-- =====================================================================
--  Inkrementelle migrationer for den LEVENDE Supabase-base.
--  schema.sql er source of truth; denne fil afstemmer en allerede
--  deployet base op til den. Alt er idempotent (IF NOT EXISTS) — sikkert
--  at køre flere gange. Kør i Supabase -> SQL Editor.
--
--  Baggrund: den levende base kan drifte fra schema.sql (manuelle ALTER'er
--  blev ikke altid anvendt). Se docs/ + memory 'live-base-schema-drift'.
-- =====================================================================

-- BEGIN 5a-cutover (#151): lukker klientvejen til den gamle identitetskerne og femarguments-
-- wrapperen, FØR resten af filen kører (filen er ikke én transaktion). Webkøens afgørelser fejler
-- lukket fra her, til den nye wrapper er oprettet længere nede; serverwritere påvirkes ikke.
DO $cutover_5a$
BEGIN
  IF to_regprocedure('public.red_decide_source_persona_identity(uuid,bigint,integer,text,jsonb)') IS NOT NULL THEN
    REVOKE ALL ON FUNCTION public.red_decide_source_persona_identity(uuid,bigint,integer,text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
  END IF;
  IF to_regprocedure('public.red_afgoer_source_persona(uuid,integer,text,bigint,text)') IS NOT NULL THEN
    REVOKE ALL ON FUNCTION public.red_afgoer_source_persona(uuid,integer,text,bigint,text) FROM PUBLIC,anon,authenticated,service_role;
  END IF;
END $cutover_5a$;
-- END 5a-cutover

-- ---- 2026-06 (tidligere manuelle tilføjelser, jf. CLAUDE.md §5) ----
-- 2026-08-18: PostgreSQL tildeler person-ID for den guarded 1939-writer.
DO $migration$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_attribute
    WHERE attrelid='public.person'::regclass AND attname='id' AND attidentity IN ('a','d')
  ) THEN
    ALTER TABLE public.person ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
    PERFORM setval(pg_get_serial_sequence('public.person','id'),
      coalesce((SELECT max(id)+1 FROM public.person),1),false);
  END IF;
END $migration$;
DO $migration$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid='public.narrative'::regclass AND attname='id' AND attidentity IN ('a','d')) THEN
    ALTER TABLE public.narrative ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
    PERFORM setval(pg_get_serial_sequence('public.narrative','id'),coalesce((SELECT max(id)+1 FROM public.narrative),1),false);
  END IF;
END $migration$;

