-- 2026-08-29: #152 — additive narrative publication event foundation
-- =====================================================================

ALTER TABLE private.source_record
  ADD COLUMN IF NOT EXISTS public_ref uuid;
ALTER TABLE private.source_record
  ALTER COLUMN public_ref SET DEFAULT gen_random_uuid();
DO $narrative_source_record_public_ref_backfill$
DECLARE
  v_append_only_trigger boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM pg_trigger
     WHERE tgrelid='private.source_record'::regclass
       AND tgname='trg_source_record_append_only'
       AND NOT tgisinternal
  ) INTO v_append_only_trigger;

  IF v_append_only_trigger THEN
    ALTER TABLE private.source_record
      DISABLE TRIGGER trg_source_record_append_only;
  END IF;
  UPDATE private.source_record
     SET public_ref=gen_random_uuid()
   WHERE public_ref IS NULL;
  IF v_append_only_trigger THEN
    ALTER TABLE private.source_record
      ENABLE TRIGGER trg_source_record_append_only;
  END IF;
END
$narrative_source_record_public_ref_backfill$;
ALTER TABLE private.source_record
  ALTER COLUMN public_ref SET NOT NULL;

DO $narrative_source_record_public_ref_unique$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid='private.source_record'::regclass
       AND conname='source_record_public_ref_key'
  ) THEN
    ALTER TABLE private.source_record
      ADD CONSTRAINT source_record_public_ref_key UNIQUE (public_ref);
  END IF;
END
$narrative_source_record_public_ref_unique$;

CREATE OR REPLACE FUNCTION public.narrative_record_contract_version()
RETURNS integer
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path=pg_catalog
AS $$ SELECT 1 $$;

CREATE TABLE IF NOT EXISTS private.narrative_legacy_publication (
  legacy_publication_ref uuid NOT NULL,
  narrative_id bigint NOT NULL,
  source_id bigint NOT NULL,
  baseline_state jsonb NOT NULL,
  baseline_sha256 text NOT NULL,
  status text NOT NULL,
  latest_event_id uuid,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT narrative_legacy_publication_pkey
    PRIMARY KEY (legacy_publication_ref),
  CONSTRAINT narrative_legacy_publication_narrative_id_key
    UNIQUE (narrative_id),
  CONSTRAINT narrative_legacy_publication_status_check
    CHECK (status IN ('grandfathered_publication','withdrawn','migrated')),
  CONSTRAINT narrative_legacy_publication_baseline_state_object_check
    CHECK (jsonb_typeof(baseline_state)='object'),
  CONSTRAINT narrative_legacy_publication_baseline_sha256_check
    CHECK (baseline_sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT narrative_legacy_publication_narrative_id_fkey
    FOREIGN KEY (narrative_id) REFERENCES public.narrative(id),
  CONSTRAINT narrative_legacy_publication_source_id_fkey
    FOREIGN KEY (source_id) REFERENCES public.source(id)
);

CREATE TABLE IF NOT EXISTS private.narrative_publication_event (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  change_set_id bigint NOT NULL,
  stream_ref uuid NOT NULL,
  stream_version integer NOT NULL,
  event_type text NOT NULL,
  binding_id uuid,
  narrative_id bigint NOT NULL,
  source_id bigint NOT NULL,
  source_record_id uuid,
  legacy_publication_ref uuid,
  decision_basis text NOT NULL,
  before_state jsonb NOT NULL,
  after_state jsonb NOT NULL,
  before_state_sha256 text NOT NULL,
  after_state_sha256 text NOT NULL,
  reversed_event_id uuid,
  decided_by uuid,
  decided_by_name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT narrative_publication_event_pkey PRIMARY KEY (id),
  CONSTRAINT narrative_publication_event_stream_version_key
    UNIQUE (stream_ref,stream_version),
  CONSTRAINT narrative_publication_event_event_type_check CHECK (
    event_type IN (
      'baseline','draft_created','draft_updated','draft_discarded','published',
      'published_revision','revalidated','withdrawn','legacy_migrated',
      'legacy_withdrawn','reversal'
    )
  ),
  CONSTRAINT narrative_publication_event_stream_version_check
    CHECK (stream_version >= 1),
  CONSTRAINT narrative_publication_event_decision_basis_check
    CHECK (btrim(decision_basis)<>''),
  CONSTRAINT narrative_publication_event_decided_by_name_check
    CHECK (btrim(decided_by_name)<>''),
  CONSTRAINT narrative_publication_event_before_state_object_check
    CHECK (jsonb_typeof(before_state)='object'),
  CONSTRAINT narrative_publication_event_after_state_object_check
    CHECK (jsonb_typeof(after_state)='object'),
  CONSTRAINT narrative_publication_event_before_state_sha256_check
    CHECK (before_state_sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT narrative_publication_event_after_state_sha256_check
    CHECK (after_state_sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT narrative_publication_event_target_check CHECK (
    (
      binding_id IS NOT NULL
      AND source_record_id IS NOT NULL
      AND legacy_publication_ref IS NULL
    ) OR (
      binding_id IS NULL
      AND source_record_id IS NULL
      AND legacy_publication_ref IS NOT NULL
    )
  ),
  CONSTRAINT narrative_publication_event_reversal_reference_check CHECK (
    (event_type='reversal')=(reversed_event_id IS NOT NULL)
  ),
  CONSTRAINT narrative_publication_event_stream_target_check CHECK (
    stream_ref=coalesce(binding_id,legacy_publication_ref)
  ),
  CONSTRAINT narrative_publication_event_change_set_id_fkey
    FOREIGN KEY (change_set_id) REFERENCES public.change_set(id),
  CONSTRAINT narrative_publication_event_binding_id_fkey
    FOREIGN KEY (binding_id) REFERENCES private.narrative_record_publication(id),
  CONSTRAINT narrative_publication_event_narrative_id_fkey
    FOREIGN KEY (narrative_id) REFERENCES public.narrative(id),
  CONSTRAINT narrative_publication_event_source_id_fkey
    FOREIGN KEY (source_id) REFERENCES public.source(id),
  CONSTRAINT narrative_publication_event_source_record_id_fkey
    FOREIGN KEY (source_record_id) REFERENCES private.source_record(id),
  CONSTRAINT narrative_publication_event_legacy_publication_ref_fkey
    FOREIGN KEY (legacy_publication_ref)
    REFERENCES private.narrative_legacy_publication(legacy_publication_ref),
  CONSTRAINT narrative_publication_event_reversed_event_id_fkey
    FOREIGN KEY (reversed_event_id) REFERENCES private.narrative_publication_event(id)
);

DO $narrative_legacy_latest_event_fk$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid='private.narrative_legacy_publication'::regclass
       AND conname='narrative_legacy_publication_latest_event_id_fkey'
  ) THEN
    ALTER TABLE private.narrative_legacy_publication
      ADD CONSTRAINT narrative_legacy_publication_latest_event_id_fkey
      FOREIGN KEY (latest_event_id)
      REFERENCES private.narrative_publication_event(id);
  END IF;
END
$narrative_legacy_latest_event_fk$;

CREATE INDEX IF NOT EXISTS narrative_publication_event_change_set_idx
  ON private.narrative_publication_event(change_set_id);
CREATE INDEX IF NOT EXISTS narrative_publication_event_binding_idx
  ON private.narrative_publication_event(binding_id) WHERE binding_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS narrative_publication_event_narrative_idx
  ON private.narrative_publication_event(narrative_id);
CREATE INDEX IF NOT EXISTS narrative_publication_event_source_idx
  ON private.narrative_publication_event(source_id);
CREATE INDEX IF NOT EXISTS narrative_publication_event_source_record_idx
  ON private.narrative_publication_event(source_record_id)
  WHERE source_record_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS narrative_publication_event_legacy_idx
  ON private.narrative_publication_event(legacy_publication_ref)
  WHERE legacy_publication_ref IS NOT NULL;
CREATE INDEX IF NOT EXISTS narrative_publication_event_reversed_idx
  ON private.narrative_publication_event(reversed_event_id)
  WHERE reversed_event_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS narrative_legacy_publication_source_idx
  ON private.narrative_legacy_publication(source_id);
CREATE INDEX IF NOT EXISTS narrative_legacy_publication_latest_event_idx
  ON private.narrative_legacy_publication(latest_event_id)
  WHERE latest_event_id IS NOT NULL;

CREATE OR REPLACE FUNCTION private.validate_narrative_publication_event()
RETURNS trigger
LANGUAGE plpgsql
SET search_path=pg_catalog
AS $$
DECLARE
  v_latest_version integer;
  v_reversed_stream uuid;
  v_reversed_version integer;
  v_target_narrative bigint;
  v_target_source bigint;
  v_target_record uuid;
  v_narrative_source bigint;
  v_record_source bigint;
BEGIN
  IF NEW.binding_id IS NOT NULL THEN
    SELECT binding.narrative_id,binding.source_record_id,
           narrative.source_id,record.source_id
      INTO v_target_narrative,v_target_record,v_narrative_source,v_record_source
      FROM private.narrative_record_publication binding
      JOIN public.narrative narrative ON narrative.id=binding.narrative_id
      JOIN private.source_record record ON record.id=binding.source_record_id
     WHERE binding.id=NEW.binding_id;
    IF NOT FOUND
       OR v_target_narrative IS DISTINCT FROM NEW.narrative_id
       OR v_target_record IS DISTINCT FROM NEW.source_record_id
       OR v_narrative_source IS DISTINCT FROM NEW.source_id
       OR v_record_source IS DISTINCT FROM NEW.source_id THEN
      RAISE EXCEPTION 'NARRATIVE_PUBLICATION_EVENT_TARGET_IDENTITY_INVALID';
    END IF;
  ELSE
    SELECT legacy.narrative_id,legacy.source_id,narrative.source_id
      INTO v_target_narrative,v_target_source,v_narrative_source
      FROM private.narrative_legacy_publication legacy
      JOIN public.narrative narrative ON narrative.id=legacy.narrative_id
     WHERE legacy.legacy_publication_ref=NEW.legacy_publication_ref;
    IF NOT FOUND
       OR v_target_narrative IS DISTINCT FROM NEW.narrative_id
       OR v_target_source IS DISTINCT FROM NEW.source_id
       OR v_narrative_source IS DISTINCT FROM NEW.source_id THEN
      RAISE EXCEPTION 'NARRATIVE_PUBLICATION_EVENT_TARGET_IDENTITY_INVALID';
    END IF;
  END IF;

  SELECT max(event.stream_version)
    INTO v_latest_version
    FROM private.narrative_publication_event event
   WHERE event.stream_ref=NEW.stream_ref;
  IF NEW.stream_version IS DISTINCT FROM coalesce(v_latest_version,0)+1 THEN
    RAISE EXCEPTION 'NARRATIVE_PUBLICATION_EVENT_STREAM_VERSION_INVALID';
  END IF;

  IF NEW.reversed_event_id IS NOT NULL THEN
    SELECT event.stream_ref,event.stream_version
      INTO v_reversed_stream,v_reversed_version
      FROM private.narrative_publication_event event
     WHERE event.id=NEW.reversed_event_id;
    IF NOT FOUND
       OR v_reversed_stream IS DISTINCT FROM NEW.stream_ref
       OR v_reversed_version>=NEW.stream_version THEN
      RAISE EXCEPTION 'NARRATIVE_PUBLICATION_REVERSAL_TARGET_INVALID';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION private.reject_narrative_publication_event_mutation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path=pg_catalog
AS $$
BEGIN
  RAISE EXCEPTION 'NARRATIVE_PUBLICATION_EVENT_APPEND_ONLY';
END
$$;

CREATE OR REPLACE FUNCTION private.validate_narrative_legacy_publication()
RETURNS trigger
LANGUAGE plpgsql
SET search_path=pg_catalog
AS $$
DECLARE
  v_latest private.narrative_publication_event%ROWTYPE;
  v_narrative_source bigint;
BEGIN
  SELECT narrative.source_id
    INTO v_narrative_source
    FROM public.narrative narrative
   WHERE narrative.id=NEW.narrative_id;
  IF NOT FOUND OR v_narrative_source IS DISTINCT FROM NEW.source_id THEN
    RAISE EXCEPTION 'NARRATIVE_LEGACY_PUBLICATION_TARGET_IDENTITY_INVALID';
  END IF;

  IF TG_OP='UPDATE' AND (
    NEW.legacy_publication_ref IS DISTINCT FROM OLD.legacy_publication_ref
    OR NEW.narrative_id IS DISTINCT FROM OLD.narrative_id
    OR NEW.source_id IS DISTINCT FROM OLD.source_id
    OR NEW.baseline_state IS DISTINCT FROM OLD.baseline_state
    OR NEW.baseline_sha256 IS DISTINCT FROM OLD.baseline_sha256
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  ) THEN
    RAISE EXCEPTION 'NARRATIVE_LEGACY_PUBLICATION_BASELINE_IMMUTABLE';
  END IF;

  IF NEW.latest_event_id IS NOT NULL THEN
    SELECT event.*
      INTO v_latest
      FROM private.narrative_publication_event event
     WHERE event.id=NEW.latest_event_id;
    IF NOT FOUND
       OR v_latest.legacy_publication_ref IS DISTINCT FROM NEW.legacy_publication_ref
       OR v_latest.narrative_id IS DISTINCT FROM NEW.narrative_id
       OR v_latest.source_id IS DISTINCT FROM NEW.source_id
       OR EXISTS (
         SELECT 1
           FROM private.narrative_publication_event later
          WHERE later.stream_ref=NEW.legacy_publication_ref
            AND later.stream_version>v_latest.stream_version
       ) THEN
      RAISE EXCEPTION 'NARRATIVE_LEGACY_PUBLICATION_LATEST_EVENT_INVALID';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_narrative_publication_event_validate
  ON private.narrative_publication_event;
CREATE TRIGGER trg_narrative_publication_event_validate
  BEFORE INSERT ON private.narrative_publication_event
  FOR EACH ROW EXECUTE FUNCTION private.validate_narrative_publication_event();
DROP TRIGGER IF EXISTS trg_narrative_publication_event_append_only
  ON private.narrative_publication_event;
CREATE TRIGGER trg_narrative_publication_event_append_only
  BEFORE UPDATE OR DELETE ON private.narrative_publication_event
  FOR EACH ROW EXECUTE FUNCTION private.reject_narrative_publication_event_mutation();
DROP TRIGGER IF EXISTS trg_narrative_legacy_publication_validate
  ON private.narrative_legacy_publication;
CREATE TRIGGER trg_narrative_legacy_publication_validate
  BEFORE INSERT OR UPDATE ON private.narrative_legacy_publication
  FOR EACH ROW EXECUTE FUNCTION private.validate_narrative_legacy_publication();

ALTER TABLE private.narrative_publication_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.narrative_legacy_publication ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE private.narrative_publication_event,
  private.narrative_legacy_publication
  FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION private.validate_narrative_publication_event(),
  private.reject_narrative_publication_event_mutation(),
  private.validate_narrative_legacy_publication()
  FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.narrative_record_contract_version()
  FROM PUBLIC,anon,authenticated,service_role;
-- #153: convert the legacy 1939 journal into the profile-bound v2 writer.
-- The identity check happens before any DDL so an ambiguous historical ledger
-- cannot be silently assigned to a profile.
BEGIN;
DO $reimport_writer_upgrade$
DECLARE
  v_source_count bigint;
  v_constraint record;
  v_constraint_name text;
  v_source record;
  v_child record;
  v_child_count bigint;
  v_payload_count bigint;
  v_terminal_source_evidence_ids uuid[];
BEGIN
  -- A legacy ledger is executable until every authorization and batch has
  -- reached a terminal state.  Take the locks and reject it before *any* DDL
  -- or profile backfill so rollback leaves the old schema and rows untouched.
  IF (SELECT relkind FROM pg_class WHERE oid=to_regclass('private.reimport_1939_authorization'))='r' THEN
    LOCK TABLE private.reimport_1939_authorization,
      private.reimport_1939_write_batch,
      private.reimport_1939_write_event,
      private.reimport_1939_name_completion_result IN ACCESS EXCLUSIVE MODE;
    -- A reimport batch that creates no person can never be activated: the v1
    -- cutover RPC requires exactly one complete name-completion child, and a
    -- child can only exist for an authorized person_create.  For such a batch
    -- `finalized` *is* the terminal state, so treating it as in-flight would
    -- reject a legitimately complete ledger forever.  The exemption is bound
    -- to evidence, not to an edition: the authorization must be consumed, the
    -- batch must declare zero person creates, and its observed counts must
    -- match both its own and its authorization's expected counts.  Every other
    -- finalized reimport batch (person_creates>0, or a count mismatch, or an
    -- expected_counts object without the key at all) remains blocking.
    SELECT coalesce(array_agg(b.id),'{}'::uuid[]) INTO v_terminal_source_evidence_ids
      FROM private.reimport_1939_write_batch b
      JOIN private.reimport_1939_authorization a ON a.id=b.authorization_id
     WHERE a.operation='reimport'
       AND a.status='consumed'
       AND b.status='finalized'
       AND b.finalized_at IS NOT NULL
       AND b.expected_counts->>'person_creates'='0'
       AND b.observed_counts IS NOT DISTINCT FROM b.expected_counts
       AND a.expected_counts IS NOT DISTINCT FROM b.expected_counts;
    IF EXISTS(SELECT 1 FROM private.reimport_1939_authorization WHERE status='issued')
       OR EXISTS(SELECT 1 FROM private.reimport_1939_write_batch WHERE status='open')
       OR EXISTS(
         SELECT 1
           FROM private.reimport_1939_write_batch b
           JOIN private.reimport_1939_authorization a ON a.id=b.authorization_id
          WHERE a.operation='reimport' AND b.status='finalized'
            AND b.id<>ALL(v_terminal_source_evidence_ids)
       ) THEN
      RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
    END IF;

    -- The old writer does not encode the source/child relationship in a
    -- relational FK.  Before assigning its rows the generic profile identity,
    -- accept only the two terminal topologies that its public v1 lifecycle can
    -- create.  In particular, a finalized child is not independently terminal:
    -- it must be the one complete name-completion child of an activated source.
    IF EXISTS(
      SELECT 1
        FROM private.reimport_1939_write_batch b
        JOIN private.reimport_1939_authorization a ON a.id=b.authorization_id
       WHERE a.operation NOT IN ('reimport','name_completion')
          OR a.status<>'consumed'
          OR (a.operation='reimport' AND b.status NOT IN ('activated','reversed')
              AND b.id<>ALL(v_terminal_source_evidence_ids))
          OR (a.operation='name_completion' AND b.status NOT IN ('finalized','reversed'))
    ) THEN
      RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
    END IF;

    -- Every child must name exactly one reimport parent in every authorized
    -- payload.  This first global check rejects orphaned/ambiguous children
    -- before the per-parent result and event checks below.
    IF EXISTS(
      SELECT 1
        FROM private.reimport_1939_write_batch child_batch
        JOIN private.reimport_1939_authorization child_authorization
          ON child_authorization.id=child_batch.authorization_id
       WHERE child_authorization.operation='name_completion'
         AND (
           jsonb_typeof(child_authorization.authorized_elements->'payloads')<>'object'
           OR NOT EXISTS(SELECT 1 FROM jsonb_object_keys(child_authorization.authorized_elements->'payloads'))
           OR (SELECT count(DISTINCT payload.value->>'source_batch_id')
                 FROM jsonb_each(child_authorization.authorized_elements->'payloads') payload)<>1
           OR NOT EXISTS(
             SELECT 1
              FROM private.reimport_1939_write_batch source_batch
               JOIN private.reimport_1939_authorization source_authorization
                 ON source_authorization.id=source_batch.authorization_id
              WHERE source_authorization.operation='reimport'
                AND source_batch.id::text=(SELECT min(payload.value->>'source_batch_id')
                                            FROM jsonb_each(child_authorization.authorized_elements->'payloads') payload)
           )
         )
    ) THEN
      RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
    END IF;

    FOR v_source IN
      SELECT source_batch.*, source_authorization.id AS authorization_id,
             source_authorization.manifest_sha256,
             source_authorization.preview_sha256,
             source_authorization.source_id,
             source_authorization.status AS authorization_status,
             source_authorization.expected_counts AS authorization_expected_counts
        FROM private.reimport_1939_write_batch source_batch
        JOIN private.reimport_1939_authorization source_authorization
          ON source_authorization.id=source_batch.authorization_id
       WHERE source_authorization.operation='reimport'
    LOOP
      SELECT count(*) INTO v_child_count
       FROM private.reimport_1939_write_batch candidate_batch
        JOIN private.reimport_1939_authorization candidate_authorization
          ON candidate_authorization.id=candidate_batch.authorization_id
       WHERE candidate_authorization.operation='name_completion'
         AND EXISTS(
           SELECT 1 FROM jsonb_each(candidate_authorization.authorized_elements->'payloads') payload
            WHERE payload.value->>'source_batch_id'=v_source.id::text
         );
      -- The exempted terminal batch has no child by construction, so it skips
      -- the parent/child contract below.  Prove that construction instead of
      -- assuming it: no child may claim it, it may only have written
      -- source_evidence events, their number must equal the authorized count,
      -- no name-completion result may reference it, and no cutover/reversal
      -- authorization may already point at it (that would be an interrupted
      -- cutover, not a terminal state).
      IF v_source.id=ANY(v_terminal_source_evidence_ids) THEN
        IF v_child_count<>0
           OR EXISTS(
             SELECT 1 FROM private.reimport_1939_write_event source_event
              WHERE source_event.batch_id=v_source.id
                AND source_event.operation<>'source_evidence'
           )
           OR (SELECT count(*) FROM private.reimport_1939_write_event source_event
                WHERE source_event.batch_id=v_source.id
                  AND source_event.operation='source_evidence')
              IS DISTINCT FROM (v_source.expected_counts->>'source_evidence')::bigint
           OR EXISTS(
             SELECT 1 FROM private.reimport_1939_name_completion_result result
              WHERE result.source_batch_id=v_source.id OR result.batch_id=v_source.id
           )
           OR EXISTS(
             SELECT 1 FROM private.reimport_1939_authorization terminal_authorization
              WHERE terminal_authorization.operation IN ('cutover','reversal')
                AND terminal_authorization.database_identity='batch:'||v_source.id::text
           )
        THEN
          RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
        END IF;
        CONTINUE;
      END IF;
      IF v_child_count<>1 THEN
        RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
      END IF;
      SELECT candidate_batch.*, candidate_authorization.id AS authorization_id,
             candidate_authorization.manifest_sha256,
             candidate_authorization.preview_sha256,
             candidate_authorization.source_id,
             candidate_authorization.status AS authorization_status,
             candidate_authorization.expected_counts AS authorization_expected_counts,
             candidate_authorization.authorized_elements
        INTO v_child
       FROM private.reimport_1939_write_batch candidate_batch
        JOIN private.reimport_1939_authorization candidate_authorization
          ON candidate_authorization.id=candidate_batch.authorization_id
       WHERE candidate_authorization.operation='name_completion'
         AND EXISTS(
           SELECT 1 FROM jsonb_each(candidate_authorization.authorized_elements->'payloads') payload
            WHERE payload.value->>'source_batch_id'=v_source.id::text
         );

      SELECT count(*) INTO v_payload_count
        FROM jsonb_object_keys(v_child.authorized_elements->'payloads');
      IF v_payload_count=0
         OR v_source.authorization_expected_counts IS DISTINCT FROM v_source.expected_counts
         OR v_source.observed_counts IS DISTINCT FROM v_source.expected_counts
         OR v_child.authorization_status<>'consumed'
         OR v_child.source_id<>v_source.source_id
         -- A v1 name-completion child has its own manifest/preview.  Its
         -- authorization instead binds the source content hash explicitly.
         OR v_child.authorized_elements->>'source_manifest_content_sha256' IS DISTINCT FROM v_source.manifest_sha256
         OR v_child.authorization_expected_counts IS DISTINCT FROM jsonb_build_object(
              'name_completions',v_payload_count,'operations',v_payload_count)
         OR v_child.expected_counts IS DISTINCT FROM v_child.authorization_expected_counts
         OR v_child.observed_counts IS DISTINCT FROM v_child.expected_counts
         OR EXISTS(
           SELECT 1 FROM jsonb_each(v_child.authorized_elements->'payloads') payload
            WHERE payload.value->>'source_batch_id' IS DISTINCT FROM v_source.id::text
         )
      THEN
        RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
      END IF;

      IF (v_source.status='activated' AND v_child.status<>'finalized')
         OR (v_source.status='reversed' AND v_child.status<>'reversed')
         OR NOT EXISTS(
           SELECT 1 FROM private.reimport_1939_authorization terminal_authorization
            WHERE terminal_authorization.operation=CASE WHEN v_source.status='activated' THEN 'cutover' ELSE 'reversal' END
              AND terminal_authorization.status='consumed'
              AND terminal_authorization.database_identity='batch:'||v_source.id::text
              AND terminal_authorization.source_id=v_source.source_id
              AND terminal_authorization.manifest_sha256=v_source.manifest_sha256
              AND terminal_authorization.preview_sha256=v_source.preview_sha256
         )
      THEN
        RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
      END IF;

      -- Bind each result and canonical-delta event to the authorized child
      -- payload and to its source person-create event.  The same evidence is
      -- retained by the old reversal RPC, so this applies to both terminal
      -- states without inventing a v2 anchor.
      IF (SELECT count(*) FROM private.reimport_1939_write_event source_event
            WHERE source_event.batch_id=v_source.id
              AND source_event.operation='person_create')<>v_payload_count
         OR (SELECT count(*) FROM private.reimport_1939_write_event child_event
              WHERE child_event.batch_id=v_child.id
                AND child_event.operation='canonical_delta')<>v_payload_count
         OR (SELECT count(*) FROM private.reimport_1939_name_completion_result result
              WHERE result.batch_id=v_child.id
                AND result.source_batch_id=v_source.id)<>v_payload_count
         OR EXISTS(
           SELECT 1
             FROM jsonb_each(v_child.authorized_elements->'payloads') payload
             LEFT JOIN private.reimport_1939_write_event source_event
               ON source_event.batch_id=v_source.id
              AND source_event.operation='person_create'
              AND source_event.element_id=payload.value->>'source_person_create_element_id'
             LEFT JOIN private.reimport_1939_write_event child_event
               ON child_event.batch_id=v_child.id
              AND child_event.operation='canonical_delta'
              AND child_event.element_id=payload.key
             LEFT JOIN private.reimport_1939_name_completion_result result
               ON result.batch_id=v_child.id
              AND result.element_id=payload.key
            WHERE payload.key IS DISTINCT FROM 'name-completion:'||(payload.value->>'source_record_key')
               OR source_event.id IS NULL
               OR source_event.canonical_person_id<>(payload.value->>'person_id')::bigint
               OR source_event.source_record_key IS DISTINCT FROM payload.value->>'source_record_key'
               OR private.reimport_1939_canonical_json_sha256(source_event.payload) IS DISTINCT FROM payload.value->>'source_payload_sha256'
               OR child_event.id IS NULL
               OR child_event.payload IS DISTINCT FROM payload.value
               OR child_event.canonical_person_id<>(payload.value->>'person_id')::bigint
               OR child_event.source_record_key IS DISTINCT FROM payload.value->>'source_record_key'
               OR result.id IS NULL
               OR result.source_batch_id<>v_source.id
               OR result.person_id<>(payload.value->>'person_id')::bigint
               OR result.source_persona_id<>(payload.value->>'source_persona_id')::uuid
               OR NOT EXISTS(
                    SELECT 1 FROM private.source_record result_record
                     WHERE result_record.id=result.source_record_id
                       AND result_record.source_id=v_source.source_id
                       AND result_record.record_key=source_event.source_record_key
                  )
               OR result.payload_sha256 IS DISTINCT FROM private.reimport_1939_canonical_json_sha256(payload.value)
               OR result.result_sha256 IS DISTINCT FROM private.reimport_1939_canonical_json_sha256(
                    jsonb_build_object('fact_id',result.fact_id,'assertion_id',result.assertion_id,
                                       'citation_id',result.citation_id,'conclusion_id',result.conclusion_id))
               OR child_event.after_sha256 IS DISTINCT FROM result.result_sha256
         )
         OR EXISTS(
           SELECT 1
             FROM private.reimport_1939_name_completion_result result
            WHERE result.batch_id=v_child.id
              AND NOT EXISTS(
                SELECT 1 FROM jsonb_each(v_child.authorized_elements->'payloads') payload
                 WHERE payload.key=result.element_id
              )
         )
      THEN
        RAISE EXCEPTION 'REIMPORT_LEGACY_IN_FLIGHT_MIGRATION_BLOCKED';
      END IF;
    END LOOP;
  END IF;
  IF to_regclass('private.reimport_authorization') IS NULL
     AND to_regclass('private.reimport_1939_authorization') IS NOT NULL THEN
    SELECT count(DISTINCT source_id) INTO v_source_count
      FROM private.reimport_1939_authorization;
    -- An empty physical v1 ledger has no profile identity to backfill, but is
    -- otherwise a safe historical upgrade: the source row is still retained
    -- for the subsequent v2 bootstrap.  Any nonempty ledger remains bound to
    -- exactly the one supported 1939 source before its rows are renamed.
    IF v_source_count<>0
       AND (v_source_count<>1 OR NOT EXISTS(SELECT 1 FROM private.reimport_1939_authorization WHERE source_id=3)) THEN
      RAISE EXCEPTION 'REIMPORT_WRITER_LEGACY_SOURCE_IDENTITY_INVALID';
    END IF;
    ALTER TABLE private.reimport_1939_authorization RENAME TO reimport_authorization;
    ALTER TABLE private.reimport_1939_write_batch RENAME TO reimport_batch;
    ALTER TABLE private.reimport_1939_write_event RENAME TO reimport_event;
    IF to_regclass('private.reimport_1939_name_completion_result') IS NOT NULL THEN
      ALTER TABLE private.reimport_1939_name_completion_result RENAME TO reimport_name_completion_result;
    END IF;
    -- Keep the owned identity sequence and append-only trigger names generic as
    -- well; the following generic trigger definitions replace their function
    -- bodies without recreating any historic ledger row.
    IF to_regclass('private.reimport_1939_write_event_id_seq') IS NOT NULL
       AND to_regclass('private.reimport_event_id_seq') IS NULL THEN
      ALTER SEQUENCE private.reimport_1939_write_event_id_seq RENAME TO reimport_event_id_seq;
    END IF;
    IF EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='private.reimport_event'::regclass AND tgname='trg_reimport_1939_event_append_only') THEN
      ALTER TRIGGER trg_reimport_1939_event_append_only ON private.reimport_event RENAME TO trg_reimport_event_append_only;
    END IF;
    IF to_regclass('private.reimport_name_completion_result') IS NOT NULL
       AND EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='private.reimport_name_completion_result'::regclass AND tgname='trg_reimport_1939_name_completion_result_append_only') THEN
      ALTER TRIGGER trg_reimport_1939_name_completion_result_append_only ON private.reimport_name_completion_result RENAME TO trg_reimport_name_completion_result_append_only;
    END IF;
    -- Constraint-backed indexes follow an ALTER TABLE ... RENAME CONSTRAINT,
    -- retaining the physical objects (and therefore historic row references)
    -- while removing the legacy relation identity.  The one long automatic
    -- name is spelled exactly as PostgreSQL generates it in fresh DDL.
    FOR v_constraint IN
      SELECT conrelid,conname
      FROM pg_constraint
      WHERE conrelid IN (
        'private.reimport_authorization'::regclass,
        'private.reimport_batch'::regclass,
        'private.reimport_event'::regclass,
        'private.reimport_name_completion_result'::regclass
      ) AND conname LIKE 'reimport_1939_%'
    LOOP
      v_constraint_name:=CASE
        WHEN v_constraint.conname='reimport_1939_name_completion_source_batch_id_person_id_sou_key'
          THEN 'reimport_name_completion_resu_source_batch_id_person_id_sou_key'
        WHEN v_constraint.conname LIKE 'reimport_1939_write_batch_%'
          THEN replace(v_constraint.conname,'reimport_1939_write_batch_','reimport_batch_')
        WHEN v_constraint.conname LIKE 'reimport_1939_write_event_%'
          THEN replace(v_constraint.conname,'reimport_1939_write_event_','reimport_event_')
        ELSE replace(v_constraint.conname,'reimport_1939_','reimport_')
      END;
      IF length(v_constraint_name)>63 THEN v_constraint_name:=left(v_constraint_name,63); END IF;
      IF NOT EXISTS(
        SELECT 1 FROM pg_constraint
        WHERE conrelid=v_constraint.conrelid AND conname=v_constraint_name
      ) THEN
        EXECUTE format('ALTER TABLE %s RENAME CONSTRAINT %I TO %I',
          v_constraint.conrelid::regclass,v_constraint.conname,v_constraint_name);
      END IF;
    END LOOP;
    -- The legacy replay index omits profile identity, so it must not survive as
    -- an over-restrictive second uniqueness rule after the generic replacement
    -- index is installed below.
    DROP INDEX IF EXISTS private.reimport_1939_write_batch_manifest_uidx;
  END IF;
END $reimport_writer_upgrade$;

CREATE OR REPLACE FUNCTION private.reimport_canonical_json_text(p_value jsonb)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_piece text; v_key text; v_item jsonb;
BEGIN
  CASE jsonb_typeof(p_value)
    WHEN 'object' THEN v_piece:='{'; FOR v_key IN SELECT jsonb_object_keys(p_value) ORDER BY 1 LOOP IF v_piece<>'{' THEN v_piece:=v_piece||','; END IF; v_piece:=v_piece||to_jsonb(v_key)::text||':'||private.reimport_canonical_json_text(p_value->v_key); END LOOP; RETURN v_piece||'}';
    WHEN 'array' THEN v_piece:='['; FOR v_item IN SELECT value FROM jsonb_array_elements(p_value) LOOP IF v_piece<>'[' THEN v_piece:=v_piece||','; END IF; v_piece:=v_piece||private.reimport_canonical_json_text(v_item); END LOOP; RETURN v_piece||']';
    ELSE RETURN p_value::text;
  END CASE;
END $$;
CREATE OR REPLACE FUNCTION private.reimport_canonical_json_sha256(p_value jsonb)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,extensions AS $$
BEGIN RETURN encode(digest(convert_to(private.reimport_canonical_json_text(p_value),'UTF8'),'sha256'),'hex'); END $$;
CREATE TABLE IF NOT EXISTS private.reimport_writer_profile (
  id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, source_id bigint NOT NULL REFERENCES public.source(id),
  profile_id text NOT NULL CHECK(btrim(profile_id)<>''), profile_version text NOT NULL CHECK(btrim(profile_version)<>''),
  profile_sha256 text NOT NULL CHECK(profile_sha256 ~ '^[0-9a-f]{64}$'), writer_config jsonb NOT NULL CHECK(jsonb_typeof(writer_config)='object'),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(source_id,profile_id),
  CHECK(profile_sha256=private.reimport_canonical_json_sha256(writer_config)),
  UNIQUE(source_id,profile_id,profile_sha256)
);
INSERT INTO private.reimport_writer_profile(source_id,profile_id,profile_version,profile_sha256,writer_config)
SELECT 3,'daa-1939-v50-production-write-v1','production-writer-v1',
  private.reimport_canonical_json_sha256(v.writer_config),v.writer_config
FROM (VALUES (
  '{"run_key_prefix":"reimport-1939-v50:","schema_version":"1939-v50-production-write-manifest-v1","extractor_version":"production-writer-v1","rendition_key":"daa-1939-calamari-r6-clean","rendition_kind":"ocr_text","rendition_metadata":{"edition":"1939"},"observation_extraction_method":"human_reviewed_1939_v50","citation_label_template":"DAA 1939 side {page_from}"}'::jsonb
)) AS v(writer_config)
WHERE EXISTS(SELECT 1 FROM public.source WHERE id=3)
ON CONFLICT(source_id,profile_id,profile_sha256) DO NOTHING;

-- The old profile row had a synthetic hash.  This one controlled migration is
-- the sole historical repair before the normal append-only trigger seals it.
DO $reimport_writer_profile_identity$
BEGIN
  IF EXISTS(
    SELECT 1 FROM private.reimport_writer_profile
     WHERE profile_sha256 IS DISTINCT FROM private.reimport_canonical_json_sha256(writer_config)
  ) THEN
    ALTER TABLE private.reimport_writer_profile DISABLE TRIGGER trg_reimport_writer_profile_append_only;
    UPDATE private.reimport_writer_profile
       SET profile_sha256=private.reimport_canonical_json_sha256(writer_config);
    ALTER TABLE private.reimport_writer_profile ENABLE TRIGGER trg_reimport_writer_profile_append_only;
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM pg_constraint c
     WHERE c.conrelid='private.reimport_writer_profile'::regclass
       AND c.contype='p'
       AND pg_get_constraintdef(c.oid) LIKE 'PRIMARY KEY (source_id, profile_id)%'
  ) THEN
    ALTER TABLE private.reimport_writer_profile DROP CONSTRAINT IF EXISTS reimport_writer_profile_pkey;
    ALTER TABLE private.reimport_writer_profile ADD CONSTRAINT reimport_writer_profile_pkey PRIMARY KEY(source_id,profile_id);
    ALTER TABLE private.reimport_writer_profile ADD CONSTRAINT reimport_writer_profile_id_key UNIQUE(id);
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM pg_constraint c
     WHERE c.conrelid='private.reimport_writer_profile'::regclass
       AND c.contype='c'
       AND pg_get_constraintdef(c.oid) LIKE '%reimport_canonical_json_sha256(writer_config)%'
  ) THEN
    ALTER TABLE private.reimport_writer_profile ADD CONSTRAINT reimport_writer_profile_config_sha256_check
      CHECK(profile_sha256=private.reimport_canonical_json_sha256(writer_config));
  END IF;
END $reimport_writer_profile_identity$;

ALTER TABLE private.reimport_authorization ADD COLUMN IF NOT EXISTS profile_id text;
ALTER TABLE private.reimport_authorization ADD COLUMN IF NOT EXISTS profile_sha256 text;
ALTER TABLE private.reimport_batch ADD COLUMN IF NOT EXISTS source_id bigint;
ALTER TABLE private.reimport_batch ADD COLUMN IF NOT EXISTS profile_id text;
ALTER TABLE private.reimport_batch ADD COLUMN IF NOT EXISTS profile_sha256 text;
UPDATE private.reimport_authorization
   SET profile_id='daa-1939-v50-production-write-v1',
       profile_sha256=(SELECT profile.profile_sha256 FROM private.reimport_writer_profile profile WHERE profile.source_id=private.reimport_authorization.source_id AND profile.profile_id='daa-1939-v50-production-write-v1')
 WHERE profile_id IS NULL OR profile_sha256 IS NULL;
UPDATE private.reimport_authorization auth_row
   SET profile_sha256=profile.profile_sha256
  FROM private.reimport_writer_profile profile
 WHERE profile.source_id=auth_row.source_id
   AND profile.profile_id=auth_row.profile_id
   AND auth_row.profile_sha256 IS DISTINCT FROM profile.profile_sha256;
UPDATE private.reimport_batch batch SET source_id=auth_row.source_id,profile_id=auth_row.profile_id,profile_sha256=auth_row.profile_sha256 FROM private.reimport_authorization auth_row WHERE auth_row.id=batch.authorization_id AND (batch.source_id IS NULL OR batch.profile_id IS NULL OR batch.profile_sha256 IS NULL);
ALTER TABLE private.reimport_authorization ALTER COLUMN profile_id SET NOT NULL;
ALTER TABLE private.reimport_authorization ALTER COLUMN profile_sha256 SET NOT NULL;
ALTER TABLE private.reimport_batch ALTER COLUMN source_id SET NOT NULL;
ALTER TABLE private.reimport_batch ALTER COLUMN profile_id SET NOT NULL;
ALTER TABLE private.reimport_batch ALTER COLUMN profile_sha256 SET NOT NULL;
ALTER TABLE private.reimport_authorization DROP CONSTRAINT IF EXISTS reimport_authorization_profile_fkey;
ALTER TABLE private.reimport_batch DROP CONSTRAINT IF EXISTS reimport_batch_profile_fkey;
ALTER TABLE private.reimport_batch DROP CONSTRAINT IF EXISTS reimport_batch_authorization_profile_fkey;
ALTER TABLE private.reimport_batch DROP CONSTRAINT IF EXISTS reimport_1939_write_batch_authorization_id_fkey;
ALTER TABLE private.reimport_batch DROP CONSTRAINT IF EXISTS reimport_batch_authorization_id_fkey;
DO $reimport_writer_constraints$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='private.reimport_authorization'::regclass AND contype='f' AND array_length(conkey,1)=3) THEN
    ALTER TABLE private.reimport_authorization ADD CONSTRAINT reimport_authorization_source_id_profile_id_profile_sha256_fkey FOREIGN KEY(source_id,profile_id,profile_sha256) REFERENCES private.reimport_writer_profile(source_id,profile_id,profile_sha256);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='private.reimport_authorization'::regclass AND contype='u' AND array_length(conkey,1)=4) THEN
    ALTER TABLE private.reimport_authorization ADD CONSTRAINT reimport_authorization_id_source_id_profile_id_profile_sha2_key UNIQUE(id,source_id,profile_id,profile_sha256);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='private.reimport_authorization'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%profile_sha256%') THEN
    ALTER TABLE private.reimport_authorization ADD CONSTRAINT reimport_authorization_profile_sha256_check CHECK(profile_sha256 ~ '^[0-9a-f]{64}$');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='private.reimport_batch'::regclass AND contype='f' AND array_length(conkey,1)=3) THEN
    ALTER TABLE private.reimport_batch ADD CONSTRAINT reimport_batch_source_id_profile_id_profile_sha256_fkey FOREIGN KEY(source_id,profile_id,profile_sha256) REFERENCES private.reimport_writer_profile(source_id,profile_id,profile_sha256);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='private.reimport_batch'::regclass AND contype='f' AND array_length(conkey,1)=4) THEN
    ALTER TABLE private.reimport_batch ADD CONSTRAINT reimport_batch_authorization_id_source_id_profile_id_profi_fkey FOREIGN KEY(authorization_id,source_id,profile_id,profile_sha256) REFERENCES private.reimport_authorization(id,source_id,profile_id,profile_sha256);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='private.reimport_batch'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%profile_sha256%') THEN
    ALTER TABLE private.reimport_batch ADD CONSTRAINT reimport_batch_profile_sha256_check CHECK(profile_sha256 ~ '^[0-9a-f]{64}$');
  END IF;
END $reimport_writer_constraints$;
ALTER TABLE private.reimport_name_completion_result ALTER COLUMN created_at SET DEFAULT clock_timestamp();
CREATE UNIQUE INDEX IF NOT EXISTS reimport_batch_profile_replay_uidx ON private.reimport_batch(source_id,profile_id,profile_sha256,manifest_sha256,preview_sha256,principal_id);

CREATE OR REPLACE FUNCTION private.reject_reimport_writer_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_TABLE_NAME='reimport_writer_profile' THEN RAISE EXCEPTION 'REIMPORT_WRITER_PROFILE_APPEND_ONLY'; END IF; IF TG_TABLE_NAME='reimport_event' THEN RAISE EXCEPTION 'REIMPORT_EVENT_APPEND_ONLY'; END IF; IF TG_TABLE_NAME='reimport_name_completion_result' THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_RESULT_APPEND_ONLY'; END IF; RAISE EXCEPTION 'REIMPORT_WRITER_APPEND_ONLY'; END $$;
DROP TRIGGER IF EXISTS trg_reimport_writer_profile_append_only ON private.reimport_writer_profile;
CREATE TRIGGER trg_reimport_writer_profile_append_only BEFORE UPDATE OR DELETE ON private.reimport_writer_profile FOR EACH ROW EXECUTE FUNCTION private.reject_reimport_writer_mutation();
DROP TRIGGER IF EXISTS trg_reimport_event_append_only ON private.reimport_event;
CREATE TRIGGER trg_reimport_event_append_only BEFORE UPDATE OR DELETE ON private.reimport_event FOR EACH ROW EXECUTE FUNCTION private.reject_reimport_writer_mutation();
DROP TRIGGER IF EXISTS trg_reimport_name_completion_result_append_only ON private.reimport_name_completion_result;
CREATE TRIGGER trg_reimport_name_completion_result_append_only BEFORE UPDATE OR DELETE ON private.reimport_name_completion_result FOR EACH ROW EXECUTE FUNCTION private.reject_reimport_writer_mutation();

