CREATE OR REPLACE FUNCTION private.lock_reimport_writer(p_source_id bigint,p_profile_id text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
  IF p_source_id IS NULL OR nullif(btrim(p_profile_id),'') IS NULL THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_LOCK_INVALID';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('daa-reimport-writer:'||p_source_id::text||':'||p_profile_id,0)
  );
END $$;
CREATE OR REPLACE FUNCTION private.validate_reimport_authorization_payload(p_expected_counts jsonb,p_authorized_elements jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_person_creates bigint; v_source_evidence bigint; v_authorized_count bigint;
BEGIN
  IF jsonb_typeof(p_expected_counts)<>'object' OR jsonb_typeof(p_authorized_elements)<>'object'
     OR jsonb_typeof(p_expected_counts->'person_creates')<>'number'
     OR jsonb_typeof(p_expected_counts->'source_evidence')<>'number'
     OR coalesce(p_expected_counts->>'person_creates','') !~ '^[0-9]+$'
     OR coalesce(p_expected_counts->>'source_evidence','') !~ '^[0-9]+$'
     OR (SELECT count(*) FROM jsonb_object_keys(p_expected_counts))<>2
     OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_expected_counts) key WHERE key NOT IN ('person_creates','source_evidence')) THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID';
  END IF;
  v_person_creates:=(p_expected_counts->>'person_creates')::bigint;
  v_source_evidence:=(p_expected_counts->>'source_evidence')::bigint;
  SELECT count(*) INTO v_authorized_count FROM jsonb_object_keys(p_authorized_elements);
  IF v_authorized_count<>(v_person_creates+v_source_evidence)
     OR EXISTS(SELECT 1 FROM jsonb_each(p_authorized_elements) element
                WHERE jsonb_typeof(element.value)<>'object'
                   OR element.key !~ '^person-create:.+$' AND element.key !~ '^source-evidence:.+$')
     OR (SELECT count(*) FROM jsonb_object_keys(p_authorized_elements) key WHERE key ~ '^person-create:.+$')<>v_person_creates
     OR (SELECT count(*) FROM jsonb_object_keys(p_authorized_elements) key WHERE key ~ '^source-evidence:.+$')<>v_source_evidence THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID';
  END IF;
END $$;
CREATE OR REPLACE FUNCTION private.require_reimport_writer_editor() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE actor uuid:=auth.uid(); BEGIN IF actor IS NULL OR public.current_rolle()<>'redaktion' THEN RAISE EXCEPTION 'REIMPORT_WRITER_ROLE_FORBIDDEN'; END IF; RETURN actor; END $$;
CREATE OR REPLACE FUNCTION private.require_reimport_open_batch(batch_id uuid) RETURNS private.reimport_batch LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ DECLARE batch private.reimport_batch%ROWTYPE; actor uuid; discovered_source_id bigint; discovered_profile_id text; BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; actor:=private.require_reimport_writer_editor(); SELECT source_id,profile_id INTO discovered_source_id,discovered_profile_id FROM private.reimport_batch WHERE id=batch_id; IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_INVALID'; END IF; PERFORM private.lock_reimport_writer(discovered_source_id,discovered_profile_id); SELECT * INTO batch FROM private.reimport_batch WHERE id=batch_id FOR UPDATE; IF NOT FOUND OR batch.source_id IS DISTINCT FROM discovered_source_id OR batch.profile_id IS DISTINCT FROM discovered_profile_id OR batch.status<>'open' OR batch.principal_id<>actor THEN RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_INVALID'; END IF; RETURN batch; END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_reimport(m text,p text,d text,s bigint,profile text,profile_hash text,c jsonb,e jsonb,n uuid,x timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ DECLARE i uuid; a uuid; BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; IF NOT EXISTS(SELECT 1 FROM private.reimport_writer_profile WHERE source_id=s AND profile_id=profile AND profile_sha256=profile_hash) THEN RAISE EXCEPTION 'REIMPORT_WRITER_PROFILE_INVALID'; END IF; IF d<>current_database() OR x<=clock_timestamp() OR jsonb_typeof(c)<>'object' OR jsonb_typeof(e)<>'object' THEN RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID'; END IF; a:=private.require_reimport_writer_editor(); INSERT INTO private.reimport_authorization(operation,manifest_sha256,preview_sha256,database_identity,source_id,profile_id,profile_sha256,expected_counts,authorized_elements,principal_id,nonce,expires_at) VALUES('reimport',m,p,d,s,profile,profile_hash,c,e,a,n,x) RETURNING id INTO i; RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.red_begin_reimport(i uuid,m text,p text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ DECLARE a private.reimport_authorization%ROWTYPE; b uuid; u uuid; BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; u:=private.require_reimport_writer_editor(); SELECT * INTO a FROM private.reimport_authorization WHERE id=i FOR UPDATE; IF NOT FOUND OR a.operation<>'reimport' OR a.status<>'issued' OR a.expires_at<=clock_timestamp() OR a.principal_id<>u OR a.manifest_sha256<>m OR a.preview_sha256<>p THEN RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID'; END IF; UPDATE private.reimport_authorization SET status='consumed',consumed_at=clock_timestamp() WHERE id=a.id; SELECT id INTO b FROM private.reimport_batch WHERE source_id=a.source_id AND profile_id=a.profile_id AND profile_sha256=a.profile_sha256 AND manifest_sha256=a.manifest_sha256 AND preview_sha256=a.preview_sha256 AND principal_id=u AND status='finalized' ORDER BY finalized_at DESC,id LIMIT 1; IF b IS NOT NULL THEN RETURN b; END IF; INSERT INTO private.reimport_batch(authorization_id,manifest_sha256,preview_sha256,source_id,profile_id,profile_sha256,principal_id,expected_counts) VALUES(a.id,a.manifest_sha256,a.preview_sha256,a.source_id,a.profile_id,a.profile_sha256,u,a.expected_counts) RETURNING id INTO b; RETURN b; END $$;
CREATE OR REPLACE FUNCTION private.ensure_reimport_source_evidence(p_batch_id uuid,p_element_id text,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,extensions AS $$
DECLARE v_batch private.reimport_batch%ROWTYPE; v_auth private.reimport_authorization%ROWTYPE; v_profile private.reimport_writer_profile%ROWTYPE;
  v_run uuid; v_rendition uuid; v_record uuid; v_occurrence uuid; v_observation uuid; v_mention uuid; v_actor uuid; v_actor_name text;
  v_span jsonb:=p_payload->'source_span'; v_page jsonb:=p_payload->'page_evidence'; v_text text:=p_payload->>'verbatim_text';
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_batch:=private.require_reimport_open_batch(p_batch_id); v_actor:=private.require_reimport_writer_editor();
  SELECT * INTO v_auth FROM private.reimport_authorization WHERE id=v_batch.authorization_id;
  SELECT * INTO v_profile FROM private.reimport_writer_profile WHERE source_id=v_batch.source_id AND profile_id=v_batch.profile_id AND profile_sha256=v_batch.profile_sha256;
  IF NOT FOUND OR v_auth.source_id<>v_batch.source_id OR v_auth.profile_id<>v_batch.profile_id OR v_auth.profile_sha256<>v_batch.profile_sha256
     OR NOT v_auth.authorized_elements ? p_element_id OR (v_auth.authorized_elements->p_element_id IS DISTINCT FROM p_payload AND v_auth.authorized_elements->p_element_id IS DISTINCT FROM (p_payload-'category')) THEN RAISE EXCEPTION 'REIMPORT_WRITER_ELEMENT_NOT_AUTHORIZED'; END IF;
  IF nullif(btrim(p_payload->>'source_record_key'),'') IS NULL OR v_span IS NULL OR v_page IS NULL OR nullif(v_text,'') IS NULL
     OR (v_span->>'char_from')::int<0 OR (v_span->>'char_to')::int<=(v_span->>'char_from')::int
     OR (v_page->>'page_from')::int<1 OR (v_page->>'page_to')::int<(v_page->>'page_from')::int
     OR p_payload->>'rendition_content_sha256' !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'REIMPORT_WRITER_SOURCE_EVIDENCE_INVALID'; END IF;
  SELECT coalesce(nullif(btrim(navn),''),nullif(btrim(email),''),v_actor::text) INTO v_actor_name FROM public.profiles WHERE id=v_actor;
  INSERT INTO private.extraction_run(source_id,run_key,schema_version,extractor_version,profile_version,input_sha256,manifest) VALUES(v_batch.source_id,(v_profile.writer_config->>'run_key_prefix')||v_batch.manifest_sha256,v_profile.writer_config->>'schema_version',v_profile.writer_config->>'extractor_version',v_profile.profile_version,v_batch.manifest_sha256,jsonb_build_object('batch_id',p_batch_id,'profile_sha256',v_batch.profile_sha256)) ON CONFLICT(source_id,run_key) DO NOTHING;
  SELECT id INTO v_run FROM private.extraction_run WHERE source_id=v_batch.source_id AND run_key=(v_profile.writer_config->>'run_key_prefix')||v_batch.manifest_sha256;
  INSERT INTO private.source_rendition(source_id,rendition_key,rendition_kind,content_sha256,metadata) VALUES(v_batch.source_id,v_profile.writer_config->>'rendition_key',v_profile.writer_config->>'rendition_kind',p_payload->>'rendition_content_sha256',v_profile.writer_config->'rendition_metadata') ON CONFLICT(source_id,rendition_key) DO NOTHING;
  SELECT id INTO v_rendition FROM private.source_rendition WHERE source_id=v_batch.source_id AND rendition_key=v_profile.writer_config->>'rendition_key';
  IF NOT EXISTS(SELECT 1 FROM private.source_rendition WHERE id=v_rendition AND content_sha256=p_payload->>'rendition_content_sha256') THEN RAISE EXCEPTION 'REIMPORT_WRITER_RENDITION_DRIFT'; END IF;
  INSERT INTO private.source_record(source_id,record_key,record_kind,created_run_id) VALUES(v_batch.source_id,p_payload->>'source_record_key',coalesce(p_payload->>'category','person'),v_run) ON CONFLICT(source_id,record_key) DO NOTHING;
  SELECT id INTO v_record FROM private.source_record WHERE source_id=v_batch.source_id AND record_key=p_payload->>'source_record_key';
  INSERT INTO private.source_record_occurrence(rendition_id,occurrence_key,page_from,page_to,char_from,char_to,verbatim_text,physical_fingerprint,structural_fingerprint,extraction_run_id) VALUES(v_rendition,p_element_id,(v_page->>'page_from')::int,(v_page->>'page_to')::int,(v_span->>'char_from')::int,(v_span->>'char_to')::int,v_text,encode(digest(v_text,'sha256'),'hex'),encode(digest(p_payload::text,'sha256'),'hex'),v_run) ON CONFLICT(rendition_id,extraction_run_id,occurrence_key) DO NOTHING;
  SELECT id INTO v_occurrence FROM private.source_record_occurrence WHERE rendition_id=v_rendition AND extraction_run_id=v_run AND occurrence_key=p_element_id;
  INSERT INTO private.source_record_anchor_event(occurrence_id,source_record_id,decision_status,evidence,version,decided_by,decided_by_name) VALUES(v_occurrence,v_record,'accepted',jsonb_build_object('batch_id',p_batch_id,'element_id',p_element_id),1,v_actor,v_actor_name) ON CONFLICT(occurrence_id,source_record_id,version) DO NOTHING;
  INSERT INTO private.source_observation(occurrence_id,observation_kind,page_from,page_to,char_from,char_to,verbatim_text,quality_status,extraction_method,extraction_run_id) VALUES(v_occurrence,coalesce(p_payload->>'category','person'),(v_page->>'page_from')::int,(v_page->>'page_to')::int,(v_span->>'char_from')::int,(v_span->>'char_to')::int,v_text,'clear',v_profile.writer_config->>'observation_extraction_method',v_run) RETURNING id INTO v_observation;
  INSERT INTO private.source_mention(observation_id,mention_kind,char_from,char_to,verbatim_text,created_run_id) VALUES(v_observation,coalesce(p_payload->>'category','person'),0,char_length(v_text),v_text,v_run) RETURNING id INTO v_mention;
  RETURN jsonb_build_object('run_id',v_run,'source_record_id',v_record,'mention_id',v_mention);
END $$;
CREATE OR REPLACE FUNCTION public.red_apply_reimport_source_evidence(b uuid,e text,p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,extensions AS $$ BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; IF p->>'disposition'<>'retain_source_only' THEN RAISE EXCEPTION 'REIMPORT_WRITER_SOURCE_EVIDENCE_INVALID'; END IF; PERFORM private.ensure_reimport_source_evidence(b,e,p); INSERT INTO private.reimport_event(batch_id,element_id,operation,source_record_key,payload,after_sha256) VALUES(b,e,'source_evidence',p->>'source_record_key',p,encode(extensions.digest(p::text,'sha256'),'hex')); END $$;
CREATE OR REPLACE FUNCTION public.red_apply_reimport_person_create(b uuid,e text,p jsonb) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,extensions AS $$ DECLARE batch private.reimport_batch%ROWTYPE; evidence jsonb; person_id bigint; persona uuid; state jsonb; result jsonb; BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; batch:=private.require_reimport_open_batch(b); IF nullif(btrim(p->>'name'),'') IS NULL OR (p->>'source_id')::bigint IS DISTINCT FROM batch.source_id OR EXISTS(SELECT 1 FROM public.person_external_id WHERE source_id=batch.source_id AND record_key=p->>'source_record_key') THEN RAISE EXCEPTION 'REIMPORT_WRITER_PERSON_CREATE_INVALID'; END IF; evidence:=private.ensure_reimport_source_evidence(b,e,p||'{"category":"person"}'::jsonb); person_id:=private.insert_person_with_receipt(true,p->>'name'); INSERT INTO public.person_external_id(person_id,source_id,record_key) VALUES(person_id,batch.source_id,p->>'source_record_key'); persona:=(p->>'source_persona_id')::uuid; INSERT INTO private.source_persona(id,source_id,persona_key,created_run_id) VALUES(persona,batch.source_id,p->>'persona_key',(evidence->>'run_id')::uuid); INSERT INTO private.source_persona_mention(persona_id,mention_id,mention_role,ordinal) VALUES(persona,(evidence->>'mention_id')::uuid,'primary',1); PERFORM private.decide_source_persona_identity(persona,person_id,0,'accepted',jsonb_build_object('batch_id',b,'profile_sha256',batch.profile_sha256),'person_create'); state:=private.narrative_record_state(person_id,batch.source_id,p->>'source_record_key',true); result:=public.red_upsert_person_narrative_record(person_id,batch.source_id,p->>'source_record_key',p->'narrative'->>'text',false,state->>'state_sha256'); INSERT INTO private.reimport_event(batch_id,element_id,operation,source_record_key,canonical_person_id,payload,after_sha256) VALUES(b,e,'person_create',p->>'source_record_key',person_id,p||jsonb_build_object('event_id',result->>'event_id','narrative_id',result->>'narrative_id','publication_state_sha256',result->>'publication_state_sha256','state_sha256',result->>'state_sha256'),result->>'state_sha256'); RETURN person_id; END $$;
CREATE OR REPLACE FUNCTION public.red_finalize_reimport(b uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ DECLARE batch private.reimport_batch%ROWTYPE; counts jsonb; BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; batch:=private.require_reimport_open_batch(b); SELECT jsonb_build_object('person_creates',count(*) FILTER(WHERE operation='person_create'),'source_evidence',count(*) FILTER(WHERE operation='source_evidence')) INTO counts FROM private.reimport_event WHERE batch_id=b; IF counts<>batch.expected_counts THEN RAISE EXCEPTION 'REIMPORT_WRITER_FINALIZE_COUNT_MISMATCH'; END IF; UPDATE private.reimport_batch SET status='finalized',observed_counts=counts,finalized_at=clock_timestamp() WHERE id=b; RETURN jsonb_build_object('batch_id',b,'status','finalized','counts',counts); END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_reimport_reversal(b uuid,n uuid,x timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_UNSUPPORTED'; END $$;
CREATE OR REPLACE FUNCTION public.red_reverse_reimport(b uuid,a uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_UNSUPPORTED'; END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_reimport_cutover(b uuid,n uuid,x timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_UNSUPPORTED'; END $$;
CREATE OR REPLACE FUNCTION public.red_activate_reimport_batch(b uuid,a uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0)); IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF; RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_UNSUPPORTED'; END $$;
ALTER TABLE private.reimport_writer_profile ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.reimport_authorization ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.reimport_batch ENABLE ROW LEVEL SECURITY;
