  TO anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION private.reimport_1939_canonical_json_sha256(p_value jsonb)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,extensions AS $$
BEGIN RETURN encode(digest(convert_to(private.reimport_1939_canonical_json_text(p_value),'UTF8'),'sha256'),'hex'); END $$;

-- Shared writer canonicalization.  The 1939 names remain below as legacy
-- aliases for the C3 surface, but generic writers must not depend on them.
CREATE OR REPLACE FUNCTION private.reimport_canonical_json_text(p_value jsonb)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_piece text; v_key text; v_item jsonb;
BEGIN
  CASE jsonb_typeof(p_value)
    WHEN 'object' THEN v_piece:='{'; FOR v_key IN SELECT jsonb_object_keys(p_value) ORDER BY 1 LOOP IF v_piece<>'{' THEN v_piece:=v_piece||','; END IF; v_piece:=v_piece||to_jsonb(v_key)::text||':'||private.reimport_canonical_json_text(p_value->v_key); END LOOP; RETURN v_piece||'}';
    WHEN 'array' THEN v_piece:='['; FOR v_item IN SELECT value FROM jsonb_array_elements(p_value) LOOP IF v_piece<>'[' THEN v_piece:=v_piece||','; END IF; v_piece:=v_piece||private.reimport_canonical_json_text(v_item); END LOOP; RETURN v_piece||']';
    ELSE RETURN p_value::text;
  END CASE;
END $$;
CREATE OR REPLACE FUNCTION private.reimport_canonical_json_sha256(p_value jsonb)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,extensions AS $$
BEGIN RETURN encode(digest(convert_to(private.reimport_canonical_json_text(p_value),'UTF8'),'sha256'),'hex'); END $$;
CREATE OR REPLACE FUNCTION private.reimport_1939_canonical_json_text(p_value jsonb)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT private.reimport_canonical_json_text(p_value) $$;
CREATE OR REPLACE FUNCTION private.reimport_1939_canonical_json_sha256(p_value jsonb)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,extensions AS $$ SELECT private.reimport_canonical_json_sha256(p_value) $$;
CREATE OR REPLACE FUNCTION private.ensure_reimport_source_evidence(p_batch_id uuid,p_element_id text,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,extensions AS $$
DECLARE v_batch private.reimport_batch%ROWTYPE; v_auth private.reimport_authorization%ROWTYPE; v_profile private.reimport_writer_profile%ROWTYPE;
  v_run uuid; v_rendition uuid; v_record uuid; v_occurrence uuid; v_observation uuid; v_mention uuid; v_actor uuid; v_actor_name text;
  v_span jsonb:=p_payload->'source_span'; v_page jsonb:=p_payload->'page_evidence'; v_text text:=p_payload->>'verbatim_text';
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_batch:=private.require_reimport_open_batch(p_batch_id); v_actor:=private.require_reimport_writer_editor();
  SELECT * INTO v_auth FROM private.reimport_authorization WHERE id=v_batch.authorization_id;
  SELECT * INTO v_profile FROM private.reimport_writer_profile WHERE source_id=v_batch.source_id AND profile_id=v_batch.profile_id AND profile_sha256=v_batch.profile_sha256;
  IF NOT FOUND OR v_auth.source_id<>v_batch.source_id OR v_auth.profile_id<>v_batch.profile_id OR v_auth.profile_sha256<>v_batch.profile_sha256
     OR NOT v_auth.authorized_elements ? p_element_id
     OR (v_auth.authorized_elements->p_element_id IS DISTINCT FROM p_payload AND v_auth.authorized_elements->p_element_id IS DISTINCT FROM (p_payload-'category')) THEN RAISE EXCEPTION 'REIMPORT_WRITER_ELEMENT_NOT_AUTHORIZED'; END IF;
  IF nullif(btrim(p_payload->>'source_record_key'),'') IS NULL OR v_span IS NULL OR v_page IS NULL OR nullif(v_text,'') IS NULL
     OR (v_span->>'char_from')::int<0 OR (v_span->>'char_to')::int<=(v_span->>'char_from')::int
     OR (v_page->>'page_from')::int<1 OR (v_page->>'page_to')::int<(v_page->>'page_from')::int
     OR p_payload->>'rendition_content_sha256' !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'REIMPORT_WRITER_SOURCE_EVIDENCE_INVALID'; END IF;
  SELECT coalesce(nullif(btrim(navn),''),nullif(btrim(email),''),v_actor::text) INTO v_actor_name FROM public.profiles WHERE id=v_actor;
  INSERT INTO private.extraction_run(source_id,run_key,schema_version,extractor_version,profile_version,input_sha256,manifest)
  VALUES(v_batch.source_id,(v_profile.writer_config->>'run_key_prefix')||v_batch.manifest_sha256,v_profile.writer_config->>'schema_version',v_profile.writer_config->>'extractor_version',v_profile.profile_version,v_batch.manifest_sha256,jsonb_build_object('batch_id',p_batch_id,'profile_sha256',v_batch.profile_sha256)) ON CONFLICT(source_id,run_key) DO NOTHING;
  SELECT id INTO v_run FROM private.extraction_run WHERE source_id=v_batch.source_id AND run_key=(v_profile.writer_config->>'run_key_prefix')||v_batch.manifest_sha256;
  IF NOT EXISTS(SELECT 1 FROM private.extraction_run WHERE id=v_run AND source_id=v_batch.source_id AND run_key=(v_profile.writer_config->>'run_key_prefix')||v_batch.manifest_sha256 AND schema_version=v_profile.writer_config->>'schema_version' AND extractor_version=v_profile.writer_config->>'extractor_version' AND profile_version=v_profile.profile_version AND input_sha256=v_batch.manifest_sha256 AND manifest=jsonb_build_object('batch_id',p_batch_id,'profile_sha256',v_batch.profile_sha256)) THEN RAISE EXCEPTION 'REIMPORT_WRITER_SOURCE_EVIDENCE_INVALID'; END IF;
  INSERT INTO private.source_rendition(source_id,rendition_key,rendition_kind,content_sha256,metadata)
  VALUES(v_batch.source_id,v_profile.writer_config->>'rendition_key',v_profile.writer_config->>'rendition_kind',p_payload->>'rendition_content_sha256',v_profile.writer_config->'rendition_metadata') ON CONFLICT(source_id,rendition_key) DO NOTHING;
  SELECT id INTO v_rendition FROM private.source_rendition WHERE source_id=v_batch.source_id AND rendition_key=v_profile.writer_config->>'rendition_key';
  IF NOT EXISTS(SELECT 1 FROM private.source_rendition WHERE id=v_rendition AND source_id=v_batch.source_id AND rendition_key=v_profile.writer_config->>'rendition_key' AND rendition_kind=v_profile.writer_config->>'rendition_kind' AND content_sha256=p_payload->>'rendition_content_sha256' AND metadata=v_profile.writer_config->'rendition_metadata') THEN RAISE EXCEPTION 'REIMPORT_WRITER_RENDITION_DRIFT'; END IF;
  INSERT INTO private.source_record(source_id,record_key,record_kind,created_run_id) VALUES(v_batch.source_id,p_payload->>'source_record_key',coalesce(p_payload->>'category','person'),v_run) ON CONFLICT(source_id,record_key) DO NOTHING;
  SELECT id INTO v_record FROM private.source_record WHERE source_id=v_batch.source_id AND record_key=p_payload->>'source_record_key';
  INSERT INTO private.source_record_occurrence(rendition_id,occurrence_key,page_from,page_to,char_from,char_to,verbatim_text,physical_fingerprint,structural_fingerprint,extraction_run_id)
  VALUES(v_rendition,p_element_id,(v_page->>'page_from')::int,(v_page->>'page_to')::int,(v_span->>'char_from')::int,(v_span->>'char_to')::int,v_text,encode(digest(v_text,'sha256'),'hex'),encode(digest(p_payload::text,'sha256'),'hex'),v_run) ON CONFLICT(rendition_id,extraction_run_id,occurrence_key) DO NOTHING;
  SELECT id INTO v_occurrence FROM private.source_record_occurrence WHERE rendition_id=v_rendition AND extraction_run_id=v_run AND occurrence_key=p_element_id;
  INSERT INTO private.source_record_anchor_event(occurrence_id,source_record_id,decision_status,evidence,version,decided_by,decided_by_name) VALUES(v_occurrence,v_record,'accepted',jsonb_build_object('batch_id',p_batch_id,'element_id',p_element_id),1,v_actor,v_actor_name) ON CONFLICT(occurrence_id,source_record_id,version) DO NOTHING;
  INSERT INTO private.source_observation(occurrence_id,observation_kind,page_from,page_to,char_from,char_to,verbatim_text,quality_status,extraction_method,extraction_run_id) VALUES(v_occurrence,coalesce(p_payload->>'category','person'),(v_page->>'page_from')::int,(v_page->>'page_to')::int,(v_span->>'char_from')::int,(v_span->>'char_to')::int,v_text,'clear',v_profile.writer_config->>'observation_extraction_method',v_run) RETURNING id INTO v_observation;
  INSERT INTO private.source_mention(observation_id,mention_kind,char_from,char_to,verbatim_text,created_run_id) VALUES(v_observation,coalesce(p_payload->>'category','person'),0,char_length(v_text),v_text,v_run) RETURNING id INTO v_mention;
  RETURN jsonb_build_object('run_id',v_run,'source_record_id',v_record,'observation_id',v_observation,'mention_id',v_mention);
END $$;

-- Task 2 initially installed compact parameter names. PostgreSQL does not let
-- CREATE OR REPLACE rename input parameters, so replace those transitional
-- bodies transactionally before installing the complete generic writer below.
DROP FUNCTION IF EXISTS public.red_authorize_reimport(text,text,text,bigint,text,text,jsonb,jsonb,uuid,timestamptz);
DROP FUNCTION IF EXISTS public.red_begin_reimport(uuid,text,text);
DROP FUNCTION IF EXISTS public.red_apply_reimport_source_evidence(uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_apply_reimport_person_create(uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_finalize_reimport(uuid);
DROP FUNCTION IF EXISTS public.red_authorize_reimport_reversal(uuid,uuid,timestamptz);
DROP FUNCTION IF EXISTS public.red_reverse_reimport(uuid,uuid);
DROP FUNCTION IF EXISTS public.red_authorize_reimport_cutover(uuid,uuid,timestamptz);
DROP FUNCTION IF EXISTS public.red_activate_reimport_batch(uuid,uuid);

CREATE OR REPLACE FUNCTION public.red_authorize_reimport(p_manifest_sha256 text,p_preview_sha256 text,p_database_identity text,p_source_id bigint,p_profile_id text,p_profile_sha256 text,p_expected_counts jsonb,p_authorized_elements jsonb,p_nonce uuid,p_expires_at timestamptz)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_id uuid; v_actor uuid;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  IF EXISTS(SELECT 1 FROM private.reimport_writer_profile WHERE source_id=p_source_id AND profile_id=p_profile_id AND profile_sha256 IS DISTINCT FROM p_profile_sha256) THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_PROFILE_HASH_INVALID';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM private.reimport_writer_profile WHERE source_id=p_source_id AND profile_id=p_profile_id AND profile_sha256=p_profile_sha256 AND profile_sha256=private.reimport_canonical_json_sha256(writer_config)) THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_PROFILE_INVALID';
  END IF;
  IF p_manifest_sha256 !~ '^[0-9a-f]{64}$' OR p_preview_sha256 !~ '^[0-9a-f]{64}$' OR p_nonce IS NULL OR p_database_identity IS DISTINCT FROM jsonb_build_object('database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text)::text OR p_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID'; END IF;
  PERFORM private.validate_reimport_authorization_payload(p_expected_counts,p_authorized_elements);
  PERFORM private.lock_reimport_writer(p_source_id,p_profile_id);
  v_actor:=private.require_reimport_writer_editor();
  INSERT INTO private.reimport_authorization(operation,manifest_sha256,preview_sha256,database_identity,source_id,profile_id,profile_sha256,expected_counts,authorized_elements,principal_id,nonce,expires_at) VALUES('reimport',p_manifest_sha256,p_preview_sha256,p_database_identity,p_source_id,p_profile_id,p_profile_sha256,p_expected_counts,p_authorized_elements,v_actor,p_nonce,p_expires_at) RETURNING id INTO v_id;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.red_preflight_reimport_authorization(p_authorization_id uuid,p_manifest_sha256 text,p_preview_sha256 text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_auth private.reimport_authorization%ROWTYPE; v_actor uuid; v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_actor:=private.require_reimport_writer_editor();
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_authorization WHERE id=p_authorization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID'; END IF;
  PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id);
  SELECT * INTO v_auth FROM private.reimport_authorization WHERE id=p_authorization_id FOR UPDATE;
  IF NOT FOUND OR v_auth.source_id IS DISTINCT FROM v_discovered_source_id OR v_auth.profile_id IS DISTINCT FROM v_discovered_profile_id OR v_auth.operation<>'reimport' OR v_auth.status<>'issued' OR v_auth.expires_at<=clock_timestamp() OR v_auth.principal_id<>v_actor
     OR v_auth.manifest_sha256<>p_manifest_sha256 OR v_auth.preview_sha256<>p_preview_sha256
     OR v_auth.database_identity IS DISTINCT FROM jsonb_build_object('database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text)::text THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID';
  END IF;
  RETURN jsonb_build_object('authorization_id',v_auth.id,'database_identity',v_auth.database_identity,
    'source',jsonb_build_object('id',v_auth.source_id,'profile_id',v_auth.profile_id,'profile_sha256',v_auth.profile_sha256),
    'manifest_sha256',v_auth.manifest_sha256,'preview_sha256',v_auth.preview_sha256);
END $$;

REVOKE ALL ON FUNCTION public.red_preflight_reimport_authorization(uuid,text,text)
  FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.red_preflight_reimport_authorization(uuid,text,text)
  TO authenticated;

CREATE OR REPLACE FUNCTION public.red_begin_reimport(p_authorization_id uuid,p_manifest_sha256 text,p_preview_sha256 text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_auth private.reimport_authorization%ROWTYPE; v_replay private.reimport_batch%ROWTYPE; v_replay_auth private.reimport_authorization%ROWTYPE; v_id uuid; v_actor uuid; v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_actor:=private.require_reimport_writer_editor();
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_authorization WHERE id=p_authorization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID'; END IF;
  PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id);
  SELECT * INTO v_auth FROM private.reimport_authorization WHERE id=p_authorization_id FOR UPDATE;
  IF NOT FOUND OR v_auth.source_id IS DISTINCT FROM v_discovered_source_id OR v_auth.profile_id IS DISTINCT FROM v_discovered_profile_id OR v_auth.operation<>'reimport' OR v_auth.status<>'issued' OR v_auth.expires_at<=clock_timestamp() OR v_auth.principal_id<>v_actor OR v_auth.manifest_sha256<>p_manifest_sha256 OR v_auth.preview_sha256<>p_preview_sha256 OR v_auth.database_identity IS DISTINCT FROM jsonb_build_object('database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text)::text THEN RAISE EXCEPTION 'REIMPORT_WRITER_AUTHORIZATION_INVALID'; END IF;
  SELECT * INTO v_replay FROM private.reimport_batch WHERE source_id=v_auth.source_id AND profile_id=v_auth.profile_id AND profile_sha256=v_auth.profile_sha256 AND manifest_sha256=v_auth.manifest_sha256 AND preview_sha256=v_auth.preview_sha256 AND principal_id=v_actor AND status='finalized' ORDER BY finalized_at DESC,id LIMIT 1 FOR UPDATE;
  IF FOUND THEN
    SELECT * INTO v_replay_auth FROM private.reimport_authorization WHERE id=v_replay.authorization_id;
    IF NOT FOUND OR v_replay.expected_counts IS DISTINCT FROM v_auth.expected_counts OR v_replay_auth.authorized_elements IS DISTINCT FROM v_auth.authorized_elements THEN
      RAISE EXCEPTION 'REIMPORT_WRITER_REPLAY_DRIFT';
    END IF;
    UPDATE private.reimport_authorization SET status='consumed',consumed_at=clock_timestamp() WHERE id=v_auth.id;
    RETURN v_replay.id;
  END IF;
  UPDATE private.reimport_authorization SET status='consumed',consumed_at=clock_timestamp() WHERE id=v_auth.id;
  INSERT INTO private.reimport_batch(authorization_id,manifest_sha256,preview_sha256,source_id,profile_id,profile_sha256,principal_id,expected_counts) VALUES(v_auth.id,v_auth.manifest_sha256,v_auth.preview_sha256,v_auth.source_id,v_auth.profile_id,v_auth.profile_sha256,v_actor,v_auth.expected_counts) RETURNING id INTO v_id;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.red_apply_reimport_source_evidence(p_batch_id uuid,p_element_id text,p_payload jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,extensions AS $$
DECLARE v_batch private.reimport_batch%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_batch:=private.require_reimport_open_batch(p_batch_id);
  PERFORM private.lock_reimport_writer(v_batch.source_id,v_batch.profile_id);
  IF p_payload->>'disposition'<>'retain_source_only' THEN RAISE EXCEPTION 'REIMPORT_WRITER_SOURCE_EVIDENCE_INVALID'; END IF;
  PERFORM private.ensure_reimport_source_evidence(p_batch_id,p_element_id,p_payload);
  INSERT INTO private.reimport_event(batch_id,element_id,operation,source_record_key,payload,after_sha256) VALUES(p_batch_id,p_element_id,'source_evidence',p_payload->>'source_record_key',p_payload,encode(digest(p_payload::text,'sha256'),'hex'));
END $$;

CREATE OR REPLACE FUNCTION public.red_apply_reimport_person_create(p_batch_id uuid,p_element_id text,p_payload jsonb)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private,extensions AS $$
DECLARE v_batch private.reimport_batch%ROWTYPE; v_evidence jsonb; v_person_id bigint; v_persona uuid; v_state jsonb; v_narrative jsonb; v_record_placement uuid; v_record_placement_count bigint; v_persona_placement uuid; v_placement_version integer; v_identity_version integer; v_payload_sha text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_batch:=private.require_reimport_open_batch(p_batch_id);
  PERFORM private.lock_reimport_writer(v_batch.source_id,v_batch.profile_id);
  IF nullif(btrim(p_payload->>'name'),'') IS NULL OR (p_payload->>'source_id')::bigint IS DISTINCT FROM v_batch.source_id OR p_payload->>'placement_role' NOT IN ('principal_member','co_principal') OR p_payload->>'placement_basis_sha256' !~ '^[0-9a-f]{64}$' OR p_payload->>'placement_review_sha256' !~ '^[0-9a-f]{64}$' OR p_payload->>'placement_decision_sha256' !~ '^[0-9a-f]{64}$' OR EXISTS(SELECT 1 FROM public.person_external_id WHERE source_id=v_batch.source_id AND record_key=p_payload->>'source_record_key') THEN RAISE EXCEPTION 'REIMPORT_WRITER_PERSON_CREATE_INVALID'; END IF;
  v_evidence:=private.ensure_reimport_source_evidence(p_batch_id,p_element_id,p_payload||'{"category":"person"}'::jsonb);
  SELECT count(*) INTO v_record_placement_count FROM private.source_record_placement_current placement WHERE placement.source_record_id=(v_evidence->>'source_record_id')::uuid AND placement.decision_status='accepted';
  IF v_record_placement_count<>1 THEN RAISE EXCEPTION 'REIMPORT_WRITER_PERSON_CREATE_INVALID'; END IF;
  SELECT placement.id INTO v_record_placement FROM private.source_record_placement_current placement JOIN private.source_record record ON record.id=placement.source_record_id WHERE placement.id=(p_payload->>'source_record_placement_id')::uuid AND placement.decision_status='accepted' AND record.id=(v_evidence->>'source_record_id')::uuid AND record.source_id=v_batch.source_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_PERSON_CREATE_INVALID'; END IF;
  PERFORM 1 FROM private.source_record_placement WHERE id=v_record_placement FOR UPDATE;
  PERFORM 1 FROM private.source_record WHERE id=(v_evidence->>'source_record_id')::uuid FOR UPDATE;
  v_payload_sha:=private.reimport_canonical_json_sha256(p_payload);
  v_person_id:=private.insert_person_with_receipt(true,NULL);
  INSERT INTO public.person_external_id(person_id,source_id,record_key) VALUES(v_person_id,v_batch.source_id,p_payload->>'source_record_key');
  v_persona:=(p_payload->>'source_persona_id')::uuid;
  INSERT INTO private.source_persona(id,source_id,persona_key,created_run_id) VALUES(v_persona,v_batch.source_id,p_payload->>'persona_key',(v_evidence->>'run_id')::uuid);
  INSERT INTO private.source_persona_mention(persona_id,mention_id,mention_role,ordinal) VALUES(v_persona,(v_evidence->>'mention_id')::uuid,'primary',1);
  v_persona_placement:=private.propose_source_persona_placement(v_persona,v_record_placement,p_payload->>'placement_role',(v_evidence->>'observation_id')::uuid,jsonb_build_object('batch_id',p_batch_id,'authorized_payload_sha256',v_payload_sha,'basis_sha256',p_payload->>'placement_basis_sha256'),'reimport writer');
  v_placement_version:=public.red_decide_source_persona_placement(v_persona_placement,1,'accepted',jsonb_build_object('batch_id',p_batch_id,'review_sha256',p_payload->>'placement_review_sha256','decision_sha256',p_payload->>'placement_decision_sha256'));
  v_identity_version:=private.decide_source_persona_identity(v_persona,v_person_id,0,'accepted',jsonb_build_object('batch_id',p_batch_id,'profile_sha256',v_batch.profile_sha256,'placement_id',v_persona_placement),'person_create');
  v_state:=private.narrative_record_state(v_person_id,v_batch.source_id,p_payload->>'source_record_key',true);
  IF v_state->>'eligibility_status'<>'eligible' OR v_state->>'blocking_reason' IS NOT NULL OR v_state->>'authority_kind'<>'accepted_identity'
     OR v_state #> '{publication_state,target}' IS DISTINCT FROM jsonb_build_object('person_id',v_person_id,'source_id',v_batch.source_id,'record_key',p_payload->>'source_record_key','source_record_id',(v_evidence->>'source_record_id')::uuid,'source_record_ref',(v_state #>> '{publication_state,target,source_record_ref}')::uuid)
     OR v_state #> '{publication_state,authority,identity_people}' IS DISTINCT FROM jsonb_build_array(v_person_id) THEN RAISE EXCEPTION 'REIMPORT_WRITER_PERSON_CREATE_INVALID'; END IF;
  v_narrative:=public.red_upsert_person_narrative_record(v_person_id,v_batch.source_id,p_payload->>'source_record_key',p_payload->'narrative'->>'text',false,v_state->>'state_sha256');
  INSERT INTO private.reimport_event(batch_id,element_id,operation,source_record_key,canonical_person_id,payload,after_sha256) VALUES(p_batch_id,p_element_id,'person_create',p_payload->>'source_record_key',v_person_id,p_payload||jsonb_build_object('authorized_payload_sha256',v_payload_sha,'record_placement_id',v_record_placement,'persona_placement_id',v_persona_placement,'persona_placement_version',v_placement_version,'identity_version',v_identity_version,'event_id',v_narrative->>'event_id','narrative_id',v_narrative->>'narrative_id','publication_state_sha256',v_narrative->>'publication_state_sha256','state_sha256',v_narrative->>'state_sha256'),v_narrative->>'state_sha256');
  RETURN v_person_id;
END $$;

CREATE OR REPLACE FUNCTION public.red_finalize_reimport(p_batch_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_batch private.reimport_batch%ROWTYPE; v_counts jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_batch:=private.require_reimport_open_batch(p_batch_id);
  PERFORM private.lock_reimport_writer(v_batch.source_id,v_batch.profile_id);
  SELECT jsonb_build_object('person_creates',count(*) FILTER(WHERE operation='person_create'),'source_evidence',count(*) FILTER(WHERE operation='source_evidence')) INTO v_counts FROM private.reimport_event WHERE batch_id=p_batch_id;
  IF v_counts<>v_batch.expected_counts THEN RAISE EXCEPTION 'REIMPORT_WRITER_FINALIZE_COUNT_MISMATCH'; END IF;
  UPDATE private.reimport_batch SET status='finalized',observed_counts=v_counts,finalized_at=clock_timestamp() WHERE id=p_batch_id;
  RETURN jsonb_build_object('batch_id',p_batch_id,'status','finalized','counts',v_counts);
END $$;

CREATE OR REPLACE FUNCTION public.red_reimport_batch_result(p_authorization_id uuid,p_batch_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE
  v_authorization private.reimport_authorization%ROWTYPE;
  v_batch private.reimport_batch%ROWTYPE;
  v_actor uuid;
  v_expected_person_creates bigint;
  v_person_create_count bigint;
  v_valid_person_create_count bigint;
  v_distinct_record_key_count bigint;
  v_distinct_element_id_count bigint;
  v_distinct_person_id_count bigint;
  v_expected_source_evidence bigint;
  v_authorized_element_count bigint;
  v_person_id_map jsonb;
  v_discovered_source_id bigint;
  v_discovered_profile_id text;
  v_discovered_auth_source_id bigint;
  v_discovered_auth_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN
    RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED';
  END IF;
  v_actor:=private.require_reimport_writer_editor();
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id
    FROM private.reimport_batch WHERE id=p_batch_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID'; END IF;
  SELECT source_id,profile_id INTO v_discovered_auth_source_id,v_discovered_auth_profile_id
    FROM private.reimport_authorization WHERE id=p_authorization_id;
  IF NOT FOUND OR v_discovered_auth_source_id IS DISTINCT FROM v_discovered_source_id OR v_discovered_auth_profile_id IS DISTINCT FROM v_discovered_profile_id THEN RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID'; END IF;
  PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id);
  SELECT * INTO v_authorization FROM private.reimport_authorization WHERE id=p_authorization_id FOR UPDATE;
  IF NOT FOUND OR v_authorization.operation<>'reimport'
     OR v_authorization.status<>'consumed' OR v_authorization.principal_id<>v_actor THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID';
  END IF;
  SELECT * INTO v_batch FROM private.reimport_batch WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND
     OR v_batch.source_id IS DISTINCT FROM v_discovered_source_id
     OR v_batch.profile_id IS DISTINCT FROM v_discovered_profile_id
     OR v_authorization.source_id IS DISTINCT FROM v_discovered_auth_source_id
     OR v_authorization.profile_id IS DISTINCT FROM v_discovered_auth_profile_id
     OR v_batch.principal_id<>v_actor
     OR v_batch.source_id<>v_authorization.source_id
     OR v_batch.profile_id<>v_authorization.profile_id
     OR v_batch.profile_sha256<>v_authorization.profile_sha256
     OR v_batch.manifest_sha256<>v_authorization.manifest_sha256
     OR v_batch.preview_sha256<>v_authorization.preview_sha256 THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID';
  END IF;
  IF v_batch.status='open' THEN
    IF v_batch.authorization_id<>v_authorization.id THEN
      RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID';
    END IF;
    RETURN jsonb_build_object('batch_id',v_batch.id,'status','open','replayed',false,'person_id_map','{}'::jsonb);
  END IF;
  IF v_batch.status<>'finalized' OR v_batch.finalized_at IS NULL
     OR v_batch.observed_counts IS DISTINCT FROM v_batch.expected_counts
     OR jsonb_typeof(v_batch.expected_counts)<>'object'
     OR coalesce(v_batch.expected_counts->>'person_creates','') !~ '^[0-9]+$'
     OR coalesce(v_batch.expected_counts->>'source_evidence','') !~ '^[0-9]+$'
     OR (SELECT count(*) FROM jsonb_object_keys(v_batch.expected_counts))<>2
     OR EXISTS(SELECT 1 FROM jsonb_object_keys(v_batch.expected_counts) key WHERE key NOT IN ('person_creates','source_evidence')) THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID';
  END IF;
  v_expected_person_creates:=(v_batch.expected_counts->>'person_creates')::bigint;
  v_expected_source_evidence:=(v_batch.expected_counts->>'source_evidence')::bigint;
  SELECT count(*) INTO v_authorized_element_count FROM jsonb_object_keys(v_authorization.authorized_elements);
  IF v_authorized_element_count<>(v_expected_person_creates+v_expected_source_evidence)
     OR EXISTS(SELECT 1 FROM jsonb_each(v_authorization.authorized_elements) item
                WHERE jsonb_typeof(item.value)<>'object'
                   OR (item.key !~ '^person-create:' AND item.key !~ '^source-evidence:'))
     OR EXISTS(SELECT 1 FROM jsonb_object_keys(v_authorization.authorized_elements) key
                LEFT JOIN private.reimport_event event ON event.batch_id=v_batch.id AND event.element_id=key
                WHERE event.id IS NULL)
     OR EXISTS(SELECT 1 FROM private.reimport_event event
                LEFT JOIN jsonb_object_keys(v_authorization.authorized_elements) key ON key=event.element_id
                WHERE event.batch_id=v_batch.id AND event.operation IN ('person_create','source_evidence') AND key IS NULL) THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID';
  END IF;
  SELECT count(*),
    count(*) FILTER (WHERE e.source_record_key IS NOT NULL AND e.source_record_key<>''
      AND e.canonical_person_id IS NOT NULL AND e.canonical_person_id>0
      AND e.element_id='person-create:'||e.source_record_key
      AND e.payload->>'source_record_key'=e.source_record_key),
    count(DISTINCT e.source_record_key),count(DISTINCT e.element_id),count(DISTINCT e.canonical_person_id),
    coalesce(jsonb_object_agg(e.source_record_key,e.canonical_person_id ORDER BY e.element_id),'{}'::jsonb)
  INTO v_person_create_count,v_valid_person_create_count,v_distinct_record_key_count,
    v_distinct_element_id_count,v_distinct_person_id_count,v_person_id_map
  FROM private.reimport_event e
  WHERE e.batch_id=v_batch.id AND e.operation='person_create';
  IF v_person_create_count<>v_expected_person_creates
     OR v_valid_person_create_count<>v_person_create_count
     OR v_distinct_record_key_count<>v_person_create_count
     OR v_distinct_element_id_count<>v_person_create_count
     OR v_distinct_person_id_count<>v_person_create_count THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_BATCH_RESULT_INVALID';
  END IF;
  RETURN jsonb_build_object('batch_id',v_batch.id,'status','finalized','replayed',true,'person_id_map',v_person_id_map);
END $$;

REVOKE ALL ON FUNCTION public.red_reimport_batch_result(uuid,uuid)
  FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.red_reimport_batch_result(uuid,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION private.validate_reimport_name_completion(p_authorization_id uuid,p_source_batch_id uuid,p_manifest_sha256 text,p_payloads jsonb)
RETURNS private.reimport_batch LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE a private.reimport_authorization%ROWTYPE; b private.reimport_batch%ROWTYPE; sa private.reimport_authorization%ROWTYPE;
  k text; p jsonb; e private.reimport_event%ROWTYPE; expected_count bigint;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_source_batch_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id);
  SELECT * INTO a FROM private.reimport_authorization WHERE id=p_authorization_id FOR UPDATE;
  SELECT * INTO b FROM private.reimport_batch WHERE id=p_source_batch_id FOR UPDATE;
  IF NOT FOUND OR b.source_id IS DISTINCT FROM v_discovered_source_id OR b.profile_id IS DISTINCT FROM v_discovered_profile_id OR a.operation<>'name_completion' OR a.status<>'issued' OR a.principal_id<>private.require_reimport_writer_editor() OR a.database_identity IS DISTINCT FROM jsonb_build_object('database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text)::text
     OR a.expires_at<=clock_timestamp() OR a.manifest_sha256<>p_manifest_sha256 OR b.status<>'finalized'
     OR a.source_id<>b.source_id OR a.profile_id<>b.profile_id OR a.profile_sha256<>b.profile_sha256
     OR a.authorized_elements->'source_batch_id' IS DISTINCT FROM to_jsonb(p_source_batch_id)
     OR a.authorized_elements->'payloads' IS DISTINCT FROM p_payloads THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  SELECT * INTO sa FROM private.reimport_authorization WHERE id=b.authorization_id;
  IF NOT FOUND OR sa.operation<>'reimport' OR sa.source_id<>b.source_id OR sa.profile_id<>b.profile_id OR sa.profile_sha256<>b.profile_sha256 OR sa.manifest_sha256<>b.manifest_sha256 OR sa.preview_sha256<>b.preview_sha256
     OR a.authorized_elements->>'source_manifest_content_sha256'<>b.manifest_sha256
     OR a.authorized_elements->>'source_manifest_bytes_sha256'<>b.preview_sha256
     OR jsonb_typeof(p_payloads)<>'object' THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  IF jsonb_typeof(a.expected_counts)<>'object'
     OR jsonb_typeof(a.expected_counts->'name_completions')<>'number'
     OR jsonb_typeof(a.expected_counts->'operations')<>'number'
     OR coalesce(a.expected_counts->>'name_completions','') !~ '^[0-9]+$'
     OR coalesce(a.expected_counts->>'operations','') !~ '^[0-9]+$'
     OR (SELECT count(*) FROM jsonb_object_keys(a.expected_counts))<>2
     OR EXISTS(SELECT 1 FROM jsonb_object_keys(a.expected_counts) key
                WHERE key NOT IN ('name_completions','operations')) THEN
    RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID';
  END IF;
  IF (a.expected_counts->>'name_completions')::numeric > 9223372036854775807 THEN
    RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID';
  END IF;
  expected_count:=(a.expected_counts->>'name_completions')::bigint;
  IF a.expected_counts->>'operations' IS DISTINCT FROM expected_count::text
     OR (SELECT count(*) FROM jsonb_object_keys(p_payloads))<>expected_count THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  PERFORM 1 FROM public.person q JOIN jsonb_each(p_payloads) j ON q.id=(j.value->>'person_id')::bigint ORDER BY q.id FOR UPDATE OF q;
  PERFORM 1 FROM private.source_record r JOIN jsonb_each(p_payloads) j ON r.source_id=b.source_id AND r.record_key=j.value->>'source_record_key' ORDER BY r.id FOR UPDATE OF r;
  PERFORM 1 FROM private.source_persona sp JOIN jsonb_each(p_payloads) j ON sp.id=(j.value->>'source_persona_id')::uuid ORDER BY sp.id FOR UPDATE OF sp;
  PERFORM 1 FROM private.source_persona_identity si JOIN jsonb_each(p_payloads) j ON si.source_persona_id=(j.value->>'source_persona_id')::uuid ORDER BY si.source_persona_id FOR UPDATE OF si;
  FOR k,p IN SELECT key,value FROM jsonb_each(p_payloads) LOOP
    IF k<>('name-completion:'||(p->>'source_record_key')) OR p->>'source_batch_id'<>b.id::text
       OR (p->>'source_id')::bigint IS DISTINCT FROM b.source_id OR nullif(btrim(p->>'name'),'') IS NULL
       OR p->>'source_payload_sha256' !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(p->'page_evidence') IS DISTINCT FROM 'object'
       OR jsonb_typeof(p->'page_evidence'->'page_from') IS DISTINCT FROM 'number'
       OR NOT (CASE WHEN coalesce(p#>>'{page_evidence,page_from}','') ~ '^[0-9]+$'
                    THEN ((p#>>'{page_evidence,page_from}')::numeric BETWEEN 1 AND 2147483647)
                    ELSE false END) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
    SELECT * INTO e FROM private.reimport_event WHERE batch_id=b.id AND element_id=p->>'source_person_create_element_id' AND operation='person_create';
    IF NOT FOUND OR e.canonical_person_id IS DISTINCT FROM (p->>'person_id')::bigint OR e.source_record_key IS DISTINCT FROM p->>'source_record_key'
       OR e.payload->>'authorized_payload_sha256' IS DISTINCT FROM p->>'source_payload_sha256'
       OR e.payload->>'source_persona_id' IS DISTINCT FROM p->>'source_persona_id'
       OR NOT EXISTS(SELECT 1 FROM private.source_record r WHERE r.source_id=b.source_id AND r.record_key=p->>'source_record_key')
       OR NOT EXISTS(SELECT 1 FROM private.source_persona sp JOIN private.source_persona_identity si ON si.source_persona_id=sp.id AND si.decision_status='accepted'
                       WHERE sp.id=(p->>'source_persona_id')::uuid AND sp.source_id=b.source_id AND si.canonical_person_id=(p->>'person_id')::bigint)
       OR NOT EXISTS(SELECT 1 FROM public.person q WHERE q.id=(p->>'person_id')::bigint AND q.staged AND q.visning_navn IS NULL)
       OR EXISTS(SELECT 1 FROM public.fact f WHERE f.subjekt_type='person' AND f.subjekt_id=(p->>'person_id')::bigint AND f.faktatype='navn') THEN
      RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID';
    END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=b.id AND parent.operation='person_create' AND NOT EXISTS(SELECT 1 FROM jsonb_each(p_payloads) child WHERE child.value->>'source_person_create_element_id'=parent.element_id AND (child.value->>'person_id')::bigint=parent.canonical_person_id AND child.value->>'source_record_key'=parent.source_record_key))
     OR EXISTS(SELECT 1 FROM jsonb_each(p_payloads) child WHERE NOT EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=b.id AND parent.operation='person_create' AND parent.element_id=child.value->>'source_person_create_element_id' AND parent.canonical_person_id=(child.value->>'person_id')::bigint AND parent.source_record_key=child.value->>'source_record_key')) THEN
    RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID';
  END IF;
  RETURN b;
END $$;

CREATE OR REPLACE FUNCTION public.red_lock_reimport_name_completion(p_manifest_sha256 text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  PERFORM private.require_reimport_writer_editor();
END $$;

CREATE OR REPLACE FUNCTION public.red_authorize_reimport_name_completion(p_manifest_sha256 text,p_source_batch_id uuid,p_source_manifest_bytes_sha256 text,p_source_manifest_content_sha256 text,p_expected_counts jsonb,p_payloads jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE b private.reimport_batch%ROWTYPE; a private.reimport_authorization%ROWTYPE; v_id uuid; v_actor uuid;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  IF p_manifest_sha256 !~ '^[0-9a-f]{64}$' OR p_source_manifest_bytes_sha256 !~ '^[0-9a-f]{64}$' OR p_source_manifest_content_sha256 !~ '^[0-9a-f]{64}$' OR jsonb_typeof(p_expected_counts)<>'object' OR jsonb_typeof(p_payloads)<>'object' THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  v_actor:=private.require_reimport_writer_editor();
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_source_batch_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id);
  SELECT * INTO b FROM private.reimport_batch WHERE id=p_source_batch_id FOR UPDATE;
  SELECT * INTO a FROM private.reimport_authorization WHERE id=b.authorization_id FOR UPDATE;
  IF NOT FOUND OR b.source_id IS DISTINCT FROM v_discovered_source_id OR b.profile_id IS DISTINCT FROM v_discovered_profile_id OR b.status<>'finalized' OR a.operation<>'reimport' OR a.principal_id<>v_actor OR b.source_id<>a.source_id OR b.profile_id<>a.profile_id OR b.profile_sha256<>a.profile_sha256 OR b.preview_sha256<>p_source_manifest_bytes_sha256 OR b.manifest_sha256<>p_source_manifest_content_sha256 THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  INSERT INTO private.reimport_authorization(operation,manifest_sha256,preview_sha256,database_identity,source_id,profile_id,profile_sha256,expected_counts,authorized_elements,principal_id,nonce,expires_at)
  VALUES('name_completion',p_manifest_sha256,p_source_manifest_content_sha256,jsonb_build_object('database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text)::text,b.source_id,b.profile_id,b.profile_sha256,p_expected_counts,jsonb_build_object('source_batch_id',p_source_batch_id,'payloads',p_payloads,'source_manifest_bytes_sha256',p_source_manifest_bytes_sha256,'source_manifest_content_sha256',p_source_manifest_content_sha256),v_actor,gen_random_uuid(),clock_timestamp()+interval '5 minutes') RETURNING id INTO v_id;
  PERFORM private.validate_reimport_name_completion(v_id,p_source_batch_id,p_manifest_sha256,p_payloads);
  RETURN jsonb_build_object('authorization_id',v_id,'database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text,'source',jsonb_build_object('id',b.source_id,'profile_id',b.profile_id,'profile_sha256',b.profile_sha256));
END $$;

CREATE OR REPLACE FUNCTION public.red_preflight_reimport_name_completion(p_authorization_id uuid,p_source_batch_id uuid,p_manifest_sha256 text,p_payloads jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE b private.reimport_batch%ROWTYPE; a private.reimport_authorization%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  b:=private.validate_reimport_name_completion(p_authorization_id,p_source_batch_id,p_manifest_sha256,p_payloads);
  PERFORM private.lock_reimport_writer(b.source_id,b.profile_id);
  SELECT * INTO a FROM private.reimport_authorization WHERE id=p_authorization_id;
  RETURN jsonb_build_object('authorization',jsonb_build_object('authorization_id',a.id,'database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text,'source',jsonb_build_object('id',b.source_id,'profile_id',b.profile_id,'profile_sha256',b.profile_sha256)),'preflight',jsonb_build_object('valid',true,'database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text,'source_batch_id',p_source_batch_id,'manifest_sha256',p_manifest_sha256));
END $$;

CREATE OR REPLACE FUNCTION public.red_begin_reimport_name_completion(p_authorization_id uuid,p_manifest_sha256 text,p_source_batch_id uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE a private.reimport_authorization%ROWTYPE; b private.reimport_batch%ROWTYPE; v_id uuid;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_source_batch_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id);
  SELECT * INTO a FROM private.reimport_authorization WHERE id=p_authorization_id FOR UPDATE; SELECT * INTO b FROM private.reimport_batch WHERE id=p_source_batch_id FOR UPDATE;
  IF NOT FOUND OR b.source_id IS DISTINCT FROM v_discovered_source_id OR b.profile_id IS DISTINCT FROM v_discovered_profile_id OR a.operation<>'name_completion' OR a.status<>'issued' OR a.principal_id<>private.require_reimport_writer_editor() OR a.expires_at<=clock_timestamp() OR a.manifest_sha256<>p_manifest_sha256 OR a.database_identity IS DISTINCT FROM jsonb_build_object('database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text)::text OR b.status<>'finalized' OR a.source_id<>b.source_id OR a.profile_id<>b.profile_id OR a.profile_sha256<>b.profile_sha256 OR a.authorized_elements->'source_batch_id' IS DISTINCT FROM to_jsonb(p_source_batch_id) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  UPDATE private.reimport_authorization SET status='consumed',consumed_at=clock_timestamp() WHERE id=a.id;
  INSERT INTO private.reimport_batch(authorization_id,manifest_sha256,preview_sha256,source_id,profile_id,profile_sha256,principal_id,expected_counts) VALUES(a.id,a.manifest_sha256,a.preview_sha256,a.source_id,a.profile_id,a.profile_sha256,a.principal_id,a.expected_counts) RETURNING id INTO v_id; RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.red_apply_reimport_name_completion(p_batch_id uuid,p_element_id text,p_payload jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE b private.reimport_batch%ROWTYPE; a private.reimport_authorization%ROWTYPE; v_profile private.reimport_writer_profile%ROWTYPE; v_fact bigint; v_assertion bigint; v_citation bigint; v_conclusion bigint; v_record uuid; v_hash text; v_citation_label text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  b:=private.require_reimport_open_batch(p_batch_id); SELECT * INTO a FROM private.reimport_authorization WHERE id=b.authorization_id;
  PERFORM private.lock_reimport_writer(b.source_id,b.profile_id);
  IF NOT FOUND OR a.operation<>'name_completion' OR a.authorized_elements->'payloads'->p_element_id IS DISTINCT FROM p_payload OR a.authorized_elements->'source_batch_id' IS DISTINCT FROM to_jsonb((p_payload->>'source_batch_id')::uuid) OR EXISTS(SELECT 1 FROM private.reimport_name_completion_result WHERE batch_id=p_batch_id AND element_id=p_element_id) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  IF jsonb_typeof(p_payload->'page_evidence') IS DISTINCT FROM 'object' OR jsonb_typeof(p_payload->'page_evidence'->'page_from') IS DISTINCT FROM 'number' OR NOT (CASE WHEN coalesce(p_payload#>>'{page_evidence,page_from}','') ~ '^[0-9]+$' THEN ((p_payload#>>'{page_evidence,page_from}')::numeric BETWEEN 1 AND 2147483647) ELSE false END) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  SELECT id INTO v_record FROM private.source_record WHERE source_id=b.source_id AND record_key=p_payload->>'source_record_key' FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM private.reimport_event e JOIN private.reimport_batch sb ON sb.id=e.batch_id WHERE e.batch_id=(p_payload->>'source_batch_id')::uuid AND sb.status='finalized' AND sb.source_id=b.source_id AND sb.profile_id=b.profile_id AND sb.profile_sha256=b.profile_sha256 AND e.operation='person_create' AND e.element_id=p_payload->>'source_person_create_element_id' AND e.canonical_person_id=(p_payload->>'person_id')::bigint AND e.payload->>'authorized_payload_sha256'=p_payload->>'source_payload_sha256') OR NOT EXISTS(SELECT 1 FROM public.person WHERE id=(p_payload->>'person_id')::bigint AND staged AND visning_navn IS NULL) OR EXISTS(SELECT 1 FROM public.fact WHERE subjekt_type='person' AND subjekt_id=(p_payload->>'person_id')::bigint AND faktatype='navn') OR NOT EXISTS(SELECT 1 FROM private.source_persona sp JOIN private.source_persona_identity si ON si.source_persona_id=sp.id AND si.decision_status='accepted' WHERE sp.id=(p_payload->>'source_persona_id')::uuid AND sp.source_id=b.source_id AND si.canonical_person_id=(p_payload->>'person_id')::bigint) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  SELECT * INTO v_profile FROM private.reimport_writer_profile WHERE source_id=b.source_id AND profile_id=b.profile_id AND profile_sha256=b.profile_sha256;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  v_citation_label:=replace(v_profile.writer_config->>'citation_label_template','{page_from}',p_payload->'page_evidence'->>'page_from');
  INSERT INTO public.fact(subjekt_type,subjekt_id,faktatype) VALUES('person',(p_payload->>'person_id')::bigint,'navn') RETURNING id INTO v_fact; INSERT INTO public.assertion(target_type,target_id,vaerdi_tekst,uforanderlig) VALUES('fact',v_fact,p_payload->>'name',true) RETURNING id INTO v_assertion; INSERT INTO public.citation(assertion_id,source_id,side,citat_tekst,kvalitet) VALUES(v_assertion,b.source_id,p_payload->'page_evidence'->>'page_from',v_citation_label,'primær') RETURNING id INTO v_citation; INSERT INTO public.conclusion(target_type,target_id,valgt_assertion_id,status,blaastemplet_af,blaastemplet_naar) VALUES('fact',v_fact,v_assertion,'afklaret',b.profile_id||' name completion',current_date) RETURNING id INTO v_conclusion;
  v_hash:=private.reimport_canonical_json_sha256(jsonb_build_object('fact_id',v_fact,'assertion_id',v_assertion,'citation_id',v_citation,'conclusion_id',v_conclusion)); INSERT INTO private.reimport_name_completion_result(batch_id,element_id,source_batch_id,person_id,source_record_id,source_persona_id,fact_id,assertion_id,citation_id,conclusion_id,payload_sha256,result_sha256) VALUES(p_batch_id,p_element_id,(p_payload->>'source_batch_id')::uuid,(p_payload->>'person_id')::bigint,v_record,(p_payload->>'source_persona_id')::uuid,v_fact,v_assertion,v_citation,v_conclusion,private.reimport_canonical_json_sha256(p_payload),v_hash); INSERT INTO private.reimport_event(batch_id,element_id,operation,source_record_key,canonical_person_id,payload,after_sha256) VALUES(p_batch_id,p_element_id,'canonical_delta',p_payload->>'source_record_key',(p_payload->>'person_id')::bigint,p_payload,v_hash);
END $$;

CREATE OR REPLACE FUNCTION public.red_finalize_reimport_name_completion(p_batch_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE b private.reimport_batch%ROWTYPE; v_counts jsonb; v_map jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  b:=private.require_reimport_open_batch(p_batch_id); PERFORM private.lock_reimport_writer(b.source_id,b.profile_id); SELECT jsonb_build_object('name_completions',coalesce(count(*),0)::bigint,'operations',coalesce(count(*),0)::bigint) INTO v_counts FROM private.reimport_name_completion_result WHERE batch_id=p_batch_id;
  IF v_counts<>b.expected_counts OR (SELECT count(*) FROM private.reimport_event WHERE batch_id=p_batch_id AND operation='canonical_delta')<>(v_counts->>'operations')::bigint OR EXISTS(SELECT 1 FROM private.reimport_name_completion_result r LEFT JOIN public.fact f ON f.id=r.fact_id AND f.subjekt_id=r.person_id AND f.faktatype='navn' LEFT JOIN public.assertion x ON x.id=r.assertion_id AND x.target_id=r.fact_id LEFT JOIN public.citation c ON c.id=r.citation_id AND c.assertion_id=r.assertion_id LEFT JOIN public.conclusion n ON n.id=r.conclusion_id AND n.valgt_assertion_id=r.assertion_id WHERE r.batch_id=p_batch_id AND (f.id IS NULL OR x.id IS NULL OR c.id IS NULL OR n.id IS NULL)) OR EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=(SELECT (auth_row.authorized_elements->>'source_batch_id')::uuid FROM private.reimport_authorization auth_row WHERE auth_row.id=b.authorization_id) AND parent.operation='person_create' AND NOT EXISTS(SELECT 1 FROM private.reimport_name_completion_result result JOIN private.reimport_event child_event ON child_event.batch_id=result.batch_id AND child_event.element_id=result.element_id AND child_event.operation='canonical_delta' WHERE result.batch_id=p_batch_id AND result.person_id=parent.canonical_person_id AND child_event.payload->>'source_person_create_element_id'=parent.element_id AND child_event.source_record_key=parent.source_record_key)) OR EXISTS(SELECT 1 FROM private.reimport_name_completion_result result JOIN private.reimport_event child_event ON child_event.batch_id=result.batch_id AND child_event.element_id=result.element_id AND child_event.operation='canonical_delta' WHERE result.batch_id=p_batch_id AND NOT EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=result.source_batch_id AND parent.operation='person_create' AND parent.element_id=child_event.payload->>'source_person_create_element_id' AND parent.canonical_person_id=result.person_id AND parent.source_record_key=child_event.source_record_key)) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  SELECT jsonb_object_agg(element_id,jsonb_build_object('person_id',person_id,'fact_id',fact_id,'assertion_id',assertion_id,'citation_id',citation_id,'conclusion_id',conclusion_id) ORDER BY element_id) INTO v_map FROM private.reimport_name_completion_result WHERE batch_id=p_batch_id; UPDATE private.reimport_batch SET status='finalized',observed_counts=v_counts,finalized_at=clock_timestamp() WHERE id=p_batch_id; RETURN jsonb_build_object('batch_id',p_batch_id,'status','finalized','counts',v_counts,'result_map',v_map);
END $$;

CREATE OR REPLACE FUNCTION public.red_authorize_reimport_reversal(p_batch_id uuid,p_nonce uuid,p_expires_at timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_id uuid; v_batch private.reimport_batch%ROWTYPE; v_actor uuid;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_actor:=private.require_reimport_writer_editor(); SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_batch_id; IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF; PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id); SELECT * INTO v_batch FROM private.reimport_batch WHERE id=p_batch_id AND status IN ('finalized','activated') FOR UPDATE;
  IF NOT FOUND OR v_batch.source_id IS DISTINCT FROM v_discovered_source_id OR v_batch.profile_id IS DISTINCT FROM v_discovered_profile_id OR p_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
  INSERT INTO private.reimport_authorization(operation,manifest_sha256,preview_sha256,database_identity,source_id,profile_id,profile_sha256,expected_counts,authorized_elements,principal_id,nonce,expires_at) VALUES('reversal',v_batch.manifest_sha256,v_batch.preview_sha256,'batch:'||v_batch.id::text,v_batch.source_id,v_batch.profile_id,v_batch.profile_sha256,'{}','{}',v_actor,p_nonce,p_expires_at) RETURNING id INTO v_id; RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.red_reverse_reimport(p_batch_id uuid,p_authorization_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_actor uuid; b private.reimport_batch%ROWTYPE; a private.reimport_authorization%ROWTYPE; cb private.reimport_batch%ROWTYPE; r private.reimport_name_completion_result%ROWTYPE; e private.reimport_event%ROWTYPE; activation private.reimport_event%ROWTYPE; v_child_count bigint; v_child_id uuid; v_identity_version integer; v_state jsonb; v_receipt jsonb; v_reversed jsonb;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_actor:=private.require_reimport_writer_editor();
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_batch_id; IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF; PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id); SELECT * INTO b FROM private.reimport_batch WHERE id=p_batch_id FOR UPDATE; SELECT * INTO a FROM private.reimport_authorization WHERE id=p_authorization_id FOR UPDATE;
  IF b.id IS NULL OR b.source_id IS DISTINCT FROM v_discovered_source_id OR b.profile_id IS DISTINCT FROM v_discovered_profile_id OR a.id IS NULL OR a.operation<>'reversal' OR a.status<>'issued' OR a.principal_id<>v_actor OR a.expires_at<=clock_timestamp() OR a.database_identity IS DISTINCT FROM 'batch:'||p_batch_id::text OR a.source_id<>b.source_id OR a.profile_id<>b.profile_id OR a.profile_sha256<>b.profile_sha256 OR b.status<>'activated' THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
  SELECT count(*),(array_agg(child_batch.id ORDER BY child_batch.id))[1] INTO v_child_count,v_child_id FROM private.reimport_batch child_batch JOIN private.reimport_authorization child_authorization ON child_authorization.id=child_batch.authorization_id WHERE child_authorization.operation='name_completion' AND child_batch.status='finalized' AND child_authorization.source_id=b.source_id AND child_authorization.profile_id=b.profile_id AND child_authorization.profile_sha256=b.profile_sha256 AND child_authorization.authorized_elements->'source_batch_id'=to_jsonb(b.id);
  IF v_child_count<>1 THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
  SELECT * INTO cb FROM private.reimport_batch WHERE id=v_child_id FOR UPDATE;
  IF cb.expected_counts IS DISTINCT FROM cb.observed_counts OR (SELECT count(*) FROM private.reimport_name_completion_result WHERE batch_id=cb.id)<>(cb.expected_counts->>'name_completions')::bigint OR (SELECT count(*) FROM private.reimport_event WHERE batch_id=cb.id AND operation='canonical_delta')<>(cb.expected_counts->>'operations')::bigint OR EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=b.id AND parent.operation='person_create' AND NOT EXISTS(SELECT 1 FROM private.reimport_name_completion_result result JOIN private.reimport_event child_event ON child_event.batch_id=result.batch_id AND child_event.element_id=result.element_id AND child_event.operation='canonical_delta' WHERE result.batch_id=cb.id AND result.person_id=parent.canonical_person_id AND child_event.payload->>'source_person_create_element_id'=parent.element_id AND child_event.source_record_key=parent.source_record_key)) OR EXISTS(SELECT 1 FROM private.reimport_name_completion_result result JOIN private.reimport_event child_event ON child_event.batch_id=result.batch_id AND child_event.element_id=result.element_id AND child_event.operation='canonical_delta' WHERE result.batch_id=cb.id AND NOT EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=b.id AND parent.operation='person_create' AND parent.element_id=child_event.payload->>'source_person_create_element_id' AND parent.canonical_person_id=result.person_id AND parent.source_record_key=child_event.source_record_key)) THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
  SELECT * INTO activation FROM private.reimport_event WHERE batch_id=b.id AND operation='activation' ORDER BY id DESC LIMIT 1 FOR UPDATE;
  IF activation.id IS NULL OR jsonb_typeof(activation.payload->'post_activation_receipts')<>'object' THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
  FOR r IN SELECT * FROM private.reimport_name_completion_result WHERE batch_id=cb.id ORDER BY person_id LOOP
    SELECT * INTO e FROM private.reimport_event WHERE batch_id=b.id AND operation='person_create' AND canonical_person_id=r.person_id AND source_record_key=(SELECT record_key FROM private.source_record WHERE id=r.source_record_id);
    v_receipt:=activation.payload->'post_activation_receipts'->r.person_id::text;
    IF e.id IS NULL OR private.reimport_canonical_json_sha256(jsonb_build_object('fact_id',r.fact_id,'assertion_id',r.assertion_id,'citation_id',r.citation_id,'conclusion_id',r.conclusion_id))<>r.result_sha256 OR e.payload->>'event_id' IS NULL OR jsonb_typeof(v_receipt)<>'object' OR v_receipt->>'source_person_create_event_id' IS DISTINCT FROM e.payload->>'event_id' OR v_receipt->>'source_record_key' IS DISTINCT FROM e.source_record_key OR v_receipt->>'state_sha256' !~ '^[0-9a-f]{64}$' OR v_receipt->>'event_id' IS NULL THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
    v_state:=private.narrative_record_state(r.person_id,b.source_id,e.source_record_key,true);
    IF v_state->>'state_sha256' IS DISTINCT FROM v_receipt->>'state_sha256' THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
    v_reversed:=public.red_fortryd_person_narrative_publication_event((v_receipt->>'event_id')::uuid,v_receipt->>'state_sha256');
    PERFORM set_config('app.change_set_id','',true);
    PERFORM public.red_kasser_person_narrative_record(r.person_id,b.source_id,e.source_record_key,v_reversed->>'state_sha256');
    PERFORM set_config('app.change_set_id','',true);
    DELETE FROM public.conclusion WHERE id=r.conclusion_id; DELETE FROM public.citation WHERE id=r.citation_id; DELETE FROM public.assertion WHERE id=r.assertion_id; DELETE FROM public.fact WHERE id=r.fact_id;
    SELECT version INTO v_identity_version FROM private.source_persona_identity WHERE source_persona_id=r.source_persona_id ORDER BY version DESC LIMIT 1 FOR UPDATE;
    IF v_identity_version IS NULL THEN RAISE EXCEPTION 'REIMPORT_WRITER_REVERSAL_INVALID'; END IF;
    PERFORM private.decide_source_persona_identity(r.source_persona_id,NULL,v_identity_version,'superseded',jsonb_build_object('reversed_batch_id',b.id,'profile_sha256',b.profile_sha256),'reversal'); UPDATE public.person SET staged=true WHERE id=r.person_id;
  END LOOP;
  UPDATE private.reimport_authorization SET status='consumed',consumed_at=clock_timestamp() WHERE id=a.id; UPDATE private.reimport_batch SET status='reversed' WHERE id IN (b.id,cb.id); INSERT INTO private.reimport_event(batch_id,element_id,operation,payload,after_sha256) VALUES(b.id,'reversal:'||a.id::text,'reversal',jsonb_build_object('authorization_id',a.id,'child_batch_id',cb.id),private.reimport_canonical_json_sha256(jsonb_build_object('authorization_id',a.id,'child_batch_id',cb.id))); RETURN jsonb_build_object('batch_id',b.id,'status','reversed','child_batch_id',cb.id);
END $$;

CREATE OR REPLACE FUNCTION public.red_authorize_reimport_cutover(p_batch_id uuid,p_nonce uuid,p_expires_at timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_id uuid; v_batch private.reimport_batch%ROWTYPE; v_actor uuid;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_actor:=private.require_reimport_writer_editor(); SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_batch_id; IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_INVALID'; END IF; PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id); SELECT * INTO v_batch FROM private.reimport_batch WHERE id=p_batch_id AND status='finalized' FOR UPDATE;
  IF NOT FOUND OR v_batch.source_id IS DISTINCT FROM v_discovered_source_id OR v_batch.profile_id IS DISTINCT FROM v_discovered_profile_id OR p_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_INVALID'; END IF;
  INSERT INTO private.reimport_authorization(operation,manifest_sha256,preview_sha256,database_identity,source_id,profile_id,profile_sha256,expected_counts,authorized_elements,principal_id,nonce,expires_at) VALUES('cutover',v_batch.manifest_sha256,v_batch.preview_sha256,'batch:'||v_batch.id::text,v_batch.source_id,v_batch.profile_id,v_batch.profile_sha256,'{}','{}',v_actor,p_nonce,p_expires_at) RETURNING id INTO v_id; RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.red_activate_reimport_batch(p_batch_id uuid,p_authorization_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_actor uuid; v_count bigint; b private.reimport_batch%ROWTYPE; a private.reimport_authorization%ROWTYPE; cb private.reimport_batch%ROWTYPE; v_child_count bigint; v_child_id uuid; e private.reimport_event%ROWTYPE; v_state jsonb; v_refreshed jsonb; v_receipts jsonb:='{}'::jsonb;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_actor:=private.require_reimport_writer_editor(); SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_batch_id; IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_INVALID'; END IF; PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id); SELECT * INTO b FROM private.reimport_batch WHERE id=p_batch_id FOR UPDATE; SELECT * INTO a FROM private.reimport_authorization WHERE id=p_authorization_id FOR UPDATE;
  IF b.id IS NULL OR b.source_id IS DISTINCT FROM v_discovered_source_id OR b.profile_id IS DISTINCT FROM v_discovered_profile_id OR a.id IS NULL OR a.operation<>'cutover' OR a.status<>'issued' OR a.principal_id<>v_actor OR a.expires_at<=clock_timestamp() OR a.database_identity IS DISTINCT FROM 'batch:'||p_batch_id::text OR a.manifest_sha256<>b.manifest_sha256 OR a.preview_sha256<>b.preview_sha256 OR a.source_id<>b.source_id OR a.profile_id<>b.profile_id OR a.profile_sha256<>b.profile_sha256 OR b.status<>'finalized' THEN RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_INVALID'; END IF;
  SELECT count(*),(array_agg(child_batch.id ORDER BY child_batch.id))[1] INTO v_child_count,v_child_id FROM private.reimport_batch child_batch JOIN private.reimport_authorization child_authorization ON child_authorization.id=child_batch.authorization_id WHERE child_authorization.operation='name_completion' AND child_batch.status='finalized' AND child_authorization.source_id=b.source_id AND child_authorization.profile_id=b.profile_id AND child_authorization.profile_sha256=b.profile_sha256 AND child_authorization.authorized_elements->'source_batch_id'=to_jsonb(b.id); IF v_child_count<>1 THEN RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_INVALID'; END IF; SELECT * INTO cb FROM private.reimport_batch WHERE id=v_child_id FOR UPDATE; IF cb.observed_counts IS DISTINCT FROM cb.expected_counts OR (SELECT count(*) FROM private.reimport_name_completion_result WHERE batch_id=cb.id)<>(cb.expected_counts->>'name_completions')::bigint OR EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=b.id AND parent.operation='person_create' AND NOT EXISTS(SELECT 1 FROM private.reimport_name_completion_result result JOIN private.reimport_event child_event ON child_event.batch_id=result.batch_id AND child_event.element_id=result.element_id AND child_event.operation='canonical_delta' WHERE result.batch_id=cb.id AND result.person_id=parent.canonical_person_id AND child_event.payload->>'source_person_create_element_id'=parent.element_id AND child_event.source_record_key=parent.source_record_key)) OR EXISTS(SELECT 1 FROM private.reimport_name_completion_result result JOIN private.reimport_event child_event ON child_event.batch_id=result.batch_id AND child_event.element_id=result.element_id AND child_event.operation='canonical_delta' WHERE result.batch_id=cb.id AND NOT EXISTS(SELECT 1 FROM private.reimport_event parent WHERE parent.batch_id=b.id AND parent.operation='person_create' AND parent.element_id=child_event.payload->>'source_person_create_element_id' AND parent.canonical_person_id=result.person_id AND parent.source_record_key=child_event.source_record_key)) THEN RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_INVALID'; END IF;
  UPDATE public.person SET staged=false WHERE id IN(SELECT canonical_person_id FROM private.reimport_event WHERE batch_id=p_batch_id AND operation='person_create'); GET DIAGNOSTICS v_count=ROW_COUNT;
  FOR e IN SELECT * FROM private.reimport_event WHERE batch_id=p_batch_id AND operation='person_create' ORDER BY canonical_person_id LOOP
    v_state:=private.narrative_record_state(e.canonical_person_id,b.source_id,e.source_record_key,true);
    IF e.payload->>'event_id' IS NULL OR v_state #> '{publication_state,target}' IS DISTINCT FROM jsonb_build_object('person_id',e.canonical_person_id,'source_id',b.source_id,'record_key',e.source_record_key,'source_record_id',(v_state #>> '{publication_state,target,source_record_id}')::uuid,'source_record_ref',(v_state #>> '{publication_state,target,source_record_ref}')::uuid) THEN RAISE EXCEPTION 'REIMPORT_WRITER_CUTOVER_INVALID'; END IF;
    v_refreshed:=public.red_upsert_person_narrative_record(e.canonical_person_id,b.source_id,e.source_record_key,e.payload->'narrative'->>'text',false,v_state->>'state_sha256');
    PERFORM set_config('app.change_set_id','',true);
    v_receipts:=v_receipts||jsonb_build_object(e.canonical_person_id::text,jsonb_build_object('event_id',v_refreshed->>'event_id','source_person_create_event_id',e.payload->>'event_id','source_record_key',e.source_record_key,'state_sha256',v_refreshed->>'state_sha256'));
  END LOOP;
  UPDATE private.reimport_authorization SET status='consumed',consumed_at=clock_timestamp() WHERE id=p_authorization_id;
  UPDATE private.reimport_batch SET status='activated' WHERE id=p_batch_id;
  INSERT INTO private.reimport_event(batch_id,element_id,operation,payload,after_sha256) VALUES(p_batch_id,'activation:'||p_authorization_id::text,'activation',jsonb_build_object('authorization_id',p_authorization_id,'persons_activated',v_count,'post_activation_receipts',v_receipts),private.reimport_canonical_json_sha256(jsonb_build_object('authorization_id',p_authorization_id,'persons_activated',v_count,'post_activation_receipts',v_receipts)));
  RETURN jsonb_build_object('batch_id',p_batch_id,'status','activated','persons_activated',v_count);
END $$;

REVOKE ALL ON FUNCTION
  private.reimport_canonical_json_text(jsonb),
  private.reimport_canonical_json_sha256(jsonb),
  private.lock_reimport_writer(bigint,text),
  private.validate_reimport_authorization_payload(jsonb,jsonb),
  private.ensure_reimport_source_evidence(uuid,text,jsonb),
  private.validate_reimport_name_completion(uuid,uuid,text,jsonb),
  public.red_lock_reimport_name_completion(text),
  public.red_authorize_reimport_name_completion(text,uuid,text,text,jsonb,jsonb),
  public.red_preflight_reimport_name_completion(uuid,uuid,text,jsonb),
  public.red_begin_reimport_name_completion(uuid,text,uuid),
  public.red_apply_reimport_name_completion(uuid,text,jsonb),
  public.red_finalize_reimport_name_completion(uuid)
FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.red_authorize_reimport_name_completion(text,uuid,text,text,jsonb,jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.red_lock_reimport_name_completion(text),public.red_preflight_reimport_name_completion(uuid,uuid,text,jsonb),public.red_begin_reimport_name_completion(uuid,text,uuid),public.red_apply_reimport_name_completion(uuid,text,jsonb),public.red_finalize_reimport_name_completion(uuid) TO authenticated;

-- Some pre-#153 upgrade paths installed the empty generic shells before this
-- transition.  Move the only permitted legacy ledger into those shells rather
-- than overwriting either ledger or recreating IDs.  Any occupied target is an
-- ambiguous merge and must stop fail-closed.
-- The terminal rename path above leaves no old physical table.  Keep the
-- coexistence fallback dynamically dispatched so PL/pgSQL does not resolve
-- its old-table references while compiling that renamed path.
DO $reimport_writer_coexistence_dispatch$
BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid=to_regclass('private.reimport_1939_authorization'))='r' THEN
    EXECUTE $reimport_writer_coexistence_body$
DO $reimport_writer_coexistence_body_inner$
DECLARE
  v_event_sequence text;
  v_event_restart_with bigint;
BEGIN
  -- The rename branch has already migrated a populated legacy table and later
  -- migration sections may recreate an empty compatibility shell.  Only an
  -- independently populated old ledger can be a coexistence candidate.
  IF EXISTS(SELECT 1 FROM private.reimport_1939_authorization) THEN
    IF (SELECT count(*) FROM private.reimport_authorization)<>0
       OR (SELECT count(*) FROM private.reimport_batch)<>0
       OR (SELECT count(*) FROM private.reimport_event)<>0
       OR (to_regclass('private.reimport_name_completion_result') IS NOT NULL AND (SELECT count(*) FROM private.reimport_name_completion_result)<>0) THEN
      RAISE EXCEPTION 'REIMPORT_WRITER_LEGACY_COEXISTENCE_AMBIGUOUS';
    END IF;
    IF EXISTS(SELECT 1 FROM private.reimport_1939_authorization)
       AND ((SELECT count(DISTINCT source_id) FROM private.reimport_1939_authorization)<>1
            OR NOT EXISTS(SELECT 1 FROM private.reimport_1939_authorization WHERE source_id=3)) THEN
      RAISE EXCEPTION 'REIMPORT_WRITER_LEGACY_SOURCE_IDENTITY_INVALID';
    END IF;
    INSERT INTO private.reimport_authorization(id,operation,manifest_sha256,preview_sha256,database_identity,source_id,profile_id,profile_sha256,expected_counts,authorized_elements,principal_id,nonce,expires_at,status,consumed_at,created_at)
    SELECT legacy.id,legacy.operation,legacy.manifest_sha256,legacy.preview_sha256,legacy.database_identity,legacy.source_id,'daa-1939-v50-production-write-v1',profile.profile_sha256,legacy.expected_counts,legacy.authorized_elements,legacy.principal_id,legacy.nonce,legacy.expires_at,legacy.status,legacy.consumed_at,legacy.created_at
      FROM private.reimport_1939_authorization legacy
      JOIN private.reimport_writer_profile profile ON profile.source_id=legacy.source_id AND profile.profile_id='daa-1939-v50-production-write-v1';
    INSERT INTO private.reimport_batch(id,authorization_id,manifest_sha256,preview_sha256,source_id,profile_id,profile_sha256,principal_id,status,expected_counts,observed_counts,created_at,finalized_at)
    SELECT legacy.id,legacy.authorization_id,legacy.manifest_sha256,legacy.preview_sha256,3,'daa-1939-v50-production-write-v1',profile.profile_sha256,legacy.principal_id,legacy.status,legacy.expected_counts,legacy.observed_counts,legacy.created_at,legacy.finalized_at
      FROM private.reimport_1939_write_batch legacy
      JOIN private.reimport_writer_profile profile ON profile.source_id=3 AND profile.profile_id='daa-1939-v50-production-write-v1';
    INSERT INTO private.reimport_event(id,batch_id,element_id,operation,source_record_key,canonical_person_id,payload,before_sha256,after_sha256,created_at)
    SELECT id,batch_id,element_id,operation,source_record_key,canonical_person_id,payload,before_sha256,after_sha256,created_at FROM private.reimport_1939_write_event;
    -- RESTART is transactional, unlike setval: if a later #153 step fails,
    -- rollback restores both the copied ledger and this owned sequence's exact
    -- state.  Preserve the existing sequence identity and derive its first
    -- post-copy value only after every legacy event row has been transferred.
    SELECT pg_get_serial_sequence('private.reimport_event','id') INTO v_event_sequence;
    IF v_event_sequence IS NULL THEN
      RAISE EXCEPTION 'REIMPORT_WRITER_EVENT_SEQUENCE_MISSING';
    END IF;
    SELECT coalesce(max(id),0)+1 INTO v_event_restart_with
      FROM private.reimport_event;
    EXECUTE format('ALTER SEQUENCE %s RESTART WITH %s',v_event_sequence,v_event_restart_with);
    IF (SELECT relkind FROM pg_class WHERE oid=to_regclass('private.reimport_1939_name_completion_result'))='r' THEN
      INSERT INTO private.reimport_name_completion_result SELECT * FROM private.reimport_1939_name_completion_result;
      DROP TABLE private.reimport_1939_name_completion_result;
    END IF;
    -- This branch is reached by a fresh #153 schema only after the old
    -- rerunnable section created empty legacy shells.  Its typed helper must
    -- be removed explicitly before dropping that shell; terminal historical
    -- upgrades use the rename branch above and never recreate a row type.
    DROP FUNCTION IF EXISTS private.require_reimport_1939_open_batch(uuid);
    DROP FUNCTION IF EXISTS private.ensure_reimport_1939_source_evidence(uuid,text,jsonb);
    DROP FUNCTION IF EXISTS private.validate_reimport_1939_name_completion(uuid,uuid,text,jsonb);
    DROP TABLE private.reimport_1939_write_event;
    DROP TABLE private.reimport_1939_write_batch;
    DROP TABLE private.reimport_1939_authorization;
  END IF;
END $reimport_writer_coexistence_body_inner$;
$reimport_writer_coexistence_body$;
  END IF;
END $reimport_writer_coexistence_dispatch$;

-- #153 transition facade.  The table rename above preserves the historic row
-- identities; the old names become views only after every generic primary is
-- installed.  These adapters are intentionally limited to one pinned generic
-- call plus the explicit legacy domain-error mapping.
DROP FUNCTION IF EXISTS private.require_reimport_1939_open_batch(uuid);
DROP FUNCTION IF EXISTS private.ensure_reimport_1939_source_evidence(uuid,text,jsonb);
DROP FUNCTION IF EXISTS private.validate_reimport_1939_name_completion(uuid,uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_authorize_1939_v50_reimport(text,text,text,bigint,jsonb,jsonb,uuid,timestamptz);
DROP FUNCTION IF EXISTS public.red_begin_1939_v50_reimport(uuid,text,text);
DROP FUNCTION IF EXISTS public.red_apply_1939_v50_source_evidence(uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_apply_1939_v50_person_create(uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_apply_1939_v50_canonical_delta(uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_finalize_1939_v50_reimport(uuid);
DROP FUNCTION IF EXISTS public.red_authorize_1939_v50_reversal(uuid,uuid,timestamptz);
DROP FUNCTION IF EXISTS public.red_reverse_1939_v50_reimport(uuid,uuid);
DROP FUNCTION IF EXISTS public.red_authorize_1939_v50_cutover(uuid,uuid,timestamptz);
DROP FUNCTION IF EXISTS public.red_activate_1939_v50_batch(uuid,uuid);
DROP FUNCTION IF EXISTS public.red_lock_1939_v50_name_completion(text);
DROP FUNCTION IF EXISTS public.red_authorize_1939_v50_name_completion(text,uuid,text,text,jsonb,jsonb);
DROP FUNCTION IF EXISTS public.red_preflight_1939_v50_name_completion(uuid,uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_begin_1939_v50_name_completion(uuid,text,uuid);
DROP FUNCTION IF EXISTS public.red_apply_1939_v50_name_completion(uuid,text,jsonb);
DROP FUNCTION IF EXISTS public.red_finalize_1939_v50_name_completion(uuid);
-- No #153 facade uses the former physical-ledger helpers.  Remove every
-- remaining private 1939 implementation so fresh and upgraded catalogs expose
-- the same generic helper surface.
-- Earlier idempotent migration sections can leave empty pre-#153 shell tables
-- behind after the real ledger was renamed.  Remove those shells (and their
-- legacy triggers) before replacing the names with read-only compatibility
-- views; no populated legacy table reaches this point.
DROP TABLE IF EXISTS private.reimport_1939_name_completion_result;
DROP TABLE IF EXISTS private.reimport_1939_write_event;
DROP TABLE IF EXISTS private.reimport_1939_write_batch;
DROP TABLE IF EXISTS private.reimport_1939_authorization;
DROP FUNCTION IF EXISTS private.reject_reimport_1939_event_mutation();
DROP FUNCTION IF EXISTS private.reimport_1939_canonical_json_text(jsonb);
CREATE OR REPLACE VIEW private.reimport_1939_authorization AS SELECT * FROM private.reimport_authorization;
CREATE OR REPLACE VIEW private.reimport_1939_write_batch AS SELECT * FROM private.reimport_batch;
CREATE OR REPLACE VIEW private.reimport_1939_write_event AS SELECT * FROM private.reimport_event;
CREATE OR REPLACE VIEW private.reimport_1939_name_completion_result AS SELECT * FROM private.reimport_name_completion_result;

CREATE OR REPLACE FUNCTION public.red_authorize_1939_v50_reimport(m text,p text,d text,s bigint,c jsonb,e jsonb,n uuid,x timestamptz)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_database_identity text; v_expected_counts jsonb;
BEGIN
  -- The one-version facade accepts only the historic Phase-A representation:
  -- current_database() plus exactly its two supported counts and a numeric
  -- zero canonical_delta.  Every other value continues into the generic
  -- validator unchanged so the historic invalid-token mapping is preserved.
  IF d=current_database() AND jsonb_typeof(c)='object'
     AND (SELECT count(*) FROM jsonb_object_keys(c))=3
     AND c ?& ARRAY['person_creates','source_evidence','canonical_delta']
     AND jsonb_typeof(c->'canonical_delta')='number'
     AND (c->>'canonical_delta')::numeric=0 THEN
    v_database_identity:=jsonb_build_object('database_name',current_database(),
      'system_identifier',(pg_control_system()).system_identifier::text)::text;
    v_expected_counts:=c-'canonical_delta';
  ELSE
    v_database_identity:=d;
    v_expected_counts:=c;
  END IF;
  RETURN public.red_authorize_reimport(m,p,v_database_identity,3,'daa-1939-v50-production-write-v1',
    (SELECT profile_sha256 FROM private.reimport_writer_profile
      WHERE (source_id,profile_id)=(3,'daa-1939-v50-production-write-v1')),v_expected_counts,e,n,x);
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM IN ('REIMPORT_WRITER_AUTHORIZATION_INVALID','REIMPORT_WRITER_PROFILE_INVALID','REIMPORT_WRITER_PROFILE_HASH_INVALID') THEN RAISE EXCEPTION 'REIMPORT_1939_AUTHORIZATION_INVALID'; END IF;
  IF SQLERRM='REIMPORT_WRITER_ROLE_FORBIDDEN' THEN RAISE EXCEPTION 'REIMPORT_1939_ROLE_FORBIDDEN'; END IF;
  RAISE;
END $$;
CREATE OR REPLACE FUNCTION public.red_begin_1939_v50_reimport(i uuid,m text,p text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_begin_reimport(i,m,p); EXCEPTION WHEN OTHERS THEN IF SQLERRM IN ('REIMPORT_WRITER_AUTHORIZATION_INVALID','REIMPORT_WRITER_BATCH_INVALID') THEN RAISE EXCEPTION 'REIMPORT_1939_AUTHORIZATION_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_apply_1939_v50_source_evidence(b uuid,e text,p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM public.red_apply_reimport_source_evidence(b,e,p); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_BATCH_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_BATCH_INVALID'; END IF; IF SQLERRM='REIMPORT_WRITER_ELEMENT_NOT_AUTHORIZED' THEN RAISE EXCEPTION 'REIMPORT_1939_ELEMENT_NOT_AUTHORIZED'; END IF; IF SQLERRM='REIMPORT_WRITER_SOURCE_EVIDENCE_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_SOURCE_EVIDENCE_INVALID'; END IF; IF SQLERRM='REIMPORT_WRITER_RENDITION_DRIFT' THEN RAISE EXCEPTION 'REIMPORT_1939_RENDITION_DRIFT'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_apply_1939_v50_person_create(b uuid,e text,p jsonb) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_apply_reimport_person_create(b,e,p); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_BATCH_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_BATCH_INVALID'; END IF; IF SQLERRM='REIMPORT_WRITER_PERSON_CREATE_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_PERSON_CREATE_INVALID'; END IF; IF SQLERRM='REIMPORT_WRITER_ELEMENT_NOT_AUTHORIZED' THEN RAISE EXCEPTION 'REIMPORT_1939_ELEMENT_NOT_AUTHORIZED'; END IF; IF SQLERRM='REIMPORT_WRITER_SOURCE_EVIDENCE_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_SOURCE_EVIDENCE_INVALID'; END IF; IF SQLERRM='REIMPORT_WRITER_RENDITION_DRIFT' THEN RAISE EXCEPTION 'REIMPORT_1939_RENDITION_DRIFT'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_apply_1939_v50_canonical_delta(b uuid,e text,p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM public.red_apply_reimport_name_completion(b,e,'{}'::jsonb); EXCEPTION WHEN OTHERS THEN IF SQLERRM IN ('REIMPORT_NAME_COMPLETION_INVALID','REIMPORT_WRITER_BATCH_INVALID') THEN RAISE EXCEPTION 'REIMPORT_1939_CANONICAL_DELTA_UNSUPPORTED'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_finalize_1939_v50_reimport(b uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_finalize_reimport(b); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_BATCH_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_BATCH_INVALID'; END IF; IF SQLERRM='REIMPORT_WRITER_FINALIZE_COUNT_MISMATCH' THEN RAISE EXCEPTION 'REIMPORT_1939_FINALIZE_COUNT_MISMATCH'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_1939_v50_reversal(b uuid,n uuid,x timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_authorize_reimport_reversal(b,n,x); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_REVERSAL_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_REVERSAL_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_reverse_1939_v50_reimport(b uuid,a uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_reverse_reimport(b,a); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_REVERSAL_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_REVERSAL_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_1939_v50_cutover(b uuid,n uuid,x timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_authorize_reimport_cutover(b,n,x); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_CUTOVER_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_CUTOVER_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_activate_1939_v50_batch(b uuid,a uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_activate_reimport_batch(b,a); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_CUTOVER_INVALID' THEN RAISE EXCEPTION 'REIMPORT_1939_NAME_COMPLETION_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_lock_1939_v50_name_completion(m text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM public.red_lock_reimport_name_completion(m); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_ROLE_FORBIDDEN' THEN RAISE EXCEPTION 'REIMPORT_1939_ROLE_FORBIDDEN'; END IF; IF SQLERRM='REIMPORT_NAME_COMPLETION_INVALID' THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_LOCK_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_1939_v50_name_completion(m text,b uuid,mb text,mc text,c jsonb,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ DECLARE r jsonb; BEGIN r:=public.red_authorize_reimport_name_completion(m,b,mb,mc,c,p); RETURN jsonb_build_object('authorization_id',r->>'authorization_id','database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_NAME_COMPLETION_INVALID' THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_AUTHORIZATION_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_preflight_1939_v50_name_completion(a uuid,b uuid,m text,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ DECLARE r jsonb; BEGIN r:=public.red_preflight_reimport_name_completion(a,b,m,p); RETURN jsonb_build_object('authorization',jsonb_build_object('authorization_id',r->'authorization'->>'authorization_id','database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text),'preflight',jsonb_build_object('valid',true,'database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text,'source_batch_id',b,'manifest_sha256',m)); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_NAME_COMPLETION_INVALID' THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_PREFLIGHT_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_begin_1939_v50_name_completion(a uuid,m text,b uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_begin_reimport_name_completion(a,m,b); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_NAME_COMPLETION_INVALID' THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_AUTHORIZATION_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_apply_1939_v50_name_completion(b uuid,e text,p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM public.red_apply_reimport_name_completion(b,e,p); EXCEPTION WHEN OTHERS THEN IF SQLERRM IN ('REIMPORT_NAME_COMPLETION_INVALID','REIMPORT_WRITER_BATCH_INVALID') THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_APPLY_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_finalize_1939_v50_name_completion(b uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN RETURN public.red_finalize_reimport_name_completion(b); EXCEPTION WHEN OTHERS THEN IF SQLERRM IN ('REIMPORT_NAME_COMPLETION_INVALID','REIMPORT_WRITER_BATCH_INVALID') THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_FINALIZE_COUNT_MISMATCH'; END IF; RAISE; END $$;

-- Task 9: a closed profile config is part of the immutable profile identity.
CREATE OR REPLACE FUNCTION private.validate_reimport_writer_config(p_writer_config jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
  SELECT jsonb_typeof(p_writer_config)='object'
    AND ARRAY(SELECT key FROM jsonb_object_keys(p_writer_config) key ORDER BY key)
        = ARRAY['citation_label_template','extractor_version','observation_extraction_method','rendition_key','rendition_kind','rendition_metadata','run_key_prefix','schema_version']
    AND NOT EXISTS (SELECT 1 FROM unnest(ARRAY['run_key_prefix','schema_version','extractor_version','rendition_key','rendition_kind','observation_extraction_method']) key WHERE jsonb_typeof(p_writer_config->key)<>'string' OR btrim(p_writer_config->>key)='')
    AND jsonb_typeof(p_writer_config->'rendition_metadata')='object'
    AND jsonb_typeof(p_writer_config->'citation_label_template')='string'
    AND (length(p_writer_config->>'citation_label_template')-length(replace(p_writer_config->>'citation_label_template','{page_from}','')))/length('{page_from}')=1
    AND regexp_replace(p_writer_config->>'citation_label_template','\{page_from\}','', 'g') !~ '\{[^}]*\}';
$$;
DO $task9_writer_config_constraint$
BEGIN
  ALTER TABLE private.reimport_writer_profile
    DROP CONSTRAINT IF EXISTS reimport_writer_profile_writer_config_check;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='private.reimport_writer_profile'::regclass AND conname='reimport_writer_profile_config_valid') THEN
    ALTER TABLE private.reimport_writer_profile ADD CONSTRAINT reimport_writer_profile_config_valid CHECK (private.validate_reimport_writer_config(writer_config));
  END IF;
END $task9_writer_config_constraint$;

CREATE OR REPLACE FUNCTION public.red_apply_reimport_canonical_delta(p_batch_id uuid,p_element_id text,p_payload jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE v_batch private.reimport_batch%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  v_batch:=private.require_reimport_open_batch(p_batch_id);
  PERFORM private.lock_reimport_writer(v_batch.source_id,v_batch.profile_id);
  RAISE EXCEPTION 'REIMPORT_WRITER_CANONICAL_DELTA_UNSUPPORTED';
END $$;
CREATE OR REPLACE FUNCTION public.red_lock_reimport_name_completion(p_manifest_sha256 text,p_source_id bigint,p_profile_id text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' OR NOT EXISTS(SELECT 1 FROM private.reimport_writer_profile WHERE source_id=p_source_id AND profile_id=p_profile_id) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  PERFORM private.require_reimport_writer_editor();
  PERFORM private.lock_reimport_writer(p_source_id,p_profile_id);
END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_reimport_name_completion(p_manifest_sha256 text,p_source_batch_id uuid,p_source_manifest_bytes_sha256 text,p_source_manifest_content_sha256 text,p_source_id bigint,p_profile_id text,p_profile_sha256 text,p_expected_counts jsonb,p_payloads jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$
DECLARE b private.reimport_batch%ROWTYPE; a private.reimport_authorization%ROWTYPE; v_id uuid; v_actor uuid;
  v_discovered_source_id bigint; v_discovered_profile_id text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>2 THEN RAISE EXCEPTION 'REIMPORT_NARRATIVE_RECORD_CONTRACT_REQUIRED'; END IF;
  IF p_manifest_sha256 !~ '^[0-9a-f]{64}$' OR p_source_manifest_bytes_sha256 !~ '^[0-9a-f]{64}$' OR p_source_manifest_content_sha256 !~ '^[0-9a-f]{64}$' OR jsonb_typeof(p_expected_counts)<>'object' OR jsonb_typeof(p_payloads)<>'object' THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  v_actor:=private.require_reimport_writer_editor();
  SELECT source_id,profile_id INTO v_discovered_source_id,v_discovered_profile_id FROM private.reimport_batch WHERE id=p_source_batch_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  PERFORM private.lock_reimport_writer(v_discovered_source_id,v_discovered_profile_id);
  SELECT * INTO b FROM private.reimport_batch WHERE id=p_source_batch_id FOR UPDATE;
  SELECT * INTO a FROM private.reimport_authorization WHERE id=b.authorization_id FOR UPDATE;
  IF NOT FOUND OR b.source_id IS DISTINCT FROM v_discovered_source_id OR b.profile_id IS DISTINCT FROM v_discovered_profile_id OR b.status<>'finalized' OR a.operation<>'reimport' OR a.principal_id<>v_actor OR b.source_id<>a.source_id OR b.profile_id<>a.profile_id OR b.profile_sha256<>a.profile_sha256 OR b.preview_sha256<>p_source_manifest_bytes_sha256 OR b.manifest_sha256<>p_source_manifest_content_sha256 OR b.source_id IS DISTINCT FROM p_source_id OR b.profile_id IS DISTINCT FROM p_profile_id OR b.profile_sha256 IS DISTINCT FROM p_profile_sha256 OR NOT EXISTS(SELECT 1 FROM private.reimport_writer_profile profile WHERE profile.source_id=p_source_id AND profile.profile_id=p_profile_id AND profile.profile_sha256=p_profile_sha256) THEN RAISE EXCEPTION 'REIMPORT_NAME_COMPLETION_INVALID'; END IF;
  INSERT INTO private.reimport_authorization(operation,manifest_sha256,preview_sha256,database_identity,source_id,profile_id,profile_sha256,expected_counts,authorized_elements,principal_id,nonce,expires_at) VALUES('name_completion',p_manifest_sha256,p_source_manifest_content_sha256,jsonb_build_object('database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text)::text,b.source_id,b.profile_id,b.profile_sha256,p_expected_counts,jsonb_build_object('source_batch_id',p_source_batch_id,'payloads',p_payloads,'source_manifest_bytes_sha256',p_source_manifest_bytes_sha256,'source_manifest_content_sha256',p_source_manifest_content_sha256),v_actor,gen_random_uuid(),clock_timestamp()+interval '5 minutes') RETURNING id INTO v_id;
  PERFORM private.validate_reimport_name_completion(v_id,p_source_batch_id,p_manifest_sha256,p_payloads);
  RETURN jsonb_build_object('authorization_id',v_id,'database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text,'source',jsonb_build_object('id',b.source_id,'profile_id',b.profile_id,'profile_sha256',b.profile_sha256));
END $$;
CREATE OR REPLACE FUNCTION public.red_apply_1939_v50_canonical_delta(b uuid,e text,p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM public.red_apply_reimport_canonical_delta(b,e,p); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_CANONICAL_DELTA_UNSUPPORTED' THEN RAISE EXCEPTION 'REIMPORT_1939_CANONICAL_DELTA_UNSUPPORTED'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_lock_1939_v50_name_completion(m text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ BEGIN PERFORM public.red_lock_reimport_name_completion(m,3,'daa-1939-v50-production-write-v1'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_WRITER_ROLE_FORBIDDEN' THEN RAISE EXCEPTION 'REIMPORT_1939_ROLE_FORBIDDEN'; END IF; IF SQLERRM='REIMPORT_NAME_COMPLETION_INVALID' THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_LOCK_INVALID'; END IF; RAISE; END $$;
CREATE OR REPLACE FUNCTION public.red_authorize_1939_v50_name_completion(m text,b uuid,mb text,mc text,c jsonb,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,private AS $$ DECLARE r jsonb; BEGIN r:=public.red_authorize_reimport_name_completion(m,b,mb,mc,3,'daa-1939-v50-production-write-v1',(SELECT profile_sha256 FROM private.reimport_writer_profile WHERE source_id=3 AND profile_id='daa-1939-v50-production-write-v1'),c,p); RETURN jsonb_build_object('authorization_id',r->>'authorization_id','database_name',current_database(),'system_identifier',(pg_control_system()).system_identifier::text); EXCEPTION WHEN OTHERS THEN IF SQLERRM='REIMPORT_NAME_COMPLETION_INVALID' THEN RAISE EXCEPTION 'NAME_COMPLETION_1939_AUTHORIZATION_INVALID'; END IF; RAISE; END $$;
DROP FUNCTION IF EXISTS public.red_lock_reimport_name_completion(text);
DROP FUNCTION IF EXISTS public.red_authorize_reimport_name_completion(text,uuid,text,text,jsonb,jsonb);
REVOKE ALL ON FUNCTION public.red_apply_reimport_canonical_delta(uuid,text,jsonb),public.red_lock_reimport_name_completion(text,bigint,text),public.red_authorize_reimport_name_completion(text,uuid,text,text,bigint,text,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.red_apply_reimport_canonical_delta(uuid,text,jsonb),public.red_lock_reimport_name_completion(text,bigint,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.red_authorize_reimport_name_completion(text,uuid,text,text,bigint,text,text,jsonb,jsonb) TO service_role;

-- Opt-in regression failpoint: a test can prove that a failure after views and
-- wrappers are installed still rolls the complete #153 transition back.
DO $reimport_writer_atomicity_test_failpoint$
BEGIN
  IF current_setting('app.reimport_writer_atomicity_test_failpoint',true)='on' THEN
    RAISE EXCEPTION 'REIMPORT_WRITER_ATOMICITY_TEST_FAILURE';
  END IF;
END $reimport_writer_atomicity_test_failpoint$;

-- The #153 conversion is deliberately one transaction: quiescence, physical
-- rename/transfer, generic writer definitions, and the legacy facade either
-- appear together or leave the pre-153 ledger untouched.
COMMIT;

CREATE OR REPLACE FUNCTION private.apply_narrative_record_cutover(
  p_record_candidates_raw text,p_legacy_candidates_raw text,
  p_record_manifest_raw text,p_legacy_manifest_raw text,
  p_inventory_raw text,p_approval_raw text,
  p_nonce uuid,p_expected_database_name text,
  p_expected_system_identifier text
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog
AS $$
DECLARE
  v_record_candidates jsonb;
  v_legacy_candidates jsonb;
  v_record_manifest jsonb;
  v_legacy_manifest jsonb;
  v_inventory jsonb;
  v_approval jsonb;
  v_record_candidates_sha text;
  v_legacy_candidates_sha text;
  v_record_manifest_sha text;
  v_legacy_manifest_sha text;
  v_inventory_sha text;
  v_approval_sha text;
  v_database_name text;
  v_system_identifier text;
  v_candidate_record_ids jsonb;
  v_manifest_record_ids jsonb;
  v_candidate_legacy_ids jsonb;
  v_keep_ids jsonb;
  v_hide_ids jsonb;
  v_live jsonb;
  v_expected jsonb;
  v_live_accepted_identity_count bigint;
  v_live_blocked_record_count bigint;
  v_row jsonb;
  v_state jsonb;
  v_state_sha text;
  v_editor jsonb;
  v_event_id uuid;
  v_change_set_id bigint;
  v_change_sequence regclass;
  v_change_sequence_last bigint;
  v_change_sequence_called boolean;
  v_change_sequence_floor bigint;
  v_change_set_max bigint;
  v_record_results jsonb:='[]'::jsonb;
  v_legacy_results jsonb:='[]'::jsonb;
  v_sequence regclass;
  v_sequence_before bigint;
  v_sequence_floor bigint;
  v_sequence_after bigint;
  v_max_narrative bigint;
  v_max_change_event bigint;
  v_max_publication_event bigint;
  v_result jsonb;
  v_result_sha text;
BEGIN
  IF p_nonce IS NULL THEN
    RAISE EXCEPTION 'CUTOVER_NONCE_REQUIRED';
  END IF;
  IF p_record_candidates_raw IS NULL OR p_legacy_candidates_raw IS NULL
     OR p_record_manifest_raw IS NULL OR p_legacy_manifest_raw IS NULL
     OR p_inventory_raw IS NULL OR p_approval_raw IS NULL THEN
    RAISE EXCEPTION 'CUTOVER_RAW_ARTIFACT_REQUIRED';
  END IF;

  -- Hash the six raw UTF-8 arguments before parsing. Receipt/recovery identity is
  -- the byte identity, never a reserialized jsonb value.
  v_record_candidates_sha:=encode(
    extensions.digest(convert_to(p_record_candidates_raw,'UTF8'),'sha256'),'hex');
  v_legacy_candidates_sha:=encode(
    extensions.digest(convert_to(p_legacy_candidates_raw,'UTF8'),'sha256'),'hex');
  v_record_manifest_sha:=encode(
    extensions.digest(convert_to(p_record_manifest_raw,'UTF8'),'sha256'),'hex');
  v_legacy_manifest_sha:=encode(
    extensions.digest(convert_to(p_legacy_manifest_raw,'UTF8'),'sha256'),'hex');
  v_inventory_sha:=encode(
    extensions.digest(convert_to(p_inventory_raw,'UTF8'),'sha256'),'hex');
  v_approval_sha:=encode(
    extensions.digest(convert_to(p_approval_raw,'UTF8'),'sha256'),'hex');
  BEGIN
    v_record_candidates:=p_record_candidates_raw::jsonb;
    v_legacy_candidates:=p_legacy_candidates_raw::jsonb;
    v_record_manifest:=p_record_manifest_raw::jsonb;
    v_legacy_manifest:=p_legacy_manifest_raw::jsonb;
    v_inventory:=p_inventory_raw::jsonb;
    v_approval:=p_approval_raw::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'CUTOVER_ARTIFACT_JSON_INVALID';
  END;

  IF v_record_candidates->>'schema_version'<>'narrative-record-baseline-candidates-v1'
     OR v_legacy_candidates->>'schema_version'<>'narrative-legacy-baseline-candidates-v1'
     OR v_record_manifest->>'schema_version'<>'narrative-record-baseline-manifest-v1'
     OR v_legacy_manifest->>'schema_version'<>'narrative-legacy-baseline-manifest-v1'
     OR v_inventory->>'schema_version'<>'narrative-record-cutover-inventory-v1'
     OR v_approval->>'schema_version'<>'narrative-record-cutover-approval-v1'
     OR jsonb_typeof(v_record_candidates->'rows')<>'array'
     OR jsonb_typeof(v_legacy_candidates->'rows')<>'array'
     OR jsonb_typeof(v_record_manifest->'rows')<>'array'
     OR jsonb_typeof(v_legacy_manifest->'rows')<>'array' THEN
    RAISE EXCEPTION 'CUTOVER_ARTIFACT_SCHEMA_INVALID';
  END IF;

  SELECT current_database(),(pg_control_system()).system_identifier::text
    INTO v_database_name,v_system_identifier;
  IF p_expected_database_name IS DISTINCT FROM v_database_name
     OR p_expected_system_identifier IS DISTINCT FROM v_system_identifier THEN
    RAISE EXCEPTION 'CUTOVER_DATABASE_IDENTITY_MISMATCH';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM (VALUES
        (v_record_candidates->'database'),(v_legacy_candidates->'database'),
        (v_record_manifest->'database'),(v_legacy_manifest->'database'),
        (v_inventory->'database'),(v_approval->'database')
      ) artifact(database)
     WHERE artifact.database IS DISTINCT FROM jsonb_build_object(
       'database_name',v_database_name,'system_identifier',v_system_identifier
     )
  ) THEN
    RAISE EXCEPTION 'CUTOVER_ARTIFACT_DATABASE_IDENTITY_MISMATCH';
  END IF;
  IF v_record_manifest->>'record_candidates_sha256' IS DISTINCT FROM
       v_record_candidates_sha
     OR v_legacy_manifest->>'legacy_candidates_sha256' IS DISTINCT FROM
       v_legacy_candidates_sha
     OR v_approval #>> '{input_hashes,record_candidates_sha256}' IS DISTINCT FROM
       v_record_candidates_sha
     OR v_approval #>> '{input_hashes,legacy_candidates_sha256}' IS DISTINCT FROM
       v_legacy_candidates_sha
     OR v_approval #>> '{input_hashes,record_manifest_sha256}' IS DISTINCT FROM
       v_record_manifest_sha
     OR v_approval #>> '{input_hashes,legacy_manifest_sha256}' IS DISTINCT FROM
       v_legacy_manifest_sha
     OR v_approval #>> '{input_hashes,inventory_sha256}' IS DISTINCT FROM
       v_inventory_sha THEN
    RAISE EXCEPTION 'CUTOVER_ARTIFACT_HASH_MISMATCH';
  END IF;

  SELECT coalesce(jsonb_agg(row->'binding_id' ORDER BY row->>'binding_id'),'[]'::jsonb),
         coalesce(jsonb_agg(row-'row_sha256' ORDER BY row->>'binding_id'),'[]'::jsonb)
    INTO v_candidate_record_ids,v_expected
    FROM jsonb_array_elements(v_record_candidates->'rows') row;
  SELECT coalesce(jsonb_agg(row->'binding_id' ORDER BY row->>'binding_id'),'[]'::jsonb),
         coalesce(jsonb_agg(row-'row_sha256' ORDER BY row->>'binding_id'),'[]'::jsonb)
    INTO v_manifest_record_ids,v_live
    FROM jsonb_array_elements(v_record_manifest->'rows') row;
  IF v_manifest_record_ids IS DISTINCT FROM v_candidate_record_ids
     OR v_live IS DISTINCT FROM v_expected
     OR v_approval->'record_approved_ids' IS DISTINCT FROM v_candidate_record_ids THEN
    RAISE EXCEPTION 'CUTOVER_RECORD_MANIFEST_IDENTITY_MISMATCH';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'binding_id',row->'binding_id','row_sha256',row->'row_sha256'
         ) ORDER BY row->>'binding_id'),'[]'::jsonb)
    INTO v_expected
    FROM jsonb_array_elements(v_record_candidates->'rows') row;
  IF v_approval->'record_approved_rows' IS DISTINCT FROM v_expected
     OR jsonb_array_length(v_candidate_record_ids)<>
        (SELECT count(DISTINCT row->>'binding_id')
           FROM jsonb_array_elements(v_record_candidates->'rows') row) THEN
    RAISE EXCEPTION 'CUTOVER_RECORD_APPROVAL_IDENTITY_MISMATCH';
  END IF;

  SELECT coalesce(jsonb_agg(row->'narrative_id' ORDER BY (row->>'narrative_id')::bigint),'[]'::jsonb)
    INTO v_candidate_legacy_ids
    FROM jsonb_array_elements(v_legacy_candidates->'rows') row;
  SELECT coalesce(jsonb_agg(row->'narrative_id' ORDER BY (row->>'narrative_id')::bigint),'[]'::jsonb)
    INTO v_keep_ids
    FROM jsonb_array_elements(v_legacy_manifest->'rows') row;
  v_hide_ids:=coalesce(v_approval->'legacy_hide_ids','[]'::jsonb);
  IF v_approval->'legacy_keep_ids' IS DISTINCT FROM v_keep_ids
     OR jsonb_array_length(v_candidate_legacy_ids)<>
        (SELECT count(DISTINCT (row->>'narrative_id')::bigint)
           FROM jsonb_array_elements(v_legacy_candidates->'rows') row)
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_keep_ids) keep
       JOIN jsonb_array_elements(v_hide_ids) hide ON keep=hide
     )
     OR (SELECT coalesce(jsonb_agg(value ORDER BY (value #>> '{}')::bigint),'[]'::jsonb)
           FROM (
             SELECT value FROM jsonb_array_elements(v_keep_ids)
             UNION ALL
             SELECT value FROM jsonb_array_elements(v_hide_ids)
           ) partition_rows) IS DISTINCT FROM v_candidate_legacy_ids THEN
    RAISE EXCEPTION 'CUTOVER_LEGACY_PARTITION_INVALID';
  END IF;
  SELECT coalesce(jsonb_agg(candidate ORDER BY (candidate->>'narrative_id')::bigint),'[]'::jsonb)
    INTO v_expected
    FROM jsonb_array_elements(v_legacy_candidates->'rows') candidate
   WHERE candidate->'narrative_id' IN (SELECT value FROM jsonb_array_elements(v_keep_ids));
  IF v_legacy_manifest->'rows' IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'CUTOVER_LEGACY_MANIFEST_IDENTITY_MISMATCH';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'narrative_id',row->'narrative_id',
           'legacy_publication_ref',row->'legacy_publication_ref',
           'row_sha256',row->'row_sha256'
         ) ORDER BY (row->>'narrative_id')::bigint),'[]'::jsonb)
    INTO v_expected
    FROM jsonb_array_elements(v_legacy_manifest->'rows') row;
  IF v_approval->'legacy_keep_rows' IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'CUTOVER_LEGACY_KEEP_ROWS_MISMATCH';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'narrative_id',row->'narrative_id','row_sha256',row->'row_sha256'
         ) ORDER BY (row->>'narrative_id')::bigint),'[]'::jsonb)
    INTO v_expected
    FROM jsonb_array_elements(v_legacy_candidates->'rows') row
   WHERE row->'narrative_id' IN (SELECT value FROM jsonb_array_elements(v_hide_ids));
  IF v_approval->'legacy_hide_rows' IS DISTINCT FROM v_expected
     OR (v_approval #>> '{counts,record_approved}')::integer<>
          jsonb_array_length(v_candidate_record_ids)
     OR (v_approval #>> '{counts,legacy_candidates}')::integer<>
          jsonb_array_length(v_candidate_legacy_ids)
     OR (v_approval #>> '{counts,legacy_keep}')::integer<>jsonb_array_length(v_keep_ids)
     OR (v_approval #>> '{counts,legacy_hide}')::integer<>jsonb_array_length(v_hide_ids) THEN
    RAISE EXCEPTION 'CUTOVER_APPROVAL_COUNTS_OR_HIDE_ROWS_MISMATCH';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_id',source_count.source_id,
           'record_candidates',source_count.record_candidates,
           'legacy_candidates',source_count.legacy_candidates
         ) ORDER BY source_count.source_id),'[]'::jsonb)
    INTO v_expected
    FROM (
      SELECT candidate.source_id,
             count(*) FILTER (WHERE candidate.kind='record')::integer AS record_candidates,
             count(*) FILTER (WHERE candidate.kind='legacy')::integer AS legacy_candidates
        FROM (
          SELECT (row->>'source_id')::bigint AS source_id,'record'::text AS kind
            FROM jsonb_array_elements(v_record_candidates->'rows') row
          UNION ALL
          SELECT (row->>'source_id')::bigint,'legacy'::text
            FROM jsonb_array_elements(v_legacy_candidates->'rows') row
        ) candidate
       GROUP BY candidate.source_id
    ) source_count;
  IF v_inventory->'record_candidate_ids' IS DISTINCT FROM v_candidate_record_ids
     OR v_inventory->'legacy_candidate_ids' IS DISTINCT FROM v_candidate_legacy_ids
     OR v_inventory->'counts_by_source' IS DISTINCT FROM v_expected
     OR jsonb_typeof(v_inventory->'accepted_identity_count')<>'number'
     OR jsonb_typeof(v_inventory->'identity_blocked_record_count')<>'number'
     OR (v_inventory->>'accepted_identity_count')::bigint<0
     OR (v_inventory->>'identity_blocked_record_count')::bigint<0
     OR v_inventory->'classified_direct_readers' IS DISTINCT FROM jsonb_build_array(
       jsonb_build_object('path','mobile/src/data/about.ts','classification','non_person_control'),
       jsonb_build_object('path','mobile/src/data/haendelser.ts','classification','rls_gated_metadata'),
       jsonb_build_object('path','mobile/src/data/load.ts','classification','v2_public_rpc'),
       jsonb_build_object('path','mobile/src/data/presensLinjer.ts','classification','non_person_control'),
       jsonb_build_object('path','mobile/src/data/publicBioVersions.ts','classification','v2_public_rpc'),
       jsonb_build_object('path','mobile/src/data/redaktionRead.ts','classification','v2_editor_rpc'),
       jsonb_build_object('path','web/src/data/feedAux.ts','classification','v2_public_rpc'),
       jsonb_build_object('path','web/src/data/haendelser.ts','classification','rls_gated_metadata'),
       jsonb_build_object('path','web/src/data/presensLinjer.ts','classification','non_person_control'),
       jsonb_build_object('path','web/src/data/public.ts','classification','v2_public_rpc'),
       jsonb_build_object('path','web/src/data/redaktionRead.ts','classification','v2_editor_rpc')
     ) THEN
    RAISE EXCEPTION 'CUTOVER_INVENTORY_IDENTITY_MISMATCH';
  END IF;

  -- The exclusive gate is acquired before version/live-state validation. The
  -- table locks freeze both existing rows and absence sets through commit.
  PERFORM pg_advisory_xact_lock(hashtextextended('daa-narrative-record-contract',0));
  IF public.narrative_record_contract_version()<>1 THEN
    RAISE EXCEPTION 'CUTOVER_CONTRACT_VERSION_NOT_ONE';
  END IF;
  IF EXISTS (SELECT 1 FROM private.narrative_record_cutover_receipt
              WHERE nonce=p_nonce) THEN
    RAISE EXCEPTION 'CUTOVER_NONCE_ALREADY_USED';
  END IF;
  LOCK TABLE private.narrative_record_publication,
    private.narrative_legacy_publication,
    private.narrative_publication_event IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.narrative,public.change_set IN SHARE ROW EXCLUSIVE MODE;
  -- Canonical publication state also depends on source evidence, current
  -- placements/identity, labels and person policy. SHARE conflicts with every
  -- INSERT/UPDATE/DELETE writer while allowing the cutover's read-only measure.
  LOCK TABLE private.source_record,
    private.source_record_occurrence,
    private.source_rendition,
    private.source_record_anchor_event,
    private.source_record_placement,
    private.source_record_placement_decision,
    private.source_persona,
    private.source_persona_placement,
    private.source_persona_placement_decision,
    private.source_persona_identity_event,
    private.source_persona_identity,
    private.source_record_revision_event,
    public.person,public.source,public.lineage_scheme_entry,public.haendelse
    IN SHARE MODE;

  SELECT count(*)::bigint INTO v_live_accepted_identity_count
    FROM private.source_persona_identity identity_state
    JOIN private.source_persona persona
      ON persona.id=identity_state.source_persona_id
    JOIN public.source source ON source.id=persona.source_id
   WHERE source.slags='DAA-udgave'
     AND identity_state.decision_status='accepted';
  SELECT count(*)::bigint INTO v_live_blocked_record_count
    FROM private.source_record record
    JOIN public.source source ON source.id=record.source_id
   WHERE source.slags='DAA-udgave'
     AND (SELECT count(DISTINCT identity_state.canonical_person_id)
            FROM private.source_record_placement_current record_placement
            JOIN private.source_persona_placement_current persona_placement
              ON persona_placement.record_placement_id=record_placement.id
            JOIN private.source_persona_identity identity_state
              ON identity_state.source_persona_id=persona_placement.source_persona_id
           WHERE record_placement.source_record_id=record.id
             AND record_placement.decision_status='accepted'
             AND persona_placement.decision_status='accepted'
             AND persona_placement.placement_role IN ('principal_member','co_principal')
             AND identity_state.decision_status='accepted')<>1;
  IF v_live_accepted_identity_count IS DISTINCT FROM
       (v_inventory->>'accepted_identity_count')::bigint
     OR v_live_blocked_record_count IS DISTINCT FROM
       (v_inventory->>'identity_blocked_record_count')::bigint THEN
    RAISE EXCEPTION 'CUTOVER_INVENTORY_LIVE_DRIFT';
  END IF;

  SELECT coalesce(jsonb_agg(live.value ORDER BY live.binding_id),'[]'::jsonb)
    INTO v_live
    FROM (
      SELECT binding.id::text AS binding_id,jsonb_build_object(
           'binding_id',binding.id::text,
           'narrative_id',narrative.id,
           'person_id',narrative.subjekt_id,
           'source_id',narrative.source_id,
           'source_kind',source.slags,
           'source_record_id',record.id::text,
           'record_key',record.record_key,
           'status',binding.status,
           'record_label',binding.record_label,
           'citation_label',binding.citation_label,
           'publication_state_sha256',encode(extensions.digest(
             private.narrative_publication_state(
               narrative.subjekt_id,narrative.source_id,record.record_key
             )::text,'sha256'),'hex'),
           'narrative_text_sha256',encode(extensions.digest(narrative.tekst,'sha256'),'hex'),
           'binding_match_count',count(*) OVER (PARTITION BY narrative.id)
         ) AS value
        FROM private.narrative_record_publication binding
        JOIN public.narrative narrative ON narrative.id=binding.narrative_id
        JOIN private.source_record record ON record.id=binding.source_record_id
        JOIN public.source source ON source.id=narrative.source_id
       WHERE source.slags='DAA-udgave'
    ) live;
  SELECT coalesce(jsonb_agg(row-'row_sha256' ORDER BY row->>'binding_id'),'[]'::jsonb)
    INTO v_expected
    FROM jsonb_array_elements(v_record_candidates->'rows') row;
  IF v_live IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'CUTOVER_RECORD_LIVE_SET_DRIFT';
  END IF;

  SELECT coalesce(jsonb_agg(narrative.id ORDER BY narrative.id),'[]'::jsonb)
    INTO v_live
    FROM public.narrative narrative
    JOIN public.person person
      ON person.id=narrative.subjekt_id AND narrative.subjekt_type='person'
    JOIN public.source source
      ON source.id=narrative.source_id AND source.slags='DAA-udgave'
   WHERE coalesce(narrative.privat,false)=false
     AND person.levende=false
     AND coalesce(person.privat,false)=false
     AND coalesce(person.staged,false)=false
     AND NOT EXISTS (SELECT 1 FROM private.narrative_record_publication binding
                      WHERE binding.narrative_id=narrative.id)
     AND NOT EXISTS (SELECT 1 FROM private.narrative_legacy_publication legacy
                      WHERE legacy.narrative_id=narrative.id);
  IF v_live IS DISTINCT FROM v_candidate_legacy_ids THEN
    RAISE EXCEPTION 'CUTOVER_LEGACY_LIVE_SET_DRIFT';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'legacy_publication_ref',row->>'legacy_publication_ref',
           'narrative_id',narrative.id,
           'person_id',narrative.subjekt_id,
           'source_id',narrative.source_id,
           'source_kind',source.slags,
           'narrative_text_sha256',encode(extensions.digest(narrative.tekst,'sha256'),'hex'),
           'baseline_sha256',encode(extensions.digest(
             private.narrative_legacy_candidate_publication_state(
               narrative.id,narrative.source_id,(row->>'legacy_publication_ref')::uuid
             )::text,'sha256'),'hex'),
           'binding_match_count',0
         ) ORDER BY narrative.id),'[]'::jsonb)
    INTO v_live
    FROM jsonb_array_elements(v_legacy_candidates->'rows') row
    JOIN public.narrative narrative ON narrative.id=(row->>'narrative_id')::bigint
    JOIN public.source source ON source.id=narrative.source_id;
  SELECT coalesce(jsonb_agg(row-'row_sha256' ORDER BY (row->>'narrative_id')::bigint),'[]'::jsonb)
    INTO v_expected
    FROM jsonb_array_elements(v_legacy_candidates->'rows') row;
  IF v_live IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'CUTOVER_LEGACY_BASELINE_DRIFT';
  END IF;
  IF EXISTS (
    SELECT 1 FROM private.narrative_publication_event event
     WHERE event.binding_id IN (
       SELECT (row->>'binding_id')::uuid
         FROM jsonb_array_elements(v_record_manifest->'rows') row
     )
  ) THEN
    RAISE EXCEPTION 'CUTOVER_RECORD_STREAM_NOT_EMPTY';
  END IF;

  LOCK TABLE public.change_set IN ACCESS EXCLUSIVE MODE;
  v_change_sequence:=pg_get_serial_sequence('public.change_set','id')::regclass;
  IF v_change_sequence IS NULL THEN
    RAISE EXCEPTION 'CUTOVER_CHANGE_SET_SEQUENCE_MISSING';
  END IF;
  EXECUTE format('SELECT last_value::bigint,is_called FROM %s',v_change_sequence)
    INTO v_change_sequence_last,v_change_sequence_called;
  SELECT coalesce(max(change_set.id),0) INTO v_change_set_max
    FROM public.change_set change_set;
  v_change_sequence_floor:=greatest(
    CASE WHEN v_change_sequence_called
         THEN v_change_sequence_last+1 ELSE v_change_sequence_last END,
    v_change_set_max+1
  );
  EXECUTE format(
    'ALTER SEQUENCE %s RESTART WITH %s',v_change_sequence,v_change_sequence_floor
  );
  INSERT INTO public.change_set(
    actor_navn,actor_rolle,operation,summary,subjekt_synlighed
  ) VALUES (
    'Narrative record cutover','system',
    'narrative_record_contract_cutover',
    format('Narrative record contract cutover %s',p_nonce),'offentlig'
  ) RETURNING id INTO v_change_set_id;

  FOR v_row IN
    SELECT row FROM jsonb_array_elements(v_record_manifest->'rows') row
     ORDER BY row->>'binding_id'
  LOOP
    SELECT private.narrative_publication_state(
             narrative.subjekt_id,narrative.source_id,record.record_key
           )
      INTO v_state
      FROM private.narrative_record_publication binding
      JOIN public.narrative narrative ON narrative.id=binding.narrative_id
      JOIN private.source_record record ON record.id=binding.source_record_id
     WHERE binding.id=(v_row->>'binding_id')::uuid;
    v_state_sha:=encode(extensions.digest(v_state::text,'sha256'),'hex');
    IF v_state_sha IS DISTINCT FROM v_row->>'publication_state_sha256' THEN
      RAISE EXCEPTION 'CUTOVER_RECORD_BASELINE_HASH_DRIFT';
    END IF;
    INSERT INTO private.narrative_publication_event(
      change_set_id,stream_ref,stream_version,event_type,binding_id,narrative_id,
      source_id,source_record_id,decision_basis,before_state,after_state,
      before_state_sha256,after_state_sha256,decided_by_name
    ) VALUES (
      v_change_set_id,(v_row->>'binding_id')::uuid,1,'baseline',
      (v_row->>'binding_id')::uuid,(v_row->>'narrative_id')::bigint,
      (v_row->>'source_id')::bigint,(v_row->>'source_record_id')::uuid,
      format('Godkendt baseline ved contract cutover %s',p_nonce),
      v_state,v_state,v_state_sha,v_state_sha,'Narrative record cutover'
    ) RETURNING id INTO v_event_id;
    v_editor:=private.narrative_record_state(
      (v_row->>'person_id')::bigint,(v_row->>'source_id')::bigint,
      v_row->>'record_key',false
    );
    IF v_editor->>'latest_event_id' IS DISTINCT FROM v_event_id::text
       OR v_editor->>'publication_state_sha256' IS DISTINCT FROM v_state_sha THEN
      RAISE EXCEPTION 'CUTOVER_RECORD_POSTSTATE_MISMATCH';
    END IF;
    v_record_results:=v_record_results||jsonb_build_array(jsonb_build_object(
      'binding_id',v_row->>'binding_id','narrative_id',v_row->'narrative_id',
      'event_id',v_event_id,'publication_state_sha256',v_state_sha,
      'state_sha256',v_editor->>'state_sha256'
    ));
  END LOOP;

  FOR v_row IN
    SELECT row FROM jsonb_array_elements(v_legacy_manifest->'rows') row
     ORDER BY (row->>'narrative_id')::bigint
  LOOP
    v_state:=private.narrative_legacy_candidate_publication_state(
      (v_row->>'narrative_id')::bigint,(v_row->>'source_id')::bigint,
      (v_row->>'legacy_publication_ref')::uuid
    );
    v_state_sha:=encode(extensions.digest(v_state::text,'sha256'),'hex');
    IF v_state_sha IS DISTINCT FROM v_row->>'baseline_sha256' THEN
      RAISE EXCEPTION 'CUTOVER_LEGACY_BASELINE_HASH_DRIFT';
    END IF;
    INSERT INTO private.narrative_legacy_publication(
      legacy_publication_ref,narrative_id,source_id,baseline_state,
      baseline_sha256,status
    ) VALUES (
      (v_row->>'legacy_publication_ref')::uuid,
      (v_row->>'narrative_id')::bigint,(v_row->>'source_id')::bigint,
      v_state,v_state_sha,'grandfathered_publication'
    );
    INSERT INTO private.narrative_publication_event(
      change_set_id,stream_ref,stream_version,event_type,narrative_id,source_id,
      legacy_publication_ref,decision_basis,before_state,after_state,
      before_state_sha256,after_state_sha256,decided_by_name
    ) VALUES (
      v_change_set_id,(v_row->>'legacy_publication_ref')::uuid,1,'baseline',
      (v_row->>'narrative_id')::bigint,(v_row->>'source_id')::bigint,
      (v_row->>'legacy_publication_ref')::uuid,
      format('Godkendt grandfathered baseline ved contract cutover %s',p_nonce),
      v_state,v_state,v_state_sha,v_state_sha,'Narrative record cutover'
    ) RETURNING id INTO v_event_id;
    UPDATE private.narrative_legacy_publication legacy
       SET latest_event_id=v_event_id
     WHERE legacy.legacy_publication_ref=(v_row->>'legacy_publication_ref')::uuid;
    v_editor:=private.narrative_legacy_state(
      (v_row->>'legacy_publication_ref')::uuid,false
    );
    IF v_editor->>'latest_event_id' IS DISTINCT FROM v_event_id::text
       OR v_editor->>'publication_state_sha256' IS DISTINCT FROM v_state_sha
       OR v_editor->>'baseline_matches' IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION 'CUTOVER_LEGACY_POSTSTATE_MISMATCH';
    END IF;
    v_legacy_results:=v_legacy_results||jsonb_build_array(jsonb_build_object(
      'legacy_publication_ref',v_row->>'legacy_publication_ref',
      'narrative_id',v_row->'narrative_id','event_id',v_event_id,
      'publication_state_sha256',v_state_sha,
      'state_sha256',v_editor->>'state_sha256'
    ));
  END LOOP;

  v_sequence:=pg_get_serial_sequence('public.narrative','id')::regclass;
  IF v_sequence IS NULL THEN
    RAISE EXCEPTION 'CUTOVER_NARRATIVE_SEQUENCE_MISSING';
  END IF;
  EXECUTE format('SELECT last_value::bigint FROM %s',v_sequence)
    INTO v_sequence_before;
  SELECT coalesce(max(narrative.id),0) INTO v_max_narrative
    FROM public.narrative narrative;
  SELECT coalesce(max(greatest(
           CASE WHEN event.row_pk->>'id' ~ '^[0-9]+$'
                THEN (event.row_pk->>'id')::bigint ELSE 0 END,
           CASE WHEN event.foer->>'id' ~ '^[0-9]+$'
                THEN (event.foer->>'id')::bigint ELSE 0 END,
           CASE WHEN event.efter->>'id' ~ '^[0-9]+$'
                THEN (event.efter->>'id')::bigint ELSE 0 END
         )),0)
    INTO v_max_change_event
    FROM public.change_event event
   WHERE event.tabel='narrative';
  SELECT coalesce(max(event.narrative_id),0) INTO v_max_publication_event
    FROM private.narrative_publication_event event;
  v_sequence_floor:=greatest(
    v_sequence_before,v_max_narrative,v_max_change_event,v_max_publication_event
  )+1;
  -- ALTER SEQUENCE RESTART is transactional; setval is not and would make the
  -- gateway's real rollback mode leak sequence state outside the rollback.
  EXECUTE format('ALTER SEQUENCE %s RESTART WITH %s',v_sequence,v_sequence_floor);
  EXECUTE format('SELECT last_value::bigint FROM %s',v_sequence)
    INTO v_sequence_after;
  IF v_sequence_after<v_sequence_before OR v_sequence_after<>v_sequence_floor THEN
    RAISE EXCEPTION 'CUTOVER_NARRATIVE_SEQUENCE_NOT_MONOTONE';
  END IF;

  v_result:=jsonb_build_object(
    'nonce',p_nonce,'database',jsonb_build_object(
      'database_name',v_database_name,'system_identifier',v_system_identifier),
    'contract_version_before',1,'contract_version_after',2,
    'change_set_id',v_change_set_id,
    'record_events',v_record_results,'legacy_events',v_legacy_results,
    'legacy_hidden_ids',v_hide_ids,
    'sequence',jsonb_build_object(
      'before',v_sequence_before,'floor',v_sequence_floor,'after',v_sequence_after),
    'input_hashes',jsonb_build_object(
      'record_candidates_sha256',v_record_candidates_sha,
      'legacy_candidates_sha256',v_legacy_candidates_sha,
      'record_manifest_sha256',v_record_manifest_sha,
      'legacy_manifest_sha256',v_legacy_manifest_sha,
      'inventory_sha256',v_inventory_sha,'approval_sha256',v_approval_sha)
  );
  v_result_sha:=encode(extensions.digest(v_result::text,'sha256'),'hex');
  INSERT INTO private.narrative_record_cutover_receipt(
    nonce,record_candidates_sha256,legacy_candidates_sha256,
    record_manifest_sha256,legacy_manifest_sha256,inventory_sha256,approval_sha256,
    database_name,system_identifier,sequence_before,sequence_floor,sequence_after,
    result,result_sha256
  ) VALUES (
    p_nonce,v_record_candidates_sha,v_legacy_candidates_sha,
    v_record_manifest_sha,v_legacy_manifest_sha,v_inventory_sha,v_approval_sha,
    v_database_name,v_system_identifier,v_sequence_before,v_sequence_floor,
    v_sequence_after,v_result,v_result_sha
  );

  PERFORM private.apply_narrative_record_contract_acl(2);
  -- Version is deliberately the final write in the cutover transaction.
  UPDATE private.narrative_record_contract contract
     SET version=2,changed_at=clock_timestamp()
   WHERE contract.singleton AND contract.version=1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CUTOVER_CONTRACT_VERSION_UPDATE_FAILED';
  END IF;
  RETURN v_result;
END
$$;

REVOKE ALL ON FUNCTION private.apply_narrative_record_cutover(
  text,text,text,text,text,text,uuid,text,text
) FROM PUBLIC,anon,authenticated,service_role;

-- =====================================================================
-- 2026-08-29: #152 Task 2 — canonical narrative publication read model
-- =====================================================================

CREATE INDEX IF NOT EXISTS narrative_record_publication_record_state_idx
  ON private.narrative_record_publication(source_record_id,status,created_at,id);
CREATE INDEX IF NOT EXISTS source_record_anchor_event_record_state_idx
  ON private.source_record_anchor_event(
    source_record_id,occurrence_id,version DESC,created_at DESC,id DESC
  );
CREATE INDEX IF NOT EXISTS source_record_placement_record_state_idx
  ON private.source_record_placement(source_record_id,id);
CREATE INDEX IF NOT EXISTS source_persona_placement_record_state_idx
  ON private.source_persona_placement(record_placement_id,source_persona_id,id);
CREATE INDEX IF NOT EXISTS source_persona_identity_person_state_idx
  ON private.source_persona_identity(canonical_person_id,source_persona_id)
  WHERE decision_status='accepted';
CREATE INDEX IF NOT EXISTS source_record_revision_event_successor_state_idx
  ON private.source_record_revision_event(
    successor_record_id,predecessor_record_id,relation_kind,version DESC
  );

CREATE OR REPLACE FUNCTION private.narrative_record_labels(
  p_source_record_id uuid
) RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path=pg_catalog
AS $$
DECLARE
  v_source_label text;
  v_record_key text;
  v_record_order integer;
  v_page_label text;
  v_record_label text;
  v_citation_label text;
  v_binding_record_label text;
  v_binding_citation_label text;
  v_placement_count integer;
BEGIN
  SELECT coalesce(source.udgave,source.titel),record.record_key
    INTO v_source_label,v_record_key
    FROM private.source_record record
    JOIN public.source source ON source.id=record.source_id
   WHERE record.id=p_source_record_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_NOT_FOUND';
  END IF;

  SELECT min(interval.page_from),
         string_agg(interval.page_label,', ' ORDER BY interval.page_from,interval.page_to)
    INTO v_record_order,v_page_label
    FROM (
      SELECT DISTINCT occurrence.page_from,occurrence.page_to,
             CASE WHEN occurrence.page_from=occurrence.page_to
                  THEN occurrence.page_from::text
                  ELSE occurrence.page_from::text||'-'||occurrence.page_to::text
              END AS page_label
        FROM private.source_record_anchor_current anchor
        JOIN private.source_record_occurrence occurrence
          ON occurrence.id=anchor.occurrence_id
       WHERE anchor.source_record_id=p_source_record_id
         AND anchor.decision_status='accepted'
    ) interval;

  SELECT count(*),min(entry.label)
    INTO v_placement_count,v_record_label
    FROM private.source_record_placement_current placement
    JOIN public.lineage_scheme_entry entry ON entry.id=placement.scheme_entry_id
   WHERE placement.source_record_id=p_source_record_id
     AND placement.decision_status='accepted';
  IF v_placement_count<>1 THEN
    v_record_label:=v_record_key;
  END IF;
  v_citation_label:=CASE WHEN v_page_label IS NULL THEN NULL
                         ELSE v_source_label||', s. '||v_page_label END;

  SELECT binding.record_label,binding.citation_label
    INTO v_binding_record_label,v_binding_citation_label
    FROM private.narrative_record_publication binding
   WHERE binding.source_record_id=p_source_record_id
     AND binding.status IN ('draft','published')
   ORDER BY binding.created_at,binding.id
   LIMIT 1;
  IF FOUND THEN
    v_record_label:=v_binding_record_label;
    v_citation_label:=v_binding_citation_label;
  END IF;

  RETURN jsonb_build_object(
    'record_order',v_record_order,
    'record_label',v_record_label,
    'citation_label',v_citation_label,
    'side',v_page_label
  );
END
$$;

CREATE OR REPLACE FUNCTION private.narrative_publication_state(
  p_person_id bigint,
  p_source_id bigint,
  p_record_key text
) RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path=pg_catalog
AS $$
DECLARE
  v_record private.source_record%ROWTYPE;
  v_source_year integer;
  v_source_label text;
  v_anchors jsonb;
  v_placements jsonb;
  v_identities jsonb;
  v_identity_people jsonb;
  v_identity_count integer;
  v_identity_matches boolean;
  v_revisions jsonb;
  v_provenance jsonb;
  v_provenance_sha256 text;
  v_binding private.narrative_record_publication%ROWTYPE;
  v_binding_person_id bigint;
  v_binding_source_id bigint;
  v_binding_json jsonb;
  v_narrative_json jsonb;
  v_labels jsonb;
  v_authority_kind text;
  v_eligibility_status text;
  v_blocking_reason text;
  v_publication_status text;
  v_person_levende boolean;
  v_person_private boolean;
  v_person_staged boolean;
  v_narrative_private boolean;
  v_person_publication_allowed boolean;
  v_narrative_publication_allowed boolean;
  v_policy jsonb;
  v_has_haendelse boolean;
  v_has_anchor boolean;
BEGIN
  SELECT * INTO v_record
    FROM private.source_record record
   WHERE record.source_id=p_source_id AND record.record_key=p_record_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_NOT_FOUND';
  END IF;

  SELECT source.aar::integer,coalesce(source.udgave,source.titel)
    INTO v_source_year,v_source_label
    FROM public.source source
   WHERE source.id=p_source_id;
  SELECT person.levende,coalesce(person.privat,false),
         coalesce(person.staged,false)
    INTO v_person_levende,v_person_private,v_person_staged
    FROM public.person person
   WHERE person.id=p_person_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_PERSON_NOT_FOUND';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'anchor_event_id',anchor.id,
           'anchor_version',anchor.version,
           'occurrence_id',occurrence.id,
           'rendition_id',rendition.id,
           'rendition_content_sha256',rendition.content_sha256,
           'page_from',occurrence.page_from,
           'page_to',occurrence.page_to,
           'physical_fingerprint',occurrence.physical_fingerprint,
           'structural_fingerprint',occurrence.structural_fingerprint
         ) ORDER BY occurrence.page_from,occurrence.page_to,occurrence.id,anchor.id),'[]'::jsonb),
         count(*)>0
    INTO v_anchors,v_has_anchor
    FROM private.source_record_anchor_current anchor
    JOIN private.source_record_occurrence occurrence ON occurrence.id=anchor.occurrence_id
    JOIN private.source_rendition rendition ON rendition.id=occurrence.rendition_id
   WHERE anchor.source_record_id=v_record.id
     AND anchor.decision_status='accepted';

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'record_placement_id',placement.id,
           'placement_version',placement.version,
           'scheme_entry_id',placement.scheme_entry_id,
           'scheme_entry_label',entry.label,
           'printed_number',placement.printed_number,
           'generation_local',placement.generation_local,
           'generation_global',placement.generation_global,
           'generation_label_raw',placement.generation_label_raw,
           'kuld_label',placement.kuld_label,
           'section_path',to_jsonb(placement.section_path)
         ) ORDER BY entry.sort_order,placement.id),'[]'::jsonb)
    INTO v_placements
    FROM private.source_record_placement_current placement
    JOIN public.lineage_scheme_entry entry ON entry.id=placement.scheme_entry_id
   WHERE placement.source_record_id=v_record.id
     AND placement.decision_status='accepted';

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_persona_id',identity_row.source_persona_id,
           'persona_placement_id',identity_row.persona_placement_id,
           'placement_role',identity_row.placement_role,
           'placement_version',identity_row.placement_version,
           'canonical_person_id',identity_row.canonical_person_id,
           'identity_version',identity_row.identity_version
         ) ORDER BY identity_row.canonical_person_id,identity_row.placement_role,
                    identity_row.source_persona_id,identity_row.persona_placement_id),'[]'::jsonb)
    INTO v_identities
    FROM (
      SELECT persona_placement.source_persona_id,
             persona_placement.id AS persona_placement_id,
             persona_placement.placement_role,
             persona_placement.version AS placement_version,
             identity_state.canonical_person_id,
             identity_state.version AS identity_version
        FROM private.source_persona_placement_current persona_placement
        JOIN private.source_record_placement_current record_placement
          ON record_placement.id=persona_placement.record_placement_id
        JOIN private.source_persona_identity identity_state
          ON identity_state.source_persona_id=persona_placement.source_persona_id
       WHERE record_placement.source_record_id=v_record.id
         AND record_placement.decision_status='accepted'
         AND persona_placement.decision_status='accepted'
         AND persona_placement.placement_role IN ('principal_member','co_principal')
         AND identity_state.decision_status='accepted'
    ) identity_row;

  SELECT coalesce(jsonb_agg(person_id ORDER BY person_id),'[]'::jsonb),count(*),
         count(*)=1 AND min(person_id)=p_person_id
    INTO v_identity_people,v_identity_count,v_identity_matches
    FROM (
      SELECT DISTINCT (identity_item->>'canonical_person_id')::bigint AS person_id
        FROM jsonb_array_elements(v_identities) identity_item
    ) people;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'revision_event_id',revision.id,
           'revision_version',revision.version,
           'relation_kind',revision.relation_kind,
           'predecessor_record_id',revision.predecessor_record_id,
           'successor_record_id',revision.successor_record_id
         ) ORDER BY revision.relation_kind,revision.predecessor_record_id,
                    revision.successor_record_id),'[]'::jsonb)
    INTO v_revisions
    FROM private.source_record_revision_current revision
   WHERE revision.decision_status='accepted'
     AND (revision.predecessor_record_id=v_record.id
          OR revision.successor_record_id=v_record.id);

  v_provenance:=jsonb_build_object(
    'anchors',v_anchors,
    'placements',v_placements,
    'identities',v_identities,
    'revisions',v_revisions
  );
  v_provenance_sha256:=encode(extensions.digest(v_provenance::text,'sha256'),'hex');
  v_labels:=private.narrative_record_labels(v_record.id);

  SELECT binding.*
    INTO v_binding
    FROM private.narrative_record_publication binding
   WHERE binding.source_record_id=v_record.id
     AND binding.status IN ('draft','published')
   ORDER BY binding.created_at,binding.id
   LIMIT 1;

  IF FOUND THEN
    SELECT narrative.subjekt_id,narrative.source_id
      INTO v_binding_person_id,v_binding_source_id
      FROM public.narrative narrative
     WHERE narrative.id=v_binding.narrative_id;
    v_binding_json:=jsonb_build_object(
      'binding_id',v_binding.id,
      'narrative_id',v_binding.narrative_id,
      'binding_person_id',v_binding_person_id,
      'status',v_binding.status,
      'record_label',v_binding.record_label,
      'citation_label',v_binding.citation_label,
      'published_at',CASE WHEN v_binding.published_at IS NULL THEN NULL
        ELSE to_char(
          v_binding.published_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        ) END
    );
    SELECT jsonb_build_object(
             'narrative_id',narrative.id,
             'text',narrative.tekst,
             'text_sha256',encode(extensions.digest(narrative.tekst,'sha256'),'hex'),
             'private',coalesce(narrative.privat,false),
             'side',narrative.side,
             'has_haendelse',EXISTS(
               SELECT 1 FROM public.haendelse event WHERE event.narrative_id=narrative.id
             )
           ),coalesce(narrative.privat,false),EXISTS(
             SELECT 1 FROM public.haendelse event WHERE event.narrative_id=narrative.id
           )
      INTO v_narrative_json,v_narrative_private,v_has_haendelse
      FROM public.narrative narrative
     WHERE narrative.id=v_binding.narrative_id;
  ELSE
    v_binding_json:=NULL;
    v_narrative_json:=NULL;
    v_narrative_private:=NULL;
    v_has_haendelse:=false;
  END IF;

  IF v_binding.id IS NOT NULL
     AND (v_binding_person_id IS DISTINCT FROM p_person_id
          OR v_binding_source_id IS DISTINCT FROM p_source_id) THEN
    v_authority_kind:='conflicting_active_binding';
    v_eligibility_status:='blocked';
    v_blocking_reason:='NARRATIVE_RECORD_ACTIVE_BINDING_CONFLICT';
  ELSIF NOT v_has_anchor THEN
    v_authority_kind:='missing_anchor';
    v_eligibility_status:='blocked';
    v_blocking_reason:='NARRATIVE_RECORD_ANCHOR_REQUIRED';
  ELSIF v_binding.id IS NOT NULL AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_identity_people) item
     WHERE (item #>> '{}')::bigint<>p_person_id
  ) THEN
    v_authority_kind:='conflicting_identity';
    v_eligibility_status:='blocked';
    v_blocking_reason:='NARRATIVE_RECORD_IDENTITY_CONFLICT';
  ELSIF v_binding.id IS NOT NULL THEN
    v_authority_kind:='existing_exact_binding';
    v_eligibility_status:='eligible';
    v_blocking_reason:=NULL;
  ELSIF v_identity_matches THEN
    v_authority_kind:='accepted_identity';
    v_eligibility_status:='eligible';
    v_blocking_reason:=NULL;
  ELSIF v_identity_count=0 THEN
    v_authority_kind:='missing_identity';
    v_eligibility_status:='blocked';
    v_blocking_reason:='NARRATIVE_RECORD_IDENTITY_REQUIRED';
  ELSE
    v_authority_kind:='ambiguous_identity';
    v_eligibility_status:='blocked';
    v_blocking_reason:='NARRATIVE_RECORD_IDENTITY_AMBIGUOUS';
  END IF;

  IF v_binding.id IS NOT NULL AND v_binding_person_id=p_person_id THEN
    v_publication_status:=v_binding.status;
  ELSIF EXISTS (
    SELECT 1
      FROM private.narrative_record_publication withdrawn_binding
      JOIN public.narrative withdrawn_narrative
        ON withdrawn_narrative.id=withdrawn_binding.narrative_id
     WHERE withdrawn_binding.source_record_id=v_record.id
       AND withdrawn_binding.status='withdrawn'
       AND withdrawn_narrative.subjekt_type='person'
       AND withdrawn_narrative.subjekt_id=p_person_id
       AND withdrawn_narrative.source_id=p_source_id
  ) THEN
    v_publication_status:='withdrawn';
  ELSE
    v_publication_status:='none';
  END IF;

  v_person_publication_allowed:=v_person_levende IS FALSE
                                AND NOT v_person_private
                                AND NOT v_person_staged;
  v_narrative_publication_allowed:=v_narrative_json IS NOT NULL
                                   AND NOT coalesce(v_narrative_private,true);
  v_policy:=jsonb_build_object(
    'person_levende',v_person_levende,
    'person_private',v_person_private,
    'person_staged',v_person_staged,
    'narrative_private',v_narrative_private,
    'person_publication_allowed',v_person_publication_allowed,
    'narrative_publication_allowed',v_narrative_publication_allowed,
    'publication_allowed',v_person_publication_allowed
                          AND v_narrative_publication_allowed
  );

  RETURN jsonb_build_object(
    'target',jsonb_build_object(
      'person_id',p_person_id,
      'source_id',p_source_id,
      'record_key',p_record_key,
      'source_record_id',v_record.id,
      'source_record_ref',v_record.public_ref
    ),
    'source',jsonb_build_object(
      'source_year',v_source_year,
      'source_label',v_source_label
    ),
    'provenance',v_provenance,
    'provenance_sha256',v_provenance_sha256,
    'authority',jsonb_build_object(
      'kind',v_authority_kind,
      'identity_people',v_identity_people,
      'eligibility_status',v_eligibility_status,
      'blocking_reason',v_blocking_reason
    ),
    'binding',v_binding_json,
    'narrative',v_narrative_json,
    'publication_status',v_publication_status,
    'labels',v_labels,
    'publication_policy',v_policy,
    'policy_sha256',encode(extensions.digest(v_policy::text,'sha256'),'hex'),
    'has_haendelse',v_has_haendelse
  );
END
$$;

CREATE OR REPLACE FUNCTION private.narrative_record_state(
  p_person_id bigint,
  p_source_id bigint,
  p_record_key text,
  p_lock boolean DEFAULT false
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
SET search_path=pg_catalog
AS $$
DECLARE
  v_record_id uuid;
  v_publication_state jsonb;
  v_publication_state_sha256 text;
  v_active_binding_id uuid;
  v_selected_binding_id uuid;
  v_withdrawn_history jsonb;
  v_latest private.narrative_publication_event%ROWTYPE;
  v_publication_status text;
  v_text_editable boolean;
  v_allowed_actions jsonb;
  v_eligibility_status text;
  v_blocking_reason text;
  v_published_text_sha256 text;
  v_publication_allowed boolean;
  v_editor_state jsonb;
BEGIN
  SELECT record.id INTO v_record_id
    FROM private.source_record record
   WHERE record.source_id=p_source_id AND record.record_key=p_record_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_NOT_FOUND';
  END IF;

  IF p_lock THEN
    PERFORM record.id FROM private.source_record record
     WHERE record.id=v_record_id FOR UPDATE;
    -- Legacy person-policy writers open their audit set before updating person.
    -- After the record-first absence owner, block the legacy allocator before
    -- its max(id)+1 read, then lock person. This makes both writer families use
    -- one compatible audit-before-person order without a stale allocation.
    LOCK TABLE public.change_set IN ACCESS EXCLUSIVE MODE;
    -- levende/privat/staged are part of the semantic policy hash. Serialize
    -- those flags after the record-first absence owner and before projection.
    PERFORM person.id FROM public.person person
     WHERE person.id=p_person_id FOR UPDATE;
    PERFORM binding.id FROM private.narrative_record_publication binding
     WHERE binding.source_record_id=v_record_id
     ORDER BY binding.id FOR UPDATE;
    PERFORM event.id
      FROM private.narrative_publication_event event
     WHERE event.source_record_id=v_record_id
     ORDER BY event.stream_ref,event.stream_version,event.id FOR UPDATE;
    PERFORM narrative.id
      FROM public.narrative narrative
      JOIN public.source source
        ON source.id=narrative.source_id AND source.slags='DAA-udgave'
      JOIN private.narrative_record_publication binding
        ON binding.narrative_id=narrative.id
     WHERE binding.source_record_id=v_record_id
     ORDER BY narrative.id FOR UPDATE OF narrative;
    PERFORM anchor.id
      FROM private.source_record_anchor_event anchor
     WHERE anchor.source_record_id=v_record_id
     ORDER BY anchor.occurrence_id,anchor.version,anchor.id FOR UPDATE;
    PERFORM occurrence.id
      FROM private.source_record_occurrence occurrence
      JOIN private.source_record_anchor_current anchor
        ON anchor.occurrence_id=occurrence.id
     WHERE anchor.source_record_id=v_record_id
     ORDER BY occurrence.id FOR UPDATE OF occurrence;
    PERFORM rendition.id
      FROM private.source_rendition rendition
      JOIN private.source_record_occurrence occurrence
        ON occurrence.rendition_id=rendition.id
      JOIN private.source_record_anchor_current anchor
        ON anchor.occurrence_id=occurrence.id
     WHERE anchor.source_record_id=v_record_id
     ORDER BY rendition.id FOR UPDATE OF rendition;
    PERFORM persona.id
      FROM private.source_persona persona
      JOIN private.source_persona_placement persona_placement
        ON persona_placement.source_persona_id=persona.id
      JOIN private.source_record_placement placement
        ON placement.id=persona_placement.record_placement_id
     WHERE placement.source_record_id=v_record_id
     ORDER BY persona.id FOR UPDATE OF persona;
    PERFORM placement.id FROM private.source_record_placement placement
     WHERE placement.source_record_id=v_record_id ORDER BY placement.id FOR UPDATE;
    PERFORM decision.id
      FROM private.source_record_placement_decision decision
      JOIN private.source_record_placement placement ON placement.id=decision.placement_id
     WHERE placement.source_record_id=v_record_id
     ORDER BY decision.placement_id,decision.version,decision.id FOR UPDATE OF decision;
    PERFORM persona_placement.id
      FROM private.source_persona_placement persona_placement
      JOIN private.source_record_placement placement
        ON placement.id=persona_placement.record_placement_id
     WHERE placement.source_record_id=v_record_id
     ORDER BY persona_placement.id FOR UPDATE OF persona_placement;
    PERFORM identity_state.source_persona_id
      FROM private.source_persona_identity identity_state
      JOIN private.source_persona_placement persona_placement
        ON persona_placement.source_persona_id=identity_state.source_persona_id
      JOIN private.source_record_placement placement
        ON placement.id=persona_placement.record_placement_id
     WHERE placement.source_record_id=v_record_id
     ORDER BY identity_state.source_persona_id FOR UPDATE OF identity_state;
    PERFORM revision.id FROM private.source_record_revision_event revision
     WHERE revision.predecessor_record_id=v_record_id
        OR revision.successor_record_id=v_record_id
     ORDER BY revision.id FOR UPDATE;
  END IF;

  v_publication_state:=private.narrative_publication_state(
    p_person_id,p_source_id,p_record_key
  );
  v_publication_state_sha256:=encode(
    extensions.digest(v_publication_state::text,'sha256'),'hex'
  );
  v_active_binding_id:=(v_publication_state #>> '{binding,binding_id}')::uuid;

  -- stream_version is local to one binding and cannot order replacement
  -- streams. Prefer the active stream; after withdrawal/discard order stream
  -- heads by server-owned change-set allocation, never by transaction-start
  -- binding timestamps. Event/id tie breakers keep the result deterministic.
  IF v_active_binding_id IS NOT NULL THEN
    v_selected_binding_id:=v_active_binding_id;
  ELSE
    SELECT binding.id INTO v_selected_binding_id
      FROM private.narrative_record_publication binding
      JOIN public.narrative narrative ON narrative.id=binding.narrative_id
      JOIN LATERAL (
        SELECT event.created_at,event.change_set_id,event.id
          FROM private.narrative_publication_event event
         WHERE event.binding_id=binding.id
         ORDER BY event.stream_version DESC,event.id DESC
         LIMIT 1
      ) stream_head ON true
     WHERE binding.source_record_id=v_record_id
       AND binding.status='withdrawn'
       AND narrative.subjekt_type='person'
       AND narrative.subjekt_id=p_person_id
       AND narrative.source_id=p_source_id
     ORDER BY stream_head.change_set_id DESC,stream_head.created_at DESC,
              stream_head.id DESC,binding.id DESC
     LIMIT 1;
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'binding_id',binding.id,
           'narrative_id',binding.narrative_id,
           'status',binding.status,
           'text_sha256',encode(extensions.digest(narrative.tekst,'sha256'),'hex'),
           'record_label',binding.record_label,
           'citation_label',binding.citation_label,
           'created_at',to_char(
             binding.created_at AT TIME ZONE 'UTC',
             'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
           )
         ) ORDER BY binding.created_at,binding.id),'[]'::jsonb)
    INTO v_withdrawn_history
    FROM private.narrative_record_publication binding
    JOIN public.narrative narrative ON narrative.id=binding.narrative_id
   WHERE binding.source_record_id=v_record_id
     AND binding.status='withdrawn'
     AND narrative.subjekt_type='person'
     AND narrative.subjekt_id=p_person_id
     AND narrative.source_id=p_source_id;

  SELECT event.* INTO v_latest
    FROM private.narrative_publication_event event
    JOIN private.narrative_record_publication binding ON binding.id=event.binding_id
    JOIN public.narrative narrative ON narrative.id=binding.narrative_id
   WHERE binding.source_record_id=v_record_id
     AND narrative.subjekt_type='person'
     AND narrative.subjekt_id=p_person_id
     AND narrative.source_id=p_source_id
     AND event.binding_id=v_selected_binding_id
   ORDER BY event.stream_version DESC,event.created_at DESC,event.id DESC
   LIMIT 1;

  v_publication_status:=v_publication_state->>'publication_status';
  v_eligibility_status:=v_publication_state #>> '{authority,eligibility_status}';
  v_blocking_reason:=v_publication_state #>> '{authority,blocking_reason}';
  v_publication_allowed:=coalesce((
    v_publication_state #>> '{publication_policy,publication_allowed}'
  )::boolean,false);
  IF v_publication_status='published'
     AND (v_latest.id IS NULL
          OR v_latest.after_state_sha256 IS DISTINCT FROM v_publication_state_sha256) THEN
    v_publication_status:='stale_published';
  END IF;

  IF v_blocking_reason IS NOT NULL THEN
    v_text_editable:=false;
    v_allowed_actions:='[]'::jsonb;
  ELSIF v_publication_status IN ('none','withdrawn') THEN
    v_text_editable:=true;
    v_allowed_actions:='["create_draft"]'::jsonb;
  ELSIF v_publication_status='draft' THEN
    v_text_editable:=true;
    v_allowed_actions:=CASE WHEN v_publication_allowed
      THEN '["save_draft","discard_draft","publish"]'::jsonb
      ELSE '["save_draft","discard_draft"]'::jsonb END;
  ELSIF v_publication_status='published' THEN
    v_text_editable:=v_publication_allowed
                     AND NOT (v_publication_state->>'has_haendelse')::boolean;
    v_allowed_actions:=CASE WHEN NOT v_publication_allowed
      THEN '["withdraw"]'::jsonb WHEN v_text_editable
      THEN '["publish_revision","withdraw"]'::jsonb
      ELSE '["withdraw"]'::jsonb END;
  ELSIF v_publication_status='stale_published' THEN
    v_text_editable:=false;
    v_allowed_actions:=CASE WHEN v_publication_allowed
      THEN '["revalidate","withdraw"]'::jsonb
      ELSE '["withdraw"]'::jsonb END;
  ELSE
    v_text_editable:=false;
    v_allowed_actions:='[]'::jsonb;
  END IF;

  IF v_publication_status IN ('published','stale_published') THEN
    v_published_text_sha256:=v_latest.after_state #>> '{narrative,text_sha256}';
  ELSE
    v_published_text_sha256:=NULL;
  END IF;

  v_editor_state:=jsonb_build_object(
    'publication_state',v_publication_state,
    'publication_state_sha256',v_publication_state_sha256,
    'withdrawn_history',v_withdrawn_history,
    'latest_event_id',v_latest.id,
    'latest_event_type',v_latest.event_type,
    'latest_event_version',v_latest.stream_version,
    'latest_before_state_sha256',v_latest.before_state_sha256,
    'latest_after_state_sha256',v_latest.after_state_sha256,
    'publication_status',v_publication_status,
    'text_editable',v_text_editable,
    'allowed_actions',v_allowed_actions,
    'eligibility_status',v_eligibility_status,
    'blocking_reason',v_blocking_reason,
    'published_text_sha256',v_published_text_sha256
  );
  RETURN v_editor_state||jsonb_build_object(
    'state_sha256',encode(extensions.digest(v_editor_state::text,'sha256'),'hex')
  );
END
$$;

CREATE OR REPLACE FUNCTION private.narrative_legacy_publication_state(
  p_legacy_publication_ref uuid
) RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path=pg_catalog
AS $$
DECLARE
  v_state jsonb;
  v_policy jsonb;
  v_person_levende boolean;
  v_person_private boolean;
  v_person_staged boolean;
  v_narrative_private boolean;
  v_has_haendelse boolean;
BEGIN
  SELECT person.levende,coalesce(person.privat,false),
         coalesce(person.staged,false),coalesce(narrative.privat,false),
         EXISTS(SELECT 1 FROM public.haendelse event WHERE event.narrative_id=narrative.id)
    INTO v_person_levende,v_person_private,v_person_staged,
         v_narrative_private,v_has_haendelse
    FROM private.narrative_legacy_publication legacy
    JOIN public.narrative narrative ON narrative.id=legacy.narrative_id
    JOIN public.person person
      ON person.id=narrative.subjekt_id AND narrative.subjekt_type='person'
   WHERE legacy.legacy_publication_ref=p_legacy_publication_ref;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NARRATIVE_LEGACY_PUBLICATION_NOT_FOUND';
  END IF;

  v_policy:=jsonb_build_object(
    'person_levende',v_person_levende,
    'person_private',v_person_private,
    'person_staged',v_person_staged,
    'narrative_private',v_narrative_private,
    'person_publication_allowed',v_person_levende IS FALSE
                                 AND NOT v_person_private
                                 AND NOT v_person_staged,
    'narrative_publication_allowed',NOT v_narrative_private,
    'publication_allowed',v_person_levende IS FALSE
                          AND NOT v_person_private
                          AND NOT v_person_staged
                          AND NOT v_narrative_private
  );

  SELECT jsonb_build_object(
           'target',jsonb_build_object(
             'legacy_publication_ref',legacy.legacy_publication_ref,
             'narrative_id',narrative.id,
             'person_id',narrative.subjekt_id,
             'source_id',legacy.source_id
           ),
           'source',jsonb_build_object(
             'source_year',source.aar::integer,
             'source_label',coalesce(source.udgave,source.titel)
           ),
           'narrative',jsonb_build_object(
             'narrative_id',narrative.id,
             'text',narrative.tekst,
             'text_sha256',encode(extensions.digest(narrative.tekst,'sha256'),'hex'),
             'private',coalesce(narrative.privat,false),
             'side',narrative.side,
             'has_haendelse',v_has_haendelse
           ),
           'publication_policy',v_policy,
           'policy_sha256',encode(extensions.digest(v_policy::text,'sha256'),'hex'),
           'has_haendelse',v_has_haendelse
         )
    INTO v_state
    FROM private.narrative_legacy_publication legacy
    JOIN public.narrative narrative ON narrative.id=legacy.narrative_id
    JOIN public.source source ON source.id=legacy.source_id
   WHERE legacy.legacy_publication_ref=p_legacy_publication_ref;
  RETURN v_state;
END
$$;

CREATE OR REPLACE FUNCTION private.narrative_legacy_state(
  p_legacy_publication_ref uuid,
  p_lock boolean DEFAULT false
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
SET search_path=pg_catalog
AS $$
DECLARE
  v_legacy private.narrative_legacy_publication%ROWTYPE;
  v_latest private.narrative_publication_event%ROWTYPE;
  v_publication_state jsonb;
  v_publication_state_sha256 text;
  v_baseline_matches boolean;
  v_withdrawal_event_id uuid;
  v_withdrawn_history jsonb;
  v_publication_status text;
  v_allowed_actions jsonb;
  v_eligibility_status text;
  v_blocking_reason text;
  v_editor_state jsonb;
BEGIN
  SELECT * INTO v_legacy
    FROM private.narrative_legacy_publication legacy
   WHERE legacy.legacy_publication_ref=p_legacy_publication_ref;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NARRATIVE_LEGACY_PUBLICATION_NOT_FOUND';
  END IF;

  IF p_lock THEN
    PERFORM legacy.legacy_publication_ref
      FROM private.narrative_legacy_publication legacy
     WHERE legacy.legacy_publication_ref=p_legacy_publication_ref FOR UPDATE;
    PERFORM event.id FROM private.narrative_publication_event event
     WHERE event.legacy_publication_ref=p_legacy_publication_ref
     ORDER BY event.stream_version,event.id FOR UPDATE;
    PERFORM narrative.id FROM public.narrative narrative
     WHERE narrative.id=v_legacy.narrative_id FOR UPDATE;
  END IF;

  v_publication_state:=private.narrative_legacy_publication_state(
    p_legacy_publication_ref
  );
  v_publication_state_sha256:=encode(
    extensions.digest(v_publication_state::text,'sha256'),'hex'
  );
  v_baseline_matches:=v_legacy.baseline_state=v_publication_state
                      AND v_legacy.baseline_sha256=encode(
                        extensions.digest(v_legacy.baseline_state::text,'sha256'),'hex'
                      );
  SELECT event.* INTO v_latest
    FROM private.narrative_publication_event event
   WHERE event.legacy_publication_ref=p_legacy_publication_ref
   ORDER BY event.stream_version DESC,event.created_at DESC,event.id DESC LIMIT 1;
  SELECT event.id INTO v_withdrawal_event_id
    FROM private.narrative_publication_event event
   WHERE event.legacy_publication_ref=p_legacy_publication_ref
     AND event.event_type='legacy_withdrawn'
   ORDER BY event.stream_version DESC,event.id DESC LIMIT 1;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'event_id',event.id,
           'event_type',event.event_type,
           'stream_version',event.stream_version,
           'after_state_sha256',event.after_state_sha256
         ) ORDER BY event.stream_version,event.id),'[]'::jsonb)
    INTO v_withdrawn_history
    FROM private.narrative_publication_event event
   WHERE event.legacy_publication_ref=p_legacy_publication_ref
     AND event.event_type='legacy_withdrawn';

  IF v_legacy.status IN ('withdrawn','migrated') THEN
    v_publication_status:='withdrawn';
    v_allowed_actions:='[]'::jsonb;
    v_eligibility_status:=v_legacy.status;
    v_blocking_reason:=NULL;
  ELSIF NOT v_baseline_matches THEN
    v_publication_status:='stale_published';
    v_allowed_actions:='[]'::jsonb;
    v_eligibility_status:='blocked';
    v_blocking_reason:='NARRATIVE_LEGACY_BASELINE_DRIFT';
  ELSE
    v_publication_status:='published';
    v_allowed_actions:='["withdraw_legacy"]'::jsonb;
    v_eligibility_status:='eligible';
    v_blocking_reason:=NULL;
  END IF;

  v_editor_state:=jsonb_build_object(
    'publication_state',v_publication_state,
    'publication_state_sha256',v_publication_state_sha256,
    'ledger_status',v_legacy.status,
    'baseline_sha256',v_legacy.baseline_sha256,
    'baseline_matches',v_baseline_matches,
    'withdrawal_event_id',v_withdrawal_event_id,
    'withdrawn_history',v_withdrawn_history,
    'latest_event_id',v_latest.id,
    'latest_event_type',v_latest.event_type,
    'latest_event_version',v_latest.stream_version,
    'latest_before_state_sha256',v_latest.before_state_sha256,
    'latest_after_state_sha256',v_latest.after_state_sha256,
    'publication_status',v_publication_status,
    'text_editable',false,
    'allowed_actions',v_allowed_actions,
    'eligibility_status',v_eligibility_status,
    'blocking_reason',v_blocking_reason,
    'published_text_sha256',CASE WHEN v_publication_status IN ('published','stale_published')
      THEN v_legacy.baseline_state #>> '{narrative,text_sha256}' ELSE NULL END
  );
  RETURN v_editor_state||jsonb_build_object(
    'state_sha256',encode(extensions.digest(v_editor_state::text,'sha256'),'hex')
  );
END
$$;

REVOKE ALL ON FUNCTION private.narrative_record_labels(uuid),
  private.narrative_publication_state(bigint,bigint,text),
  private.narrative_record_state(bigint,bigint,text,boolean),
  private.narrative_legacy_publication_state(uuid),
  private.narrative_legacy_state(uuid,boolean)
  FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.red_person_narrative_records(
  p_person_id bigint
) RETURNS TABLE(
  person_id bigint,
  source_id bigint,
  source_year integer,
  source_label text,
  provenance_kind text,
  record_key text,
  source_record_ref uuid,
  legacy_publication_ref uuid,
  record_order integer,
  record_label text,
  citation_label text,
  narrative_id bigint,
  narrative_text text,
  narrative_private boolean,
  narrative_side text,
  publication_status text,
  text_editable boolean,
  allowed_actions jsonb,
  withdrawn_history jsonb,
  latest_event_version integer,
  published_text_sha256 text,
  eligibility_status text,
  blocking_reason text,
  state_sha256 text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog
AS $$
BEGIN
  IF auth.uid() IS NULL OR public.current_rolle()<>'redaktion' THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_ROLE_FORBIDDEN';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT record.id,record.source_id,record.record_key
      FROM private.source_record record
     WHERE EXISTS (
       SELECT 1
         FROM private.narrative_record_publication binding
         JOIN public.narrative narrative ON narrative.id=binding.narrative_id
        WHERE binding.source_record_id=record.id
          AND narrative.subjekt_type='person'
          AND narrative.subjekt_id=p_person_id
          AND narrative.source_id=record.source_id
     )
    UNION
    SELECT DISTINCT record.id,record.source_id,record.record_key
      FROM private.source_record record
      JOIN private.source_record_anchor_current anchor
        ON anchor.source_record_id=record.id AND anchor.decision_status='accepted'
      JOIN private.source_record_placement_current record_placement
        ON record_placement.source_record_id=record.id
       AND record_placement.decision_status='accepted'
      JOIN private.source_persona_placement_current persona_placement
        ON persona_placement.record_placement_id=record_placement.id
       AND persona_placement.decision_status='accepted'
       AND persona_placement.placement_role IN ('principal_member','co_principal')
      JOIN private.source_persona_identity identity_state
        ON identity_state.source_persona_id=persona_placement.source_persona_id
       AND identity_state.decision_status='accepted'
       AND identity_state.canonical_person_id=p_person_id
  ), measured AS (
    SELECT candidate.id,candidate.source_id,candidate.record_key,
           private.narrative_record_state(
             p_person_id,candidate.source_id,candidate.record_key,false
           ) AS state
      FROM candidates candidate
  )
  SELECT p_person_id,
         measured.source_id,
         (measured.state #>> '{publication_state,source,source_year}')::integer,
         measured.state #>> '{publication_state,source,source_label}',
         'source_record'::text,
         measured.record_key,
         (measured.state #>> '{publication_state,target,source_record_ref}')::uuid,
         NULL::uuid,
         (measured.state #>> '{publication_state,labels,record_order}')::integer,
         measured.state #>> '{publication_state,labels,record_label}',
         measured.state #>> '{publication_state,labels,citation_label}',
         CASE WHEN measured.state->>'blocking_reason'=
                        'NARRATIVE_RECORD_ACTIVE_BINDING_CONFLICT'
              THEN NULL::bigint
              ELSE (measured.state #>> '{publication_state,narrative,narrative_id}')::bigint
          END,
         CASE WHEN measured.state->>'blocking_reason'=
                        'NARRATIVE_RECORD_ACTIVE_BINDING_CONFLICT'
              THEN NULL::text
              ELSE measured.state #>> '{publication_state,narrative,text}'
          END,
         CASE WHEN measured.state->>'blocking_reason'=
                        'NARRATIVE_RECORD_ACTIVE_BINDING_CONFLICT'
              THEN NULL::boolean
              ELSE (measured.state #>> '{publication_state,narrative,private}')::boolean
          END,
         CASE WHEN measured.state->>'blocking_reason'=
                        'NARRATIVE_RECORD_ACTIVE_BINDING_CONFLICT'
              THEN NULL::text
              ELSE measured.state #>> '{publication_state,narrative,side}'
          END,
         measured.state->>'publication_status',
         (measured.state->>'text_editable')::boolean,
         measured.state->'allowed_actions',
         coalesce((
           SELECT jsonb_agg(jsonb_build_object(
                    'narrative_id',item->'narrative_id',
                    'status',item->'status',
                    'text_sha256',item->'text_sha256',
                    'record_label',item->'record_label',
                    'citation_label',item->'citation_label',
                    'created_at',item->'created_at'
                  ) ORDER BY item->>'created_at',item->>'narrative_id')
             FROM jsonb_array_elements(measured.state->'withdrawn_history') item
         ),'[]'::jsonb),
         (measured.state->>'latest_event_version')::integer,
         measured.state->>'published_text_sha256',
         measured.state->>'eligibility_status',
         measured.state->>'blocking_reason',
         measured.state->>'state_sha256'
    FROM measured
   ORDER BY (measured.state #>> '{publication_state,labels,record_order}')::integer
              NULLS LAST,
            measured.record_key;

  RETURN QUERY
  WITH measured AS (
    SELECT legacy.legacy_publication_ref,legacy.created_at,
           private.narrative_legacy_state(
             legacy.legacy_publication_ref,false
           ) AS state
      FROM private.narrative_legacy_publication legacy
      JOIN public.narrative narrative ON narrative.id=legacy.narrative_id
     WHERE narrative.subjekt_type='person'
       AND narrative.subjekt_id=p_person_id
  )
  SELECT p_person_id,
         (measured.state #>> '{publication_state,target,source_id}')::bigint,
         (measured.state #>> '{publication_state,source,source_year}')::integer,
         measured.state #>> '{publication_state,source,source_label}',
         'grandfathered_legacy'::text,
         NULL::text,
         NULL::uuid,
         measured.legacy_publication_ref,
         NULL::integer,
         'Overgangsdata — kildepost ikke fastlagt'::text,
         (measured.state #>> '{publication_state,source,source_label}')
           ||CASE WHEN nullif(
                     measured.state #>> '{publication_state,narrative,side}',''
                   ) IS NULL THEN ''
                 ELSE ', s. '||(
                   measured.state #>> '{publication_state,narrative,side}'
                 ) END,
         (measured.state #>> '{publication_state,narrative,narrative_id}')::bigint,
         measured.state #>> '{publication_state,narrative,text}',
         (measured.state #>> '{publication_state,narrative,private}')::boolean,
         measured.state #>> '{publication_state,narrative,side}',
         measured.state->>'publication_status',
         (measured.state->>'text_editable')::boolean,
         measured.state->'allowed_actions',
         measured.state->'withdrawn_history',
         (measured.state->>'latest_event_version')::integer,
         measured.state->>'published_text_sha256',
         measured.state->>'eligibility_status',
         measured.state->>'blocking_reason',
         measured.state->>'state_sha256'
    FROM measured
   ORDER BY measured.created_at,measured.legacy_publication_ref;
END
$$;

CREATE OR REPLACE FUNCTION public.red_person_narrative_publication_history(
  p_person_id bigint
) RETURNS TABLE(
  event_id uuid,
  change_set_id bigint,
  stream_version integer,
  event_type text,
  source_record_ref uuid,
  legacy_publication_ref uuid,
  before_state_sha256 text,
  after_state_sha256 text,
  before_text text,
  after_text text,
  decided_by_name text,
  created_at timestamptz,
  can_reverse boolean,
  blocking_reason text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog
AS $$
BEGIN
  IF auth.uid() IS NULL OR public.current_rolle()<>'redaktion' THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_ROLE_FORBIDDEN';
  END IF;

  RETURN QUERY
  WITH measured AS (
    SELECT event.*,record.public_ref AS safe_source_record_ref,
           CASE WHEN event.source_record_id IS NOT NULL
                THEN private.narrative_record_state(
                  p_person_id,event.source_id,record.record_key,false
                )
                ELSE private.narrative_legacy_state(
                  event.legacy_publication_ref,false
                )
            END AS state
      FROM private.narrative_publication_event event
      JOIN public.narrative narrative ON narrative.id=event.narrative_id
      LEFT JOIN private.source_record record ON record.id=event.source_record_id
     WHERE narrative.subjekt_type='person'
       AND narrative.subjekt_id=p_person_id
  ), classified AS (
    SELECT measured.*,
           measured.state->>'publication_state_sha256' AS current_state_sha256,
           measured.state->>'blocking_reason' AS current_blocking_reason,
           EXISTS(
             SELECT 1 FROM private.narrative_publication_event later
              WHERE later.stream_ref=measured.stream_ref
                AND later.stream_version>measured.stream_version
           ) AS has_later_event,
           EXISTS(
             SELECT 1 FROM private.narrative_publication_event reversal
              WHERE reversal.reversed_event_id=measured.id
           ) AS has_reversal
      FROM measured
  ), reversible AS (
    SELECT classified.*,
           CASE
             WHEN classified.event_type='baseline'
               THEN 'NARRATIVE_PUBLICATION_EVENT_BASELINE_NOT_REVERSIBLE'
             WHEN classified.event_type='reversal'
               THEN 'NARRATIVE_PUBLICATION_REVERSAL_NOT_REVERSIBLE'
             WHEN classified.event_type NOT IN (
                    'draft_created','draft_updated','draft_discarded','published',
                    'published_revision','revalidated','withdrawn','legacy_withdrawn',
                    'legacy_migrated'
                  )
               THEN 'NARRATIVE_PUBLICATION_EVENT_NOT_REVERSIBLE'
             -- #166 149b: samme gate som private.reverse_narrative_publication_event —
             -- en legacy-migration kan først fortrydes, når record-bindingen er
             -- trukket tilbage. Uden denne gren ville fladen tilbyde en knap, RPC'en
             -- afviser.
             WHEN classified.event_type='legacy_migrated' AND EXISTS (
                    SELECT 1 FROM private.narrative_record_publication binding
                     WHERE binding.narrative_id=classified.narrative_id
                       AND binding.status IN ('draft','published')
                  )
               THEN 'NARRATIVE_LEGACY_MIGRATION_BINDING_ACTIVE'
             WHEN classified.has_reversal
               THEN 'NARRATIVE_PUBLICATION_EVENT_ALREADY_REVERSED'
             WHEN classified.has_later_event
               THEN 'NARRATIVE_PUBLICATION_EVENT_NOT_LATEST'
             WHEN classified.current_state_sha256 IS DISTINCT FROM
                    classified.after_state_sha256
               THEN 'NARRATIVE_PUBLICATION_EVENT_STATE_DRIFT'
             WHEN classified.current_blocking_reason IS NOT NULL
               THEN classified.current_blocking_reason
             ELSE NULL
            END AS reversal_blocking_reason
      FROM classified
  )
  SELECT reversible.id,
         reversible.change_set_id,
         reversible.stream_version,
         reversible.event_type,
         reversible.safe_source_record_ref,
         reversible.legacy_publication_ref,
         reversible.before_state_sha256,
         reversible.after_state_sha256,
         reversible.before_state #>> '{narrative,text}',
         reversible.after_state #>> '{narrative,text}',
         reversible.decided_by_name,
         reversible.created_at,
         reversible.reversal_blocking_reason IS NULL,
         reversible.reversal_blocking_reason
    FROM reversible
   ORDER BY reversible.created_at,reversible.id;
END
$$;

REVOKE ALL ON FUNCTION public.red_person_narrative_records(bigint),
  public.red_person_narrative_publication_history(bigint)
  FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.red_person_narrative_records(bigint),
  public.red_person_narrative_publication_history(bigint)
  TO authenticated;
-- =====================================================================
-- 2026-08-29: #152 Task 3 — record-keyed narrative mutation kernel
-- =====================================================================

CREATE OR REPLACE FUNCTION private.mutate_person_narrative_record(
  p_operation text,
  p_person_id bigint,
  p_source_id bigint,
  p_record_key text,
  p_text text,
  p_private boolean,
  p_expected_state_sha256 text
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog
AS $$
DECLARE
  v_actor uuid;
  v_actor_name text;
  v_before_editor jsonb;
  v_before_publication jsonb;
  v_after_editor jsonb;
  v_after_publication jsonb;
  v_before_hash text;
  v_after_hash text;
  v_status text;
  v_blocking_reason text;
  v_source_record_id uuid;
  v_source_record_ref uuid;
  v_binding_id uuid;
  v_narrative_id bigint;
  v_labels jsonb;
  v_latest_event private.narrative_publication_event%ROWTYPE;
  v_event_id uuid;
  v_event_type text;
  v_stream_version integer;
  v_change_set_id bigint;
  v_decision_basis text;
BEGIN
  -- The shared contract gate is deliberately the first lock in every writer.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('daa-narrative-record-contract',0)
  );
  IF public.narrative_record_contract_version()<>2 THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_CONTRACT_INACTIVE';
  END IF;

  v_actor:=auth.uid();
  IF v_actor IS NULL OR public.current_rolle()<>'redaktion' THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_ROLE_FORBIDDEN';
  END IF;
  IF p_operation NOT IN (
    'upsert','publish','revise','revalidate','discard','withdraw'
  ) THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_OPERATION_INVALID';
  END IF;

  -- Task 2 owns record resolution and the complete record-first lock order.
  v_before_editor:=private.narrative_record_state(
    p_person_id,p_source_id,p_record_key,true
  );
  IF p_expected_state_sha256 IS NULL
     OR p_expected_state_sha256 !~ '^[0-9a-f]{64}$'
     OR p_expected_state_sha256 IS DISTINCT FROM
          v_before_editor->>'state_sha256' THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_STATE_STALE';
  END IF;

  v_before_publication:=v_before_editor->'publication_state';
  v_before_hash:=v_before_editor->>'publication_state_sha256';
  v_status:=v_before_editor->>'publication_status';
  v_blocking_reason:=v_before_editor->>'blocking_reason';
  IF v_blocking_reason IS NOT NULL THEN
    RAISE EXCEPTION '%',v_blocking_reason;
  END IF;

  v_source_record_id:=(
    v_before_publication #>> '{target,source_record_id}'
  )::uuid;
  v_source_record_ref:=(
    v_before_publication #>> '{target,source_record_ref}'
  )::uuid;
  v_binding_id:=(
    v_before_publication #>> '{binding,binding_id}'
  )::uuid;
  v_narrative_id:=(
    v_before_publication #>> '{narrative,narrative_id}'
  )::bigint;
  v_labels:=v_before_publication->'labels';
  SELECT event.* INTO v_latest_event
    FROM private.narrative_publication_event event
   WHERE event.id=(v_before_editor->>'latest_event_id')::uuid;

  -- Validate the complete transition before opening its audit set. A rejected
  -- call therefore cannot leave an empty change set behind.
  IF p_operation='upsert' THEN
    IF p_text IS NULL THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_TEXT_REQUIRED';
    END IF;
    IF p_private IS NULL THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PRIVACY_REQUIRED';
    END IF;
    IF v_status='published' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLISHED_REQUIRES_REVISION';
    ELSIF v_status='stale_published' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLICATION_STALE';
    ELSIF v_status='draft' THEN
      v_event_type:='draft_updated';
    ELSIF v_status IN ('none','withdrawn') THEN
      v_event_type:='draft_created';
    ELSE
      RAISE EXCEPTION 'NARRATIVE_RECORD_TRANSITION_INVALID';
    END IF;
  ELSIF p_operation='publish' THEN
    IF v_status<>'draft' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_TRANSITION_INVALID';
    END IF;
    IF NOT coalesce((
      v_before_publication #>> '{publication_policy,publication_allowed}'
    )::boolean,false) THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLICATION_POLICY_BLOCKED';
    END IF;
    v_event_type:='published';
  ELSIF p_operation='revise' THEN
    IF p_text IS NULL THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_TEXT_REQUIRED';
    END IF;
    IF coalesce((v_before_publication->>'has_haendelse')::boolean,false) THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_DERIVED_EVENTS_PRESENT';
    END IF;
    IF v_status='stale_published' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLICATION_STALE';
    ELSIF v_status<>'published' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_TRANSITION_INVALID';
    END IF;
    IF NOT coalesce((
      v_before_publication #>> '{publication_policy,publication_allowed}'
    )::boolean,false) THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLICATION_POLICY_BLOCKED';
    END IF;
    v_event_type:='published_revision';
  ELSIF p_operation='revalidate' THEN
    IF v_status<>'stale_published' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_TRANSITION_INVALID';
    END IF;
    IF NOT coalesce((
      v_before_publication #>> '{publication_policy,publication_allowed}'
    )::boolean,false) THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLICATION_POLICY_BLOCKED';
    END IF;
    IF v_latest_event.id IS NULL THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLICATION_EVENT_MISSING';
    END IF;
    IF v_before_publication #>> '{narrative,text_sha256}' IS DISTINCT FROM
       v_latest_event.after_state #>> '{narrative,text_sha256}' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PUBLICATION_TEXT_DRIFT';
    END IF;
    v_event_type:='revalidated';
  ELSIF p_operation='discard' THEN
    IF v_status<>'draft' THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_TRANSITION_INVALID';
    END IF;
    v_event_type:='draft_discarded';
  ELSIF p_operation='withdraw' THEN
    IF v_status NOT IN ('published','stale_published') THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_TRANSITION_INVALID';
    END IF;
    v_event_type:='withdrawn';
  END IF;

  IF v_before_hash IS DISTINCT FROM encode(
       extensions.digest(v_before_publication::text,'sha256'),'hex'
     ) THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_PRESTATE_HASH_MISMATCH';
  END IF;

  -- A nested caller could otherwise make begin_change_set reuse an unrelated
  -- audit set. The Task-2 lock owner has already serialized change-set
  -- allocation before person-policy rows, following the global writer order.
  IF btrim(coalesce(current_setting('app.change_set_id',true),''))<>'' THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_FOREIGN_CHANGE_SET';
  END IF;
  v_decision_basis:=CASE v_event_type
    WHEN 'draft_created' THEN 'Oprettede record-bundet narrativkladde'
    WHEN 'draft_updated' THEN 'Opdaterede record-bundet narrativkladde'
    WHEN 'draft_discarded' THEN 'Kasserede record-bundet narrativkladde'
    WHEN 'published' THEN 'Publicerede record-bundet narrativ'
    WHEN 'published_revision' THEN 'Publicerede revideret record-bundet narrativ'
    WHEN 'revalidated' THEN 'Revaliderede record-bundet narrativpublicering'
    WHEN 'withdrawn' THEN 'Tilbagetrak record-bundet narrativpublicering'
  END;
  v_change_set_id:=public.begin_change_set(
    'narrative_record_'||v_event_type,
    format('%s: person %s, source %s, record %s',
      v_decision_basis,p_person_id,p_source_id,p_record_key),
    'person',p_person_id
  );

  -- Perform exactly the projection mutation selected above, after the change
  -- set is active so narrative INSERT/UPDATE is captured by change_event.
  IF v_event_type='draft_updated' THEN
    UPDATE public.narrative narrative
       SET tekst=p_text,privat=p_private
     WHERE narrative.id=v_narrative_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PROJECTION_MISSING';
    END IF;
  ELSIF v_event_type='draft_created' THEN
    INSERT INTO public.narrative(
      subjekt_type,subjekt_id,source_id,side,tekst,privat
    ) VALUES (
      'person',p_person_id,p_source_id,v_labels->>'side',p_text,p_private
    ) RETURNING id INTO v_narrative_id;
    INSERT INTO private.narrative_record_publication(
      narrative_id,source_record_id,record_label,citation_label,status
    ) VALUES (
      v_narrative_id,v_source_record_id,v_labels->>'record_label',
      v_labels->>'citation_label','draft'
    ) RETURNING id INTO v_binding_id;
  ELSIF v_event_type='published' THEN
    UPDATE private.narrative_record_publication binding
       SET status='published'
     WHERE binding.id=v_binding_id AND binding.status='draft';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PROJECTION_MISMATCH';
    END IF;
  ELSIF v_event_type='published_revision' THEN
    UPDATE public.narrative narrative
       SET tekst=p_text
     WHERE narrative.id=v_narrative_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PROJECTION_MISSING';
    END IF;
  ELSIF v_event_type='draft_discarded' THEN
    UPDATE private.narrative_record_publication binding
       SET status='withdrawn'
     WHERE binding.id=v_binding_id AND binding.status='draft';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PROJECTION_MISMATCH';
    END IF;
  ELSIF v_event_type='withdrawn' THEN
    UPDATE private.narrative_record_publication binding
       SET status='withdrawn'
     WHERE binding.id=v_binding_id AND binding.status='published';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'NARRATIVE_RECORD_PROJECTION_MISMATCH';
    END IF;
  END IF;

  v_after_publication:=private.narrative_publication_state(
    p_person_id,p_source_id,p_record_key
  );
  v_after_hash:=encode(
    extensions.digest(v_after_publication::text,'sha256'),'hex'
  );
  SELECT coalesce(nullif(btrim(profile.navn),''),
                  nullif(btrim(profile.email),''),v_actor::text)
    INTO v_actor_name
    FROM public.profiles profile
   WHERE profile.id=v_actor;
  v_actor_name:=coalesce(v_actor_name,v_actor::text);
  SELECT coalesce(max(event.stream_version),0)+1
    INTO v_stream_version
    FROM private.narrative_publication_event event
   WHERE event.stream_ref=v_binding_id;
  INSERT INTO private.narrative_publication_event(
    change_set_id,stream_ref,stream_version,event_type,binding_id,narrative_id,
    source_id,source_record_id,decision_basis,before_state,after_state,
    before_state_sha256,after_state_sha256,decided_by,decided_by_name
  ) VALUES (
    v_change_set_id,v_binding_id,v_stream_version,v_event_type,v_binding_id,
    v_narrative_id,p_source_id,v_source_record_id,v_decision_basis,
    v_before_publication,v_after_publication,v_before_hash,v_after_hash,
    v_actor,v_actor_name
  ) RETURNING id INTO v_event_id;

  v_after_editor:=private.narrative_record_state(
    p_person_id,p_source_id,p_record_key,false
  );
  IF v_after_editor->>'latest_event_id' IS DISTINCT FROM v_event_id::text
     OR v_after_editor->>'publication_state_sha256' IS DISTINCT FROM v_after_hash
     OR v_after_editor->>'latest_before_state_sha256' IS DISTINCT FROM v_before_hash
     OR v_after_editor->>'latest_after_state_sha256' IS DISTINCT FROM v_after_hash
     OR v_after_editor->'publication_state' IS DISTINCT FROM v_after_publication THEN
    RAISE EXCEPTION 'NARRATIVE_RECORD_EVENT_APPEND_MISMATCH';
  END IF;

  RETURN jsonb_build_object(
    'person_id',p_person_id,
    'source_id',p_source_id,
    'record_key',p_record_key,
    'source_record_ref',v_source_record_ref,
    'event_id',v_event_id,
    'narrative_id',v_narrative_id,
    'status',v_after_editor->>'publication_status',
    'publication_state_sha256',v_after_hash,
    'state_sha256',v_after_editor->>'state_sha256'
  );
END
$$;

CREATE OR REPLACE FUNCTION public.red_upsert_person_narrative_record(
  p_person_id bigint,p_source_id bigint,p_record_key text,
  p_tekst text,p_privat boolean,p_expected_state_sha256 text
) RETURNS jsonb
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog
AS $$
  SELECT private.mutate_person_narrative_record(
    'upsert',p_person_id,p_source_id,p_record_key,p_tekst,p_privat,
    p_expected_state_sha256
  )
$$;

CREATE OR REPLACE FUNCTION public.red_publicer_person_narrative_record(
  p_person_id bigint,p_source_id bigint,p_record_key text,
  p_expected_state_sha256 text
